// parse robusto: aceita "24,90", "24.90", "1.234,56", "R$ 24,90", vazio => 0
function num(v){
  if(v===null || v===undefined || v==='') return 0;
  let s = String(v).replace(/\s/g, ''); // Remove todos os espaços
  s = s.replace(/[^\d.,-]/g, ''); // Remove letras e símbolos como R, $ (mantém números, ponto, vírgula e negativo)
  if(s.includes(',') && s.includes('.')){
    s = s.replace(/\./g, '').replace(',', '.');
  } else if(s.includes(',')){
    s = s.replace(',', '.'); // BR para US
  }
  const n = parseFloat(s);
  return isNaN(n) ? 0 : n;
}
// Dinheiro DIGITADO em campo de texto: "1.500" é mil e quinhentos (jeito
// brasileiro), não 1,5. Só vale pra texto digitado e só no formato exato
// de milhar — por isso não mexe no num(), que também lê pesos como 0.125.
function numBR(v){
  if(typeof v === 'string'){
    const t = v.replace(/\s|R\$/g, '');
    if(!t.includes(',') && /^-?[1-9]\d{0,2}(\.\d{3})+$/.test(t)) return parseFloat(t.replace(/\./g,''));
  }
  return num(v);
}
// formata em Real brasileiro
const BRL = new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});
const money = n => BRL.format(isFinite(n)?n:0);
const pct = n => (isFinite(n)?n:0).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%';

// escapa texto do usuário antes de injetar em innerHTML (evita quebra/injeção)
function esc(s){ return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
// normaliza texto pra busca: sem acento, minúsculo
function norm(s){ return String(s==null?'':s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(); }
// ID único e monotônico (evita colisão de Date.now() em cadastros rápidos)
/* Data "de calendário" no fuso de quem usa. toISOString() devolve UTC: no
   Brasil, depois das 21h ele já é o dia seguinte — venda do dia 30 às 22h
   caía no mês seguinte. Toda data de calendário passa por aqui. */
function isoLocal(d){
  d = d instanceof Date ? d : new Date(d == null ? Date.now() : d);
  const z = n => String(n).padStart(2,'0');
  return d.getFullYear() + '-' + z(d.getMonth()+1) + '-' + z(d.getDate());
}
function hojeLocal(){ return isoLocal(new Date()); }
// Checagem de permissão dentro da própria ação. Esconder o botão não basta:
// a função continua acessível pelo menu de três pontinhos ou pelo console.
function precisa(chave, msg){
  if(typeof pode !== 'function' || pode(chave)) return true;
  toast(msg || 'Sua conta não tem permissão para isso', 'warn');
  return false;
}
function veCustoAgora(){ return (typeof pode !== 'function') || pode('custos'); }
function corSegura(c){ return /^#[0-9a-fA-F]{3,8}$/.test(String(c||'')) ? c : '#888888'; }
/* Id que vai dentro de onclick="fn('...')". Os ids do sistema são sempre
   letras, números, hífen e sublinhado (uid() / randomUUID). Qualquer outra
   coisa só chegaria aqui por dado adulterado — e seria código rodando no
   navegador de quem abrir a tela. Então fica só o que é permitido. */
function jsId(v){
  const orig = String(v == null ? '' : v);
  const limpo = orig.replace(/[^A-Za-z0-9_-]/g, '');
  // se precisou limpar, o id foi adulterado: não pode acabar apontando pra
  // outro registro legítimo (ex.: "c1'" virando "c1") — então não aponta pra nada
  return limpo === orig ? limpo : '__id_invalido__';
}
// Campos de data que já nascem com "hoje". Se o sistema ficar aberto
// de um dia pro outro, eles continuavam no dia antigo. Ao abrir a tela,
// se a pessoa não mexeu no campo, ele volta pra hoje.
function renovarDatasPadrao(){
  ['s_data','ex_data','mk_data'].forEach(id => {
    const el = document.getElementById(id); if(!el) return;
    if(!el.dataset.auto || el.value === el.dataset.auto){
      el.value = hojeLocal(); el.dataset.auto = el.value;
    }
  });
}
function uid() { return (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : (Date.now().toString(36) + Math.random().toString(36).substr(2, 5)); }

function toast(msg,type){
  if(type==='warn'){toastRaw(msg,type);return;}
  queueMicrotask(()=>{if(!Cloud.deferToast(msg,type))toastRaw(msg,type);});
}
function toastRaw(msg,type){
  const t=$('toast'); t.textContent=msg; t.className='show '+(type||'');
  clearTimeout(t._t); t._t=setTimeout(()=>t.className='',2200);
}

