/* Uma ação de dinheiro mexe em venda, estoque, pedido e caixa ao mesmo
   tempo. Em vez de cada função lembrar de repintar as telas certas, todas
   chamam isto: as abas ficam sempre contando a mesma história. */
function atualizarTudo(){
  // Só a tela que está aberta. As outras são redesenhadas pelo ON_SHOW na hora
  // em que forem abertas, então continuam contando a mesma história — e com
  // catálogo grande isso tirava quase 1 segundo de travada por ação.
  // Só redesenha LISTAS e números — nunca limpa formulário que a pessoa está
  // preenchendo (a rotina de abrir a tela de Vendas, por exemplo, zera a peça).
  const REDESENHA = {
    dash: () => renderDashboard(),   sales: () => renderSales(),
    quote: () => renderQuoteList(),  prod: () => renderProducts(),
    fin: () => renderFinance(),      clients: () => renderClientsList(),
    ecom: () => renderMarketplaces(), consig: () => renderConsigList(),
    fil: () => renderFilaments(),    rep: () => renderRelatorios(),
    audit: () => renderAudit()
  };
  const aberta = document.querySelector('.view.active')?.id?.replace('view-','');
  try{ if(aberta && REDESENHA[aberta]) REDESENHA[aberta](); }
  catch(e){ console.error('Erro ao atualizar a tela ' + aberta + ':', e); }
  try{ mascAtualizar(false); }catch(e){ console.error('Erro no assistente:', e); }
}

