/* ================================================================
   TRILHA DE AUDITORIA — quem fez o quê, quando
   ================================================================ */
const AUDIT_MAX = 3000;

function autorAtual(){
  return {
    id:   currentUser ? currentUser.id   : '',
    nome: currentUser ? (currentUser.nome || currentUser.login || 'Usuário') : 'Sistema'
  };
}
// carimba o autor e a data de criação num registro novo
function carimbar(obj){
  const a = autorAtual();
  obj.usuarioId   = a.id;
  obj.usuarioNome = a.nome;
  obj.criadoEm    = new Date().toISOString();
  return obj;
}
// grava uma linha na trilha
function registrar(acao, alvo, detalhe, valor){
  const a = autorAtual();
  auditLog.push({
    id: uid(),
    ts: new Date().toISOString(),
    usuarioId: a.id,
    usuario: a.nome,
    acao: acao,          // criou | editou | excluiu | ...
    alvo: alvo,          // Venda | Produto | Despesa | ...
    detalhe: detalhe || '',
    valor: (valor === undefined || valor === null) ? '' : num(valor)
  });
  if(auditLog.length > AUDIT_MAX) auditLog = auditLog.slice(-AUDIT_MAX);
  // Gravação best-effort: se falhar, a venda/lançamento segue normalmente.
  try{ localStorage.setItem(AUDIT_LOCAL, JSON.stringify(auditLog)); }
  catch(e){ console.warn('Trilha de atividade não pôde ser gravada:', e); }
}
