const PERMISSOES_PADRAO = ['dash','calc','quote','sales','prod','clients'];

function permsDoUsuario(u){
  const user = u || currentUser;
  if(!user) return [];
  if(user.perfil === 'ADMIN') return ['*'];
  const p = permissoes[user.id];
  return Array.isArray(p) ? p : PERMISSOES_PADRAO.slice();
}
// pode('sales'), pode('excluir'), ...
function pode(chave){
  const p = permsDoUsuario();
  return p[0] === '*' || p.includes(chave);
}
