const LOCAIS_DEF = [
  { key:'oficina', nome:'Oficina' },
  { key:'ml',      nome:'ML Full' },
  { key:'shopee',  nome:'Shopee Full' }
];

// Migração: peça sem repartição joga o estoque todo no local do rótulo antigo
function migraLocais(p){
  if(!p) return p;
  if(!p.locais || typeof p.locais !== 'object'){
    const destino = (p.local === 'ML Full') ? 'ml'
                  : (p.local === 'Shopee Full' || p.local === 'Shopee') ? 'shopee'
                  : 'oficina';
    p.locais = { oficina:0, ml:0, shopee:0 };
    p.locais[destino] = num(p.estoque)||0;
  }else{
    LOCAIS_DEF.forEach(l => { p.locais[l.key] = num(p.locais[l.key])||0; });
  }
  return p;
}
products.forEach(migraLocais);
save('knx3d_products', products);

function estoqueLocal(p, key){ return (p && p.locais) ? (num(p.locais[key])||0) : 0; }
function estoqueProprio(p){ return LOCAIS_DEF.reduce((s,l)=>s+estoqueLocal(p,l.key), 0); }
function syncEstoque(p){ p.estoque = estoqueProprio(p); return p.estoque; }

// Peças em poder de parceiros: somadas dos termos ATIVOS. Nunca digitadas.
function consignadoDe(p){
  let lista;
  try{ lista = consignments; }catch(e){ return 0; }   // ainda não carregado no boot
  if(!p || !Array.isArray(lista)) return 0;
  let t = 0;
  lista.forEach(c => {
    if(c.status === 'Acertado') return;
    (c.itens||[]).forEach(it => {
      const bate = it.prodId ? String(it.prodId) === String(p.id) : it.nome === p.nome;
      if(!bate) return;
      t += Math.max(0, (num(it.qtd)||0) + (num(it.qtdReposta)||0)
                     - (num(it.qtdVendida)||0) - (num(it.qtdDevolvida)||0));
    });
  });
  return t;
}

// Total que é seu, esteja onde estiver
function estoqueTotalPeca(p){ return estoqueProprio(p) + consignadoDe(p); }

// Entrada e baixa em um local específico (mantêm p.estoque coerente)
function entradaLocal(p, key, qtd){
  migraLocais(p);
  p.locais[key] = estoqueLocal(p, key) + (num(qtd)||0);
  return syncEstoque(p);
}
function baixaLocal(p, key, qtd){
  migraLocais(p);
  const real = Math.min(estoqueLocal(p, key), num(qtd)||0);
  p.locais[key] = estoqueLocal(p, key) - real;
  syncEstoque(p);
  return real;   // quanto realmente saiu
}
