/* ---------- navegação por abas ---------- */
let previousTab = null;   // {g,t} da ÚNICA aba anterior — sempre SUBSTITUI, nunca empilha
let isGoingBack = false;

function pushHistory() {
  if (isGoingBack) return;
  const activeG = document.querySelector('nav.tabs button.active');
  const activeT = document.querySelector('.view.active');
  if (activeG && activeT) {
    const g = activeG.dataset.g;
    const t = activeT.id.replace('view-', '');
    previousTab = { g, t };
    const btnVoltar = $('btn_voltar');
    if (btnVoltar) btnVoltar.style.display = 'inline-block';
  }
}

const btnVoltar = $('btn_voltar');
if (btnVoltar) {
  btnVoltar.onclick = () => {
    if (previousTab) {
      isGoingBack = true;
      const dest = previousTab;
      previousTab = null;
      showTab(dest.t);
      isGoingBack = false;
      btnVoltar.style.display = 'none';
    }
  };
}

