// libera a aba para o perfil atual
function tabPermitida(tid){
  if(tid === 'users' || tid === 'audit') return !!(currentUser && currentUser.perfil === 'ADMIN');
  if(!currentUser) return true;
  if(currentUser.perfil === 'ADMIN') return true;
  return pode(tid);
}
// grupo ao qual uma aba pertence
function grupoDaTab(tid){
  const g = NAV.find(x => x[2].some(t => t[0] === tid));
  return g ? g[0] : 'painel';
}
// primeira aba permitida de um grupo
function primeiraTab(gid){
  const g = NAV.find(x => x[0] === gid) || NAV[0];
  const t = g[2].filter(t => tabPermitida(t[0]));
  return t.length ? t[0][0] : 'dash';
}

function buildGroups(){
  // Aplica a classe CSS para ocultar botões de exclusão se for Vendedor
  document.body.classList.toggle('is-vendedor', !pode('excluir'));
  document.body.classList.toggle('sem-custos', !pode('custos'));

  // menu único, sempre visível — sem sanfona
  const gruposVazio = $('nav-groups');
  if(gruposVazio){ gruposVazio.innerHTML=''; gruposVazio.style.display='none'; }

  let html = '';
  NAV.forEach(g => {
    const itens = g[2].filter(t => tabPermitida(t[0]));
    if(!itens.length) return;
    html += `<div class="navgroup">${g[1]}</div>`;
    html += itens.map(t => `<button data-t="${t[0]}" data-g="${g[0]}">${t[1]}</button>`).join('');
  });
  const nav = $('nav-subtabs');
  nav.innerHTML = html;
  nav.querySelectorAll('button').forEach(b => b.onclick = () => showTab(b.dataset.t));
}
// mantida para compatibilidade: abre a primeira aba do grupo
function showGroup(gid){ showTab(primeiraTab(gid)); }

function showTab(tid){
  // Bloqueio de segurança extra (evita acesso forçado via console)
  if(!tabPermitida(tid)) return;

  $('nav-subtabs').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.t===tid));
  document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));
  const view=$('view-'+tid); if(view) view.classList.add('active');
  try{ renovarDatasPadrao(); }catch(e){}
  if(ON_SHOW[tid]) ON_SHOW[tid]();
  // formata o que já estava salvo nos campos desta tela
  if(view && typeof formatarCamposExistentes === 'function') formatarCamposExistentes(view);
}
// abre uma aba específica a partir de qualquer lugar
function goTo(gid,tid){ pushHistory(); showTab(tid || primeiraTab(gid)); }

/* ================================================================
   MOTOR DE PRECIFICAÇÃO — coração do sistema (§4 do manuscrito)
   ================================================================ */
function calcular(inp){
  const qtd    = Math.max(1, Math.round(num(inp.qtd) || 1));
  const gramas = num(inp.gramas) / qtd;
  const horas  = num(inp.horas) / qtd;
  const min    = num(inp.min) / qtd;
  const extras = num(inp.extras) / qtd;
  const margem = num(inp.margem);      // % sobre o PREÇO
  const plat   = num(inp.plataforma);  // % taxa marketplace

  // impressora e filamento escolhidos definem potência/máquina e preço do material
  const pr  = printers.find(p=>String(p.id)===String(inp.printerId));
  const fil = filaments.find(f=>String(f.id)===String(inp.filamentId));
  const prkg = fil ? fil.prkg : cfg.prkg;
  const pot  = pr  ? pr.pot   : cfg.pot;
  const maq  = pr  ? pr.maq   : cfg.maq;

  // --- 5 blocos de custo ---
  const custo_material = gramas * (prkg / 1000);      // R$/g
  const custo_energia  = horas * pot * cfg.kwh;
  const custo_maquina  = horas * maq;
  const custo_mao_obra = (min / 60) * cfg.hora;
  const custo_extras   = extras;

  const subtotal      = custo_material + custo_energia + custo_maquina + custo_mao_obra + custo_extras;
  const reserva_falha = subtotal * (cfg.falha / 100);
  const custo_total   = subtotal + reserva_falha;

  // margem SOBRE O PREÇO: preco = custo / (1 - margem)
  const mFrac = Math.min(Math.max(margem/100,0),0.99); // trava < 100%
  let preco_venda = mFrac<1 ? custo_total / (1 - mFrac) : custo_total;

  // taxa de plataforma opcional
  const pFrac = Math.min(Math.max(plat/100,0),0.99);
  const preco_final = pFrac>0 ? preco_venda / (1 - pFrac) : preco_venda;

  // CORREÇÃO: O lucro precisa descontar o valor real que a plataforma vai reter
  const valor_plataforma = preco_final * pFrac;
  const lucro   = preco_final - custo_total - valor_plataforma;
  const margReal = preco_final>0 ? (lucro/preco_final)*100 : 0;

  return {custo_material,custo_energia,custo_maquina,custo_mao_obra,custo_extras,
          subtotal,reserva_falha,custo_total,preco_venda:preco_final,lucro,margReal};
}

/* ---------- leitura dos campos da calculadora ---------- */
function readCalc(){
  return {
    nome:$('c_nome').value, categoria:$('c_categoria').value,
    qtd:$('c_qtd').value,
    gramas:$('c_gramas').value, horas:$('c_horas').value,
    min:$('c_min').value, extras:$('c_extras').value,
    margem:$('c_margem').value, plataforma:$('c_plataforma').value,
    printerId:$('c_printer').value, filamentId:$('c_filament').value
  };
}

/* ---------- render da calculadora ---------- */
const BLOCOS = [
  ['custo_material','Material',      'var(--c-material)'],
  ['custo_energia', 'Energia',       'var(--c-energia)'],
  ['custo_maquina', 'Máquina',       'var(--c-maquina)'],
  ['custo_mao_obra','Mão de obra',   'var(--c-mao)'],
  ['custo_extras',  'Acessórios',    'var(--c-extras)'],
  ['reserva_falha', 'Reserva falha', 'var(--c-falha)'],
];

function renderCalc(){
  const r = calcular(readCalc());

  $('r_preco').textContent  = money(r.preco_venda);
  $('r_lucro').textContent  = money(r.lucro);
  $('r_margpct').textContent= pct(r.margReal);

  // detalhamento
  let html='';
  BLOCOS.forEach(([k,label,color])=>{
    html+=`<div class="line"><span class="swatch" style="background:${color}"></span>
      <span class="name">${label}</span><span class="amt">${money(r[k])}</span></div>`;
  });
  html+=`<div class="line total"><span class="name">Custo total</span>
    <span class="amt">${money(r.custo_total)}</span></div>`;
  $('r_break').innerHTML=html;

  // SIGNATURE: pilha proporcional dos 5 blocos + reserva
  const base = r.custo_total || 1;
  let stack='';
  BLOCOS.forEach(([k,label,color])=>{
    const w=(r[k]/base)*100;
    if(w>0) stack+=`<span style="width:${w}%;background:${color}" title="${label}: ${money(r[k])}"></span>`;
  });
  $('r_stack').innerHTML=stack;
  const qtdMesa = Math.max(1, Math.round(num($('c_qtd').value) || 1));
  if (qtdMesa > 1) {
    $('r_lbl_unit').textContent = '(Unitário)';
    $('r_total_mesa').style.display = 'block';
    $('r_qtd_mesa').textContent = qtdMesa;
    $('r_preco_mesa').textContent = money(r.preco_venda * qtdMesa);
    $('r_custo_mesa').textContent = money(r.custo_total * qtdMesa);
  } else {
    $('r_lbl_unit').textContent = 'sugerido';
    $('r_total_mesa').style.display = 'none';
  }
  return r;
}

// recálculo ao vivo
['c_qtd','c_gramas','c_horas','c_min','c_extras','c_margem','c_plataforma']
  .forEach(id=>$(id).addEventListener('input',renderCalc));
['c_printer','c_filament'].forEach(id=>$(id).addEventListener('change',renderCalc));

/* ---------- foto do produto ----------
   Comprime pra thumbnail (máx 320px, JPEG) antes de salvar no localStorage,
   pra não estourar o limite de armazenamento. */
let currentFoto = '';
function compressImage(file, maxSize, cb){
  const img = new Image();
  img.onload = ()=>{
    let w=img.width, h=img.height;
    if(w>h && w>maxSize){ h=Math.round(h*maxSize/w); w=maxSize; }
    else if(h>maxSize){ w=Math.round(w*maxSize/h); h=maxSize; }
    const cv=document.createElement('canvas'); cv.width=w; cv.height=h;
    cv.getContext('2d').drawImage(img,0,0,w,h);
    cb(cv.toDataURL('image/jpeg',0.75));
  };
  img.onerror=()=>cb('');
  const rd=new FileReader(); rd.onload=()=>img.src=rd.result; rd.readAsDataURL(file);
}
function updateFotoPreview(){
  const p=$('c_foto_prev');
  if(currentFoto){ p.innerHTML='<img src="'+currentFoto+'" alt="">'; $('c_foto_del').style.display=''; }
  else{ p.innerHTML='<span class="photo-empty">sem foto</span>'; $('c_foto_del').style.display='none'; }
}
$('c_foto_btn').onclick=()=>$('c_foto_file').click();
$('c_foto_file').onchange=e=>{
  const f=e.target.files[0]; if(!f) return;
  compressImage(f,320,url=>{ currentFoto=url; updateFotoPreview(); toast('Foto adicionada','ok'); });
  e.target.value='';
};
$('c_foto_del').onclick=()=>{ currentFoto=''; updateFotoPreview(); };
// thumb: usa a foto do produto se existir, senão o emoji
function prodImg(p, cls){
  return p && p.foto ? '<img class="'+cls+'" src="'+p.foto+'" alt="">' : '';
}

/* ---------- botões da calculadora ---------- */

/* ================================================================
   MODAL DE FORMULÁRIO — abre qualquer cadastro numa janela
   ================================================================ */
let _modalAoFechar = null;

function abrirModal(titulo, corpoHTML, botoes, largura, aoAbrir){
  $('modal-form-title').textContent = titulo;
  $('modal-form-body').innerHTML = corpoHTML;
  $('modal-form-box').className = 'modal-box' + (largura ? ' ' + largura : '');

  const foot = $('modal-form-foot');
  foot.innerHTML = '';
  (botoes || [{ txt:'Fechar', fn: fecharModal }]).forEach(b => {
    const el = document.createElement('button');
    el.type = 'button';
    el.className = 'btn' + (b.cls ? ' ' + b.cls : '');
    el.textContent = b.txt;
    el.onclick = b.fn;
    if(b.id) el.id = b.id;
    foot.appendChild(el);
  });

  $('modal-form').classList.add('active');
  _modalAoFechar = null;

  if(typeof formatarCamposExistentes === 'function') formatarCamposExistentes($('modal-form-body'));
  if(typeof aoAbrir === 'function'){ try{ aoAbrir(); }catch(e){ console.error(e); } }

  // foca o primeiro campo
  setTimeout(()=>{
    const primeiro = $('modal-form-body').querySelector('input:not([type=hidden]), select, textarea');
    if(primeiro) primeiro.focus();
  }, 60);
}

function fecharModal(){
  $('modal-form').classList.remove('active');
  if(typeof _modalAoFechar === 'function'){ const f=_modalAoFechar; _modalAoFechar=null; f(); }
}

// Enter salva, Esc fecha
(function(){
  const ov = $('modal-form');
  if(!ov) return;
  $('modal-form-x').onclick = fecharModal;
  ov.addEventListener('mousedown', e => { if(e.target === ov) fecharModal(); });
  ov.addEventListener('keydown', e => {
    if(e.key === 'Escape'){ e.preventDefault(); fecharModal(); return; }
    if(e.key === 'Enter' && e.target.tagName !== 'TEXTAREA'){
      const salvar = $('modal-form-foot').querySelector('.btn.primary');
      if(salvar){ e.preventDefault(); salvar.click(); }
    }
  });
})();

/* Abre um formulário que já existe na página dentro do modal.
   Move os nós de verdade (não copia), então todos os listeners continuam valendo.
   Ao fechar, devolve cada nó para o lugar de origem. */
function abrirModalForm(titulo, idCampos, idBotao, largura, aoAbrir){
  const campos = $(idCampos);
  const botao  = idBotao ? $(idBotao) : null;
  if(!campos) return;

  const marcaC = document.createComment('form-home');
  campos.parentNode.insertBefore(marcaC, campos);
  let marcaB = null;
  if(botao){ marcaB = document.createComment('btn-home'); botao.parentNode.insertBefore(marcaB, botao); }

  $('modal-form-title').textContent = titulo;
  $('modal-form-box').className = 'modal-box' + (largura ? ' ' + largura : '');

  const body = $('modal-form-body');
  body.innerHTML = '';
  body.appendChild(campos);
  campos.style.display = '';

  const foot = $('modal-form-foot');
  foot.innerHTML = '';
  const cancelar = document.createElement('button');
  cancelar.type='button'; cancelar.className='btn'; cancelar.textContent='Cancelar';
  cancelar.onclick = fecharModal;
  foot.appendChild(cancelar);
  if(botao){ botao.classList.add('primary'); botao.style.display=''; foot.appendChild(botao); }

  $('modal-form').classList.add('active');

  _modalAoFechar = () => {
    if(marcaC && marcaC.parentNode){ marcaC.parentNode.insertBefore(campos, marcaC); marcaC.remove(); }
    campos.style.display = 'none';
    if(botao && marcaB && marcaB.parentNode){ marcaB.parentNode.insertBefore(botao, marcaB); marcaB.remove(); botao.style.display='none'; }
  };

  if(typeof formatarCamposExistentes === 'function') formatarCamposExistentes(body);
  if(typeof aoAbrir === 'function'){ try{ aoAbrir(); }catch(e){ console.error(e); } }
  setTimeout(()=>{
    const primeiro = body.querySelector('input:not([type=hidden]):not([type=color]), select, textarea');
    if(primeiro) primeiro.focus();
  }, 60);
}

// helpers de montagem de formulário dentro do modal
function campo(label, inner, unidade){
  return '<div class="field"><label>' + label +
    (unidade ? ' <span class="u">' + unidade + '</span>' : '') + '</label>' + inner + '</div>';
}
function linha(n, ...campos){
  return '<div class="row' + n + '">' + campos.join('') + '</div>';
}

function customPrompt(msg, defaultValue, callback, isText = false) {
  const overlay = $('custom-prompt');
  const input = $('prompt-input');
  const btnOk = $('prompt-ok');
  const btnCancel = $('prompt-cancel');

  $('prompt-msg').innerHTML = msg;
  input.value = defaultValue;
  
  // Ajusta o visual do input dinamicamente (Texto/Senha vs. Dinheiro/Número)
  if (isText) {
    input.inputMode = 'text';
    input.placeholder = 'Nova senha...';
    input.style.color = 'var(--ink)'; // Remove o laranjinha e aplica a cor de texto padrão
  } else {
    input.inputMode = 'decimal';
    input.placeholder = '0,00';
    input.style.color = 'var(--amber)'; // Mantém o laranjinha para os preços
  }
  
  overlay.classList.add('active');
  input.focus();
  setTimeout(()=>input.select(), 50); // slight delay for mobile selection

  const close = () => {
    overlay.classList.remove('active');
    btnOk.onclick = null;
    btnCancel.onclick = null;
    input.onkeypress = null;
  };

  btnOk.onclick = () => {
    close();
    callback(input.value);
  };

  btnCancel.onclick = () => {
    close();
  };

  input.onkeypress = (e) => {
    if (e.key === 'Enter') btnOk.click();
  };
}

function customConfirm(msg, callback) {
  const overlay = $('custom-prompt');
  const input = $('prompt-input');
  const btnOk = $('prompt-ok');
  const btnCancel = $('prompt-cancel');

  $('prompt-msg').innerHTML = msg;
  input.parentNode.style.display = 'none'; // Esconde o campo de texto
  overlay.classList.add('active');

  const close = () => {
    overlay.classList.remove('active');
    btnOk.onclick = null;
    btnCancel.onclick = null;
    input.parentNode.style.display = ''; // Restaura para a calculadora
  };

  btnOk.onclick = () => {
    close();
    callback();
  };

  btnCancel.onclick = () => {
    close();
  };
}

$('btn_manual').onclick=()=>{
  const r=calcular(readCalc());
  const atual = $('r_preco').dataset.rounded ? num($('r_preco').dataset.rounded) : r.preco_venda;
  const msg = 'A calculadora sugeriu <b>R$ ' + num(r.preco_venda).toFixed(2).replace('.', ',') + '</b><br><br>Digite o preço FINAL que você deseja cobrar:';

  customPrompt(msg, num(atual).toFixed(2).replace('.', ','), (novo) => {
    if(novo !== null && novo.trim() !== ''){
      let p = num(novo);
      $('r_preco').textContent=money(p);
      const lucro=p-r.custo_total;
      $('r_lucro').textContent=money(lucro);
      $('r_margpct').textContent=pct(p>0?(lucro/p)*100:0);
      $('r_preco').dataset.rounded=p; // Salva o valor customizado
      toast('Preço manual aplicado!','ok');
    }
  });
};

$('btn_round').onclick=()=>{
  const r=calcular(readCalc());
  // arredonda para valor comercial terminando em ,90
  let p=r.preco_venda;
  let base=Math.floor(p);
  let comercial = (p-base) > 0.45 ? base+0.90 : (base>0? base-0.10 : 0.90);
  if(comercial<p) comercial=base+0.90;
  // guarda como "preço fixo" mostrando no box (não altera custo)
  $('r_preco').textContent=money(comercial);
  const lucro=comercial-r.custo_total;
  $('r_lucro').textContent=money(lucro);
  $('r_margpct').textContent=pct(comercial>0?(lucro/comercial)*100:0);
  $('r_preco').dataset.rounded=comercial;
  toast('Preço arredondado para valor comercial','ok');
};

$('btn_clear').onclick=()=>{
  ['c_nome','c_categoria','c_gramas','c_horas','c_min','c_extras'].forEach(id=>$(id).value='');
  $('c_qtd').value='1';
  $('c_margem').value=cfg.margem; $('c_plataforma').value=cfg.plat;
  currentFoto=''; updateFotoPreview();
  if($('c_printer').options.length) $('c_printer').selectedIndex=0;
  if($('c_filament').options.length) $('c_filament').selectedIndex=0;
  $('btn_save').dataset.editing=''; $('btn_save').textContent='Salvar como produto';
  delete $('r_preco').dataset.rounded;
  renderCalc();
};

/* Peso POR UNIDADE de uma peça.
   Atenção: p.gramas guarda o peso da MESA INTEIRA (é o valor digitado no campo).
   Produtos novos gravam gramasUnit já dividido; produtos antigos caem no
   fallback (gramas / qtdMesa), que corrige o valor sem precisar migrar dado. */
function pesoUnit(p){
  if(!p) return 0;
  if(p.gramasUnit!==undefined && p.gramasUnit!==null) return num(p.gramasUnit)||0;
  const mesa = Math.max(1, Math.round(num(p.qtdMesa)||1));
  return (num(p.gramas)||0) / mesa;
}

$('btn_save').onclick=()=>{
  const inp=readCalc();
  const r=calcular(inp);
  const nome=(inp.nome||'').trim() || 'Peça sem nome';
  const precoFinal = $('r_preco').dataset.rounded ? num($('r_preco').dataset.rounded) : r.preco_venda;
  const editing=$('btn_save').dataset.editing;
  const dados={
    nome, foto:currentFoto||'', categoria:(inp.categoria||'').trim(),
    local: $('c_local') ? $('c_local').value : 'Oficina',
    gramas:num(inp.gramas), horas:num(inp.horas), min:num(inp.min), extras:num(inp.extras),
    margem:num(inp.margem), plataforma:num(inp.plataforma),
    printerId:inp.printerId||0, filamentId:inp.filamentId||0,
    custo:r.custo_total, preco:precoFinal,
    qtdMesa: Math.max(1, Math.round(num(inp.qtd) || 1)),
    // peso POR UNIDADE — p.gramas continua sendo o peso da mesa inteira
    gramasUnit: (num(inp.gramas)||0) / Math.max(1, Math.round(num(inp.qtd) || 1))
  };
  if(editing){
    const i=products.findIndex(p=>String(p.id)===String(editing));
    if(i>=0){ products[i]=Object.assign({}, products[i], dados); }
    $('btn_save').dataset.editing=''; $('btn_save').textContent='Salvar como produto';
    toast('Produto atualizado: '+nome,'ok');
  }else{
    const mesaQtd = Math.max(1, Math.round(num($('c_qtd').value) || 1));
    // A mesa inteira entra no destino escolhido no seletor "Enviar para"
    const destino = ($('c_local') && ['oficina','ml','shopee'].includes($('c_local').value))
      ? $('c_local').value : 'oficina';
    dados.locais = { oficina:0, ml:0, shopee:0 };
    dados.locais[destino] = mesaQtd;
    dados.local = (LOCAIS_DEF.find(l=>l.key===destino)||LOCAIS_DEF[0]).nome;   // rótulo legado
    dados.estoque = mesaQtd;

    // PRODUÇÃO: o filamento é consumido AGORA, na impressão da mesa — nunca na venda.
    // Baixa o peso TOTAL digitado (a mesa inteira), não o peso unitário.
    let msgFil = '';
    const gramasMesa = Math.round((num(inp.gramas)||0)*100)/100;
    if(dados.filamentId && gramasMesa > 0){
      const fil = filaments.find(f=>String(f.id)===String(dados.filamentId));
      if(fil){
        const antes = num(fil.estoque)||0;
        const baixa = Math.min(antes, gramasMesa);
        fil.estoque = antes - baixa;
        save('knx3d_filaments', filaments);
        renderFilaments();
        msgFil = ' · -'+baixa+'g '+fil.marca;
        if(baixa < gramasMesa){
          toast('Rolo '+fil.marca+' zerou · faltaram '+(Math.round((gramasMesa-baixa)*100)/100)+'g','warn');
        }
      }
    }

    const novoProd = Object.assign({id:uid()}, dados);
    products.push(carimbar(novoProd));
    registrar('criou','Produto', novoProd.nome, novoProd.preco);
    logProducao(novoProd, mesaQtd, gramasMesa, dados.filamentId);
    toast('Produto salvo (+'+mesaQtd+' no estoque)'+msgFil+': '+nome,'ok');
  }
  save('knx3d_products',products);
      refreshCategories();
      delete $('r_preco').dataset.rounded;
      
      // AUTO-LIMPEZA: Zera a calculadora e puxa os valores padrão (margem e plataforma)
      $('btn_clear').click();
    };

/* ================================================================
   PRODUTOS
   ================================================================ */
function productCategories(){
  return [...new Set(products.filter(p=>p.ativo!==false).map(p=>(p.categoria||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
}
// preenche o datalist da calculadora e o filtro da aba Produtos
function refreshCategories(){
  const cats=productCategories();
  $('cat_list').innerHTML=cats.map(c=>`<option value="${esc(c)}">`).join('');
  const sel=$('prod-cat-filter'); const prev=sel.value||'__all';
  let opts='<option value="__all">Todas</option>';
  cats.forEach(c=>opts+=`<option value="${esc(c)}">${esc(c)}</option>`);
  if(products.some(p=>!(p.categoria||'').trim())) opts+='<option value="__none">Sem categoria</option>';
  sel.innerHTML=opts;
  sel.value=[...sel.options].some(o=>o.value===prev)?prev:'__all';
}
let prodPage = 1;
function renderProducts(){
  const el=$('prod-list'), pager=$('prod-pager');
  if(!products.length){ el.innerHTML='<div class="empty">Nenhum produto salvo ainda. Calcule uma peça e clique em “Salvar como produto”.</div>'; pager.innerHTML=''; return; }
  const cat=$('prod-cat-filter').value||'__all';

  // 1. Primeiro, separa APENAS os produtos ativos (não excluídos)
  let list = products.filter(p => p.ativo !== false);

  // 2. Depois, aplica o filtro de categoria SOBRE a lista que já está limpa
  if(cat === '__none') {
    list = list.filter(p => !(p.categoria || '').trim());
  } else if(cat !== '__all') {
    list = list.filter(p => (p.categoria || '').trim() === cat);
  }

  // 3. Busca por nome/categoria (ignora acento e maiúsculas)
  const termoBusca = norm($('prod-search') ? $('prod-search').value : '');
  if(termoBusca){
    list = list.filter(p => norm(p.nome).includes(termoBusca) || norm(p.categoria||'').includes(termoBusca));
  }

  if(!list.length){ el.innerHTML='<div class="empty">Nenhum produto encontrado.</div>'; pager.innerHTML=''; return; }

  // 4. Paginação
  const pageSizeVal = $('prod-pagesize') ? $('prod-pagesize').value : '10';
  const pageSize = pageSizeVal==='all' ? list.length : parseInt(pageSizeVal,10);
  const totalPaginas = Math.max(1, Math.ceil(list.length/pageSize));
  if(prodPage > totalPaginas) prodPage = totalPaginas;
  if(prodPage < 1) prodPage = 1;
  const inicio = (prodPage-1)*pageSize;
  const listPag = list.slice(inicio, inicio+pageSize);

  let rows='';
  listPag.forEach(p=>{
    const fil = p.filamentId ? filaments.find(f=>String(f.id)===String(p.filamentId)) : null;
    const filText = p.filamentId ? (fil ? esc(fil.marca + ' ' + (fil.corNome||'')) : '<span style="color:var(--red)">Filamento excluído</span>') : 'Sem material';
    rows+=`<tr>
      <td>${prodImg(p,'prod-thumb')}${esc(p.nome)}</td>
      <td>
    <div style="margin-bottom:4px">${p.categoria?'<span class="badge">'+esc(p.categoria)+'</span>':''}</div>
    <small style="color:var(--ink-dim); font-size:11px">${filText}</small>
    ${p.usuarioNome?'<div class="autor">cadastrado por '+esc(p.usuarioNome)+'</div>':''}
  </td>
      <td class="num" style="white-space:nowrap; text-align:center">
        <div style="display:flex; align-items:center; justify-content:center; gap:2px;">
          <button class="btn small ghost" style="padding:2px 8px; border-color:var(--line)" onclick="changeStock('${jsId(p.id)}', -1)">-</button>
          <span title="Total seu, incluindo o que está com parceiros" style="display:inline-block; width:26px; text-align:center; font-family:var(--mono); font-weight:700">${estoqueTotalPeca(p)}</span>
          <button class="btn small ghost" style="padding:2px 8px; border-color:var(--line)" onclick="changeStock('${jsId(p.id)}', 1)">+</button>
        </div>
        <div style="display:flex; gap:7px; justify-content:center; margin-top:4px; font-family:var(--mono);">${chipsLocais(p)}</div>
        <button class="btn small ghost" style="padding:1px 10px; font-size:10px; margin-top:5px; border-color:var(--line)" onclick="moveStock('${jsId(p.id)}')">Mover</button>
      </td>
      <td class="num">${Math.round(pesoUnit(p)*10)/10} g</td>
      <td class="num">${(num(p.horas)||0)}h${num(p.min)?' '+num(p.min)+'min':''}</td>
      ${veCustoAgora() ? `<td class="num">${money(p.custo)}</td>` : ''}
      <td class="num" style="font-weight:600">${money(p.preco)}</td>
      <td style="white-space:nowrap; width:1%;"><div style="display:flex; justify-content:flex-end; gap:6px;"><button class="btn small" onclick="loadProduct(\'${jsId(p.id)}\','edit')">Editar</button>
        <button class="btn small" onclick="loadProduct(\'${jsId(p.id)}\','copy')">Duplicar</button>
        <button class="btn small danger" onclick="delProduct(\'${jsId(p.id)}\')">Excluir</button>
      </div></td></tr>`;
  });
  el.innerHTML=`<table><thead><tr>
    <th>Peça</th><th>Cat. / Material</th><th class="num" style="text-align:center">Estoque</th><th class="num">Peso</th><th class="num">Tempo</th>
    ${veCustoAgora() ? '<th class="num">Custo</th>' : ''}<th class="num">Preço</th><th class="num">Ações</th>
    </tr></thead><tbody>${rows}</tbody></table>`;

  // 5. Controles de página
  if(totalPaginas <= 1){
    pager.innerHTML = `<small style="color:var(--ink-dim)">${list.length} ${list.length===1?'item':'itens'}</small>`;
  } else {
    pager.innerHTML = `
      <button class="btn small ghost" id="prod-pg-prev" ${prodPage<=1?'disabled':''}>← Anterior</button>
      <small style="color:var(--ink-dim)">Página ${prodPage} de ${totalPaginas} · ${list.length} itens</small>
      <button class="btn small ghost" id="prod-pg-next" ${prodPage>=totalPaginas?'disabled':''}>Próxima →</button>`;
    $('prod-pg-prev').onclick = ()=>{ prodPage--; renderProducts(); };
    $('prod-pg-next').onclick = ()=>{ prodPage++; renderProducts(); };
  }
}
$('prod-cat-filter').addEventListener('change',()=>{ prodPage=1; renderProducts(); });
$('prod-search').addEventListener('input',()=>{ prodPage=1; renderProducts(); });
$('prod-pagesize').addEventListener('change',()=>{ prodPage=1; renderProducts(); });

// Etiquetas de onde estão as peças. Consignado é calculado, por isso vem em âmbar.
function chipsLocais(p){
  const out = LOCAIS_DEF.map(l => {
    const n = estoqueLocal(p, l.key);
    return n > 0 ? `<span style="font-size:10px; color:var(--ink-dim);">${l.nome} ${n}</span>` : '';
  }).filter(Boolean);
  const nc = consignadoDe(p);
  if(nc > 0) out.push(`<span style="font-size:10px; color:var(--amber);" title="Com parceiros (calculado dos termos)">${nc}</span>`);
  return out.length ? out.join('') : '<span style="font-size:10px; color:var(--ink-dim);">—</span>';
}

let currentMoveProd = null;
window.moveStock = id => {
  const p = products.find(x => String(x.id) === String(id));
  if(!p) return;
  migraLocais(p);
  currentMoveProd = id;

  $('mv_subtitle').textContent = p.nome;
  const nc = consignadoDe(p);
  $('mv_saldos').innerHTML =
    LOCAIS_DEF.map(l => `<div style="display:flex; justify-content:space-between; padding:2px 0;"><span>${l.nome}</span><b style="font-family:var(--mono)">${estoqueLocal(p,l.key)}</b></div>`).join('') +
    `<div style="display:flex; justify-content:space-between; padding:2px 0; border-top:1px solid var(--line); margin-top:4px; padding-top:6px;"><span>Com parceiros <small style="color:var(--ink-dim)">(calculado)</small></span><b style="font-family:var(--mono); color:var(--amber);">${nc}</b></div>`;

  const opts = LOCAIS_DEF.map(l => `<option value="${l.key}">${l.nome}</option>`).join('');
  $('mv_de').innerHTML = opts;   $('mv_de').value = 'oficina';
  $('mv_para').innerHTML = opts; $('mv_para').value = 'ml';
  $('mv_qtd').value = '';
  $('modal-move-stock').classList.add('active');
};
$('mv_cancel').onclick = () => { $('modal-move-stock').classList.remove('active'); currentMoveProd = null; };
$('mv_confirm').onclick = () => {
  const p = products.find(x => String(x.id) === String(currentMoveProd));
  if(!p) return;
  const de = $('mv_de').value, para = $('mv_para').value;
  const q = Math.max(0, Math.round(num($('mv_qtd').value)||0));

  if(de === para){ toast('Escolha locais diferentes','warn'); return; }
  if(q <= 0){ toast('Informe a quantidade','warn'); return; }
  const disp = estoqueLocal(p, de);
  if(q > disp){ toast('Há apenas ' + disp + ' un. em ' + LOCAIS_DEF.find(l=>l.key===de).nome, 'warn'); return; }

  // Transferência não cria nem destrói peça: o total continua o mesmo
  baixaLocal(p, de, q);
  entradaLocal(p, para, q);
  save('knx3d_products', products);

  $('modal-move-stock').classList.remove('active');
  currentMoveProd = null;
  renderProducts();
  toast(q + ' un. movidas para ' + LOCAIS_DEF.find(l=>l.key===para).nome, 'ok');
};
window.loadProduct=(id,mode)=>{
  const p=products.find(x=>String(x.id)===String(id)); if(!p) return;
  $('c_nome').value=p.nome; $('c_categoria').value=p.categoria||'';
  // Mostra o local onde está a maior parte das peças (o campo só decide destino de produção nova)
  if($('c_local')){
    migraLocais(p);
    const maior = LOCAIS_DEF.reduce((a,l)=> estoqueLocal(p,l.key) > estoqueLocal(p,a.key) ? l : a, LOCAIS_DEF[0]);
    $('c_local').value = maior.key;
  }
  $('c_qtd').value = p.qtdMesa || '1'; $('c_gramas').value=p.gramas; $('c_horas').value=p.horas;
  $('c_min').value=p.min; $('c_extras').value=p.extras;
  $('c_margem').value=p.margem; $('c_plataforma').value=p.plataforma;
  currentFoto=p.foto||''; updateFotoPreview();
  renderCalcSelects();
  if(p.printerId) $('c_printer').value=p.printerId;
  if(p.filamentId) $('c_filament').value=p.filamentId;
  // 'edit' atualiza o mesmo produto; 'copy' salva como novo
  if(mode==='edit'){ $('btn_save').dataset.editing=id; $('btn_save').textContent='Atualizar produto'; }
  else{ $('btn_save').dataset.editing=''; $('btn_save').textContent='Salvar como produto'; }
  goTo('operacao','calc');
  renderCalc();
  toast(mode==='edit'?'Editando: '+p.nome:'Cópia carregada: '+p.nome,'ok');
};
window.changeStock = (id, delta) => {
  const p = products.find(x => String(x.id) === String(id));
  if(!p) return;

  // Produção entra e sai sempre da Oficina; para os outros locais use o botão Mover
  migraLocais(p);
  const atual = estoqueLocal(p, 'oficina');
  const novo  = Math.max(0, atual + delta);
  const real  = novo - atual;              // variação efetiva (a trava no 0 pode reduzir)
  if(real === 0){ renderProducts(); return; }

  // "+" = produziu a peça  -> tira filamento do rolo
  // "-" = estorno de lançamento -> devolve filamento ao rolo
  const g = Math.round(pesoUnit(p) * Math.abs(real) * 100) / 100;
  if(p.filamentId && g > 0){
    const fil = filaments.find(f => String(f.id) === String(p.filamentId));
    if(fil){
      const antes = num(fil.estoque)||0;
      if(real > 0){
        const baixa = Math.min(antes, g);
        fil.estoque = antes - baixa;
        if(baixa < g) toast('Rolo '+fil.marca+' zerou · faltaram '+(Math.round((g-baixa)*100)/100)+'g','warn');
        else          toast('Produção · -'+baixa+'g '+fil.marca,'ok');
      }else{
        fil.estoque = antes + g;
        toast('Estorno de produção · +'+g+'g '+fil.marca,'warn');
      }
      save('knx3d_filaments', filaments);
      renderFilaments();
    }
  }

  p.locais.oficina = novo;
  syncEstoque(p);
  save('knx3d_products', products);
  // Registra produção (+) e estorno de produção (−) para o histórico
  logProducao(p, real, (real>0 ? g : -g), p.filamentId);
  renderProducts();
};
window.delProduct=id=>{
  customConfirm('Excluir este produto?<br><br><small style="color:var(--ink-soft); font-weight:normal;">As vendas já registradas continuam no histórico.</small>', () => {
    const p = products.find(x=>String(x.id)===String(id));
    if(p) p.ativo = false;
    save('knx3d_products',products);
    registrar('arquivou','Produto', p ? p.nome : id);
    refreshCategories(); renderProducts(); toast('Produto arquivado','warn');
  });
};

