/* ---- Pagamento dividido em duas formas ----
   A Forma 2 é sempre o resto (total - valor da Forma 1), para as duas
   pernas somarem exatamente o valor da venda, sem sobra nem falta. */
function vendaBruto(){
  const p = products.find(x=>String(x.id)===$('s_prod').value);
  const qtd = Math.max(1, Math.round(num($('s_qtd').value)||1));
  const raw = $('s_preco').value.trim();
  const pu  = (raw === '' && p) ? num(p.preco) : numBR(raw);
  const sub = pu * qtd;
  return Math.max(0, sub - getVendaDesconto(sub));
}
function vendaPernas(){
  const pag = $('s_pagamento').value;
  const bruto = vendaBruto();
  if(pag !== 'Dividido') return [{forma: pag, valor: bruto}];
  const v1 = Math.min(bruto, Math.max(0, num($('s_pg1_val').value)||0));
  const v2 = Math.max(0, Math.round((bruto - v1)*100)/100);
  return [{forma:$('s_pg1').value, valor:v1}, {forma:$('s_pg2').value, valor:v2}];
}
function vendaValorPor(forma){
  return vendaPernas().filter(x=>x.forma===forma).reduce((a,x)=>a+x.valor, 0);
}
/* Taxa do cartão convertida para % sobre o TOTAL da venda.
   Assim só a perna do cartão paga taxa, sem alterar saleFeePct/saleNet. */
function taxaCartaoEfetiva(){
  const bruto = vendaBruto();
  const nominal = num($('s_taxacartao').value)||0;
  if(bruto <= 0 || nominal <= 0) return 0;
  return Math.round((vendaValorPor('Cartão') * nominal / bruto) * 10000)/10000;
}

/* ---------- chips: botões que controlam um <select> escondido ---------- */
function montarChips(idChips, idSelect, rotulos){
  const cx = $(idChips), sel = $(idSelect);
  if(!cx || !sel) return;
  cx.innerHTML = [...sel.options].map(o =>
    `<button type="button" data-v="${esc(o.value)}">${esc((rotulos && rotulos[o.value]) || o.textContent)}</button>`
  ).join('');
  cx.querySelectorAll('button').forEach(b => b.onclick = () => {
    sel.value = b.dataset.v;
    sel.dispatchEvent(new Event('change'));
    sincronizarChips(idChips, idSelect);
  });
  sincronizarChips(idChips, idSelect);
  sel.addEventListener('change', () => sincronizarChips(idChips, idSelect));
}
function sincronizarChips(idChips, idSelect){
  const cx = $(idChips), sel = $(idSelect);
  if(!cx || !sel) return;
  cx.querySelectorAll('button').forEach(b => b.classList.toggle('on', b.dataset.v === sel.value));
}

montarChips('chips_canal', 's_canal');
montarChips('chips_pag', 's_pagamento');
montarChips('chips_cartao_tipo', 's_cartao_tipo');
montarChips('chips_bandeira', 's_cartao_bandeira');
montarChips('chips_desc', 's_desc_tipo', { valor:'R$', pct:'%' });

/* ---------- mostra só o que a forma de pagamento pede ---------- */
function updatePagamentoUI(){
  const pag = $('s_pagamento').value;
  const dividido = (pag === 'Dividido');

  $('field_split').style.display = dividido ? 'block' : 'none';

  const formas = dividido ? [$('s_pg1').value, $('s_pg2').value] : [pag];
  const temDinheiro = formas.includes('Dinheiro');
  const temCartao   = formas.includes('Cartão');

  $('field_recebido').style.display = temDinheiro ? 'block' : 'none';
  if(!temDinheiro){ $('s_recebido').value = ''; }

  $('field_cartao_detalhes').style.display = temCartao ? 'block' : 'none';

  // rótulo do campo de dinheiro deixa claro sobre qual parte é o troco
  const lbl = $('lbl_recebido');
  if(lbl){
    lbl.innerHTML = dividido
      ? 'Quanto o cliente deu em dinheiro <span class="u">a parte em dinheiro é ' + money(vendaValorPor('Dinheiro')) + '</span>'
      : 'Quanto o cliente deu <span class="u">R$</span>';
  }

  // segunda parte = o resto
  const pernas = vendaPernas();
  $('s_pg2_val').textContent = money(dividido ? pernas[1].valor : 0);

  // aviso quando a 1ª parte passa do total
  const nota = $('split_nota');
  if(nota && dividido){
    const bruto = vendaBruto();
    const digitado = num($('s_pg1_val').value) || 0;
    if(digitado > bruto && bruto > 0){
      nota.textContent = 'A 1ª parte não pode passar do total de ' + money(bruto) + '.';
      nota.classList.add('erro');
    } else if(pernas[0].valor === 0){
      nota.textContent = 'Digite quanto entrou na 1ª forma. O resto vai para a 2ª.';
      nota.classList.remove('erro');
    } else {
      nota.textContent = money(pernas[0].valor) + ' em ' + $('s_pg1').value +
                         '  +  ' + money(pernas[1].valor) + ' em ' + $('s_pg2').value +
                         '  =  ' + money(vendaBruto());
      nota.classList.remove('erro');
    }
  }

  updateTroco();
  updateLiquido();
  atualizarResumoTaxas();
}
$('s_pagamento').addEventListener('change', updatePagamentoUI);
