/* ---------- taxas: resumo na linha, campos só quando pedir ---------- */
function atualizarResumoTaxas(){
  const el = $('taxas_resumo');
  if(!el) return;
  const bruto = vendaBruto();
  const plat = num($('s_taxaplat').value) || 0;
  const cartaoNominal = num($('s_taxacartao').value) || 0;
  const cartaoEfetiva = taxaCartaoEfetiva();
  const pctTotal = plat + cartaoEfetiva;

  if(pctTotal <= 0){ el.textContent = 'Sem taxa nesta venda.'; return; }

  const partes = [];
  if(plat > 0) partes.push(plat.toLocaleString('pt-BR',{maximumFractionDigits:1}) + '% do canal');
  if(cartaoNominal > 0 && cartaoEfetiva > 0){
    partes.push(cartaoNominal.toLocaleString('pt-BR',{maximumFractionDigits:1}) + '% do cartão');
  }
  el.innerHTML = partes.join(' + ') + ' — descontam <b>' + money(bruto * pctTotal / 100) + '</b>';
}
if($('btn_taxas')) $('btn_taxas').onclick = () => {
  const box = $('box_taxas');
  const aberto = box.style.display !== 'none';
  box.style.display = aberto ? 'none' : 'block';
  $('btn_taxas').textContent = aberto ? 'Ajustar taxas' : 'Ocultar taxas';
};
['s_taxaplat','s_taxacartao'].forEach(id => $(id).addEventListener('input', atualizarResumoTaxas));

function getVendaDesconto(subtotal) {
  const tipo = $('s_desc_tipo').value;
  const val = num($('s_desc_val').value);
  return tipo === 'pct' ? subtotal * (Math.min(val, 100) / 100) : Math.min(val, subtotal);
}

function updateTroco() {
  const p = products.find(x=>String(x.id)===$('s_prod').value);
  const qtd = Math.max(1, Math.round(num($('s_qtd').value)||1));
  
  const rawPreco = $('s_preco').value.trim();
  let precoUnitario = rawPreco === '' && p ? p.preco : numBR(rawPreco);
  const subtotal = precoUnitario * qtd;
  const desconto = getVendaDesconto(subtotal);
  const precoTotal = Math.max(0, subtotal - desconto);
  
  // Na venda dividida, o troco sai só sobre a perna paga em dinheiro
  const aPagarEmDinheiro = ($('s_pagamento').value === 'Dividido')
    ? vendaValorPor('Dinheiro')
    : precoTotal;
  const recebido = num($('s_recebido').value);
  const diferenca = recebido - aPagarEmDinheiro;
  const box = $('field_troco');

  if(recebido > 0 && diferenca < -0.005){
    // o cliente deu menos do que precisa
    $('s_troco_val').textContent = money(Math.abs(diferenca));
    if(box){
      box.querySelector('.k').textContent = 'Ainda falta';
      box.classList.add('falta'); box.classList.remove('tem-troco');
    }
  } else {
    const troco = Math.max(0, diferenca);
    $('s_troco_val').textContent = money(troco);
    if(box){
      box.querySelector('.k').textContent = 'Troco a devolver';
      box.classList.toggle('tem-troco', troco > 0);
      box.classList.remove('falta');
    }
  }
}
