// ---- canal de venda + taxas (líquido = o que cai no caixa) ----
function saleGross(s){ return Math.max(0, (num(s.precoUnit)*num(s.qtd)) - num(s.descontoValor||0)); }
function saleFeePct(s){ return num(s.taxaPlat)+num(s.taxaCartao); }
function saleFee(s){ return saleGross(s)*saleFeePct(s)/100; }
function saleNet(s){ return saleGross(s)-saleFee(s); }

$('s_canal').addEventListener('change',()=>{
  const c=$('s_canal').value;
  if(c==='Mercado Livre') $('s_taxaplat').value=cfg.taxaML;
  else if(c==='Shopee') $('s_taxaplat').value=cfg.taxaShopee;
  else if(c==='Presencial') $('s_taxaplat').value=0;
  // "Outro": mantém o que estiver digitado

  // Sugere o estoque de saída conforme o canal (você pode trocar manualmente)
  if($('s_local')){
    if(c==='Mercado Livre')  $('s_local').value='ml';
    else if(c==='Shopee')    $('s_local').value='shopee';
    else if(c==='Presencial')$('s_local').value='oficina';
    updateLocalSaldo();
  }
  updateLiquido();
  atualizarResumoTaxas();
});

// Mostra ao lado do seletor quanto há disponível naquele local
function updateLocalSaldo(){
  if(!$('s_local')) return;
  const p = products.find(x=>String(x.id)===$('s_prod').value);
  const lbl = $('s_local').parentElement.querySelector('label');
  if(!p || !lbl) return;
  migraLocais(p);
  const n = estoqueLocal(p, $('s_local').value);
  lbl.innerHTML = 'Sair de qual estoque <span class="u" style="color:' + (n>0?'var(--cyan)':'var(--red)') + '">' + n + ' disp.</span>';
}
