$('s_desc_tipo').addEventListener('change', updateLiquido);

function updateLiquido(){
  // Mesmo fallback do updateTroco: campo de preço vazio usa o preço do produto
  const _pLiq = products.find(x=>String(x.id)===$('s_prod').value);
  const _rawLiq = $('s_preco').value.trim();
  const _precoLiq = (_rawLiq==='' && _pLiq) ? num(_pLiq.preco) : numBR(_rawLiq);
  const subtotal = _precoLiq * Math.max(1, Math.round(num($('s_qtd').value)||1));
  const desconto = getVendaDesconto(subtotal);
  const bruto = Math.max(0, subtotal - desconto);
  
  const pct = num($('s_taxaplat').value) + taxaCartaoEfetiva();
  const taxa = bruto * pct / 100;
  const liq = bruto - taxa;
  
  // painel de resumo do PDV
  $('s_item_sub').textContent = money(subtotal);
  $('res_sub').textContent = money(subtotal);

  $('res_desc_ln').style.display = desconto > 0 ? '' : 'none';
  $('res_desc').textContent = '− ' + money(desconto);

  $('res_taxa_ln').style.display = taxa > 0 ? '' : 'none';
  $('res_taxa_lbl').textContent = 'Taxas (' + pct.toLocaleString('pt-BR',{maximumFractionDigits:1}) + '%)';
  $('res_taxa').textContent = '− ' + money(taxa);

  $('res_liq').textContent = money(liq);

  // margem estimada: líquido menos o custo de produção das unidades
  const qtdLiq = Math.max(1, Math.round(num($('s_qtd').value)||1));
  if(_pLiq && subtotal > 0){
    const custo = num(_pLiq.custo) * qtdLiq;
    const lucro = liq - custo;
    const mg = liq > 0 ? (lucro / liq) * 100 : 0;
    $('res_margem_lbl').textContent = 'Lucro estimado';
    $('res_margem').textContent = money(lucro) + '  ·  ' + mg.toLocaleString('pt-BR',{maximumFractionDigits:1}) + '%';
    $('res_margem').style.color = lucro >= 0 ? 'var(--green)' : 'var(--red)';
  } else {
    $('res_margem_lbl').textContent = 'Lucro estimado';
    $('res_margem').textContent = '—';
    $('res_margem').style.color = 'var(--ink-dim)';
  }

  // cabeçalho do item
  const temPeca = !!_pLiq;
  if(temPeca){
    $('s_item_nome').textContent = _pLiq.nome;
    const partes = [];
    if(_pLiq.categoria) partes.push(_pLiq.categoria);
    partes.push('custo ' + money(_pLiq.custo) + '/un');
    partes.push('preço de tabela ' + money(_pLiq.preco));
    $('s_item_meta').textContent = partes.join('  ·  ');
  } else {
    $('s_item_nome').textContent = 'Nenhuma peça escolhida';
    $('s_item_meta').textContent = 'Busque acima e clique na peça que foi vendida.';
  }
  $('s_item').classList.toggle('vazio', !temPeca);

  // sem peça escolhida, não dá para registrar nada
  const botao = $('btn_sale');
  if(botao){
    botao.disabled = !temPeca;
    botao.textContent = temPeca ? 'Registrar venda' : 'Escolha uma peça';
  }
  const resumo = document.querySelector('.resumo');
  if(resumo) resumo.classList.toggle('inativo', !temPeca);
}

/* ================================================================
   BUSCA COM SUGESTÃO — componente reaproveitado em Vendas,
   Orçamento e Consignado. Aguenta catálogo grande sem lista suspensa.
   ================================================================ */
function criarBusca(cfg){
  const input = $(cfg.input);
  const caixa = $(cfg.results);
  if(!input || !caixa) return null;

  let marcado = -1;

  function fonte(){
    const termo = norm(input.value);
    const lista = cfg.itens();
    if(!termo) return lista.slice(0, 8);
    return lista.filter(it => {
      const campos = cfg.campos ? cfg.campos(it) : [it.nome];
      return campos.some(c => norm(c).includes(termo));
    }).slice(0, 30);
  }

  function desenhar(){
    const lista = fonte();
    if(!cfg.itens().length){
      caixa.innerHTML = '<div class="vazio">' + (cfg.vazio || 'Nada cadastrado ainda.') + '</div>';
      return;
    }
    if(!lista.length){
      caixa.innerHTML = '<div class="vazio">Nada encontrado para “' + esc(input.value) + '”.</div>';
      return;
    }
    caixa.innerHTML = lista.map((it,i) => {
      const l = cfg.linha(it);
      return '<button type="button" data-id="' + esc(it.id) + '" class="' + (i===marcado?'sel':'') + '">' +
        '<span class="nm">' + l.nome + (l.extra ? ' <span class="st">· ' + l.extra + '</span>' : '') + '</span>' +
        (l.meio ? '<span class="st">' + l.meio + '</span>' : '') +
        (l.preco ? '<span class="pr">' + l.preco + '</span>' : '') +
      '</button>';
    }).join('');
    caixa.querySelectorAll('button').forEach(b => b.onclick = () => escolher(b.dataset.id));
  }

  function escolher(id){
    const it = cfg.itens().find(x => String(x.id) === String(id));
    if(!it) return;
    cfg.aoEscolher(it);
    input.value = '';
    fechar();
  }

  function abrir(){ marcado = -1; desenhar(); caixa.classList.add('open'); }
  function fechar(){ caixa.classList.remove('open'); marcado = -1; }

  input.addEventListener('focus', abrir);
  input.addEventListener('input', () => { marcado = -1; desenhar(); caixa.classList.add('open'); });
  input.addEventListener('keydown', e => {
    const btns = caixa.querySelectorAll('button');
    if(e.key === 'Escape'){ fechar(); return; }
    if(e.key === 'ArrowDown' || e.key === 'ArrowUp'){
      e.preventDefault();
      if(!btns.length) return;
      marcado += (e.key === 'ArrowDown' ? 1 : -1);
      if(marcado < 0) marcado = btns.length - 1;
      if(marcado >= btns.length) marcado = 0;
      btns.forEach((b,i) => b.classList.toggle('sel', i === marcado));
      btns[marcado].scrollIntoView({block:'nearest'});
      return;
    }
    if(e.key === 'Enter'){
      e.preventDefault();
      if(!btns.length) return;
      const alvo = btns[marcado >= 0 ? marcado : 0];
      if(alvo) escolher(alvo.dataset.id);
    }
  });
  document.addEventListener('mousedown', e => {
    if(!caixa.contains(e.target) && e.target !== input) fechar();
  });

  return { desenhar, abrir, fechar };
}

function produtosAtivos(){ return products.filter(p => p.ativo !== false); }

/* ---------- escolha de cliente com busca (orçamento, consignado, venda) ---------- */
function ligarBuscaCliente(pre, idSelect, aoTrocar){
  const sel = $(idSelect);
  if(!sel || !$(pre + '_busca')) return;

  function mostrarEscolhido(){
    const c = clients.find(x => String(x.id) === String(sel.value));
    const chip = $(pre + '_chip'), wrap = $(pre + '_wrap');
    if(c){
      const detalhe = [c.whatsapp, c.cidade].filter(Boolean).join('  ·  ');
      $(pre + '_nome').innerHTML = esc(c.nome) + (detalhe ? '<small>' + esc(detalhe) + '</small>' : '');
      chip.style.display = 'flex';
      wrap.style.display = 'none';
    } else {
      chip.style.display = 'none';
      wrap.style.display = '';
    }
  }

  criarBusca({
    input: pre + '_busca',
    results: pre + '_results',
    itens: () => clients.slice().sort((a,b)=>String(a.nome||'').localeCompare(String(b.nome||''))),
    campos: c => [c.nome, c.whatsapp || '', c.cpfCnpj || '', c.cidade || '', c.email || ''],
    vazio: 'Nenhum cliente cadastrado ainda.',
    linha: c => ({
      nome: esc(c.nome),
      extra: c.cidade ? esc(c.cidade) : '',
      meio: c.whatsapp ? esc(c.whatsapp) : (c.cpfCnpj ? esc(c.cpfCnpj) : '')
    }),
    aoEscolher: c => {
      sel.value = c.id;
      sel.dispatchEvent(new Event('change'));
      mostrarEscolhido();
      if(typeof aoTrocar === 'function') aoTrocar(c);
    }
  });

  $(pre + '_x').onclick = () => {
    sel.value = '';
    sel.dispatchEvent(new Event('change'));
    mostrarEscolhido();
    $(pre + '_busca').focus();
  };

  // qualquer mudança no select (inclusive por código) atualiza o visual
  sel.addEventListener('change', mostrarEscolhido);
  mostrarEscolhido();
  return { atualizar: mostrarEscolhido };
}


/* ---------- busca de peça no PDV ---------- */
let _pdvSel = -1;

function pdvFiltrar(termo){
  const t = (termo||'').trim().toLowerCase();
  const ativos = products.filter(p => p.ativo !== false);
  if(!t) return ativos.slice(0, 8);
  return ativos.filter(p =>
    (p.nome||'').toLowerCase().includes(t) ||
    (p.categoria||'').toLowerCase().includes(t)
  ).slice(0, 25);
}

function pdvRenderResultados(){
  const cx = $('s_results');
  if(!cx) return;
  const lista = pdvFiltrar($('s_busca').value);
  if(!products.filter(p=>p.ativo!==false).length){
    cx.innerHTML = '<div class="vazio">Nenhuma peça cadastrada ainda.</div>';
    return;
  }
  if(!lista.length){
    cx.innerHTML = '<div class="vazio">Nada encontrado.</div>';
    return;
  }
  cx.innerHTML = lista.map((p,i) => {
    migraLocais(p);
    const est = estoqueTotalPeca(p);
    return '<button type="button" data-id="' + p.id + '" class="' + (i===_pdvSel?'sel':'') + '">' +
      '<span class="nm">' + esc(p.nome) + (p.categoria ? ' <span class="st">· ' + esc(p.categoria) + '</span>' : '') + '</span>' +
      '<span class="st">' + est + ' un.</span>' +
      '<span class="pr">' + money(p.preco) + '</span>' +
    '</button>';
  }).join('');
  cx.querySelectorAll('button').forEach(b => b.onclick = () => pdvEscolher(b.dataset.id));
}

function pdvEscolher(id){
  const p = products.find(x => String(x.id) === String(id));
  if(!p) return;
  $('s_prod').value = p.id;
  $('s_busca').value = '';
  pdvFechar();
  syncSalePrice();
  updateLocalSaldo();
  $('s_qtd').focus();
  $('s_qtd').select();
}

function pdvAbrir(){ _pdvSel = -1; pdvRenderResultados(); $('s_results').classList.add('open'); }
function pdvFechar(){ $('s_results').classList.remove('open'); _pdvSel = -1; }

if($('s_busca')){
  $('s_busca').addEventListener('focus', pdvAbrir);
  $('s_busca').addEventListener('input', () => { _pdvSel = -1; pdvRenderResultados(); $('s_results').classList.add('open'); });
  $('s_busca').addEventListener('keydown', e => {
    const btns = $('s_results').querySelectorAll('button');
    if(e.key === 'Escape'){ pdvFechar(); return; }
    if(e.key === 'ArrowDown' || e.key === 'ArrowUp'){
      e.preventDefault();
      if(!btns.length) return;
      _pdvSel += (e.key === 'ArrowDown' ? 1 : -1);
      if(_pdvSel < 0) _pdvSel = btns.length - 1;
      if(_pdvSel >= btns.length) _pdvSel = 0;
      btns.forEach((b,i) => b.classList.toggle('sel', i === _pdvSel));
      btns[_pdvSel].scrollIntoView({block:'nearest'});
      return;
    }
    if(e.key === 'Enter'){
      e.preventDefault();
      if(!btns.length) return;
      const alvo = btns[_pdvSel >= 0 ? _pdvSel : 0];
      if(alvo) pdvEscolher(alvo.dataset.id);
    }
  });
  document.addEventListener('mousedown', e => {
    const cx = $('s_results');
    if(cx && !cx.contains(e.target) && e.target !== $('s_busca')) pdvFechar();
  });
}

