$('btn_sale').onclick=()=>{
  const p=products.find(x=>String(x.id)===$('s_prod').value);
  if(!p){ toast('Selecione um produto','warn'); return; }
  const qtd=Math.max(1,Math.round(num($('s_qtd').value)||1));
  const preco=numBR($('s_preco').value);
  const canal=$('s_canal').value;
  const taxaPlat=num($('s_taxaplat').value), taxaCartao=taxaCartaoEfetiva();
  const pagPernas = ($('s_pagamento').value === 'Dividido') ? vendaPernas() : null;
  if(pagPernas && pagPernas.some(x=>x.valor <= 0)){
    toast('Informe um valor válido para a Forma 1 (menor que o total)','warn'); return;
  }

  // Pagamento em dinheiro exige o valor recebido, senão não há como conferir o troco
  if($('field_recebido').style.display !== 'none'){
    const recDin  = num($('s_recebido').value) || 0;
    const devidoDin = ($('s_pagamento').value === 'Dividido')
      ? vendaValorPor('Dinheiro') : vendaBruto();
    if(recDin <= 0){
      toast('Informe o valor recebido em dinheiro','warn');
      $('s_recebido').focus(); return;
    }
    if(recDin < devidoDin){
      toast('Valor recebido menor que ' + money(devidoDin) + ' — falta ' + money(devidoDin - recDin),'warn');
      $('s_recebido').focus(); return;
    }
  }
  const data=$('s_data').value||hojeLocal();
  
  const subtotal = preco * qtd;
  const descontoValor = getVendaDesconto(subtotal);
  const pagamento = $('s_pagamento').value;
  const cartaoTipo = pagamento === 'Cartão' ? $('s_cartao_tipo').value : '';
  const cartaoBandeira = pagamento === 'Cartão' ? $('s_cartao_bandeira').value : '';

  // TRAVA DE ESTOQUE: valida contra o estoque DO LOCAL escolhido
  migraLocais(p);
  const localVenda = ($('s_local') && ['oficina','ml','shopee'].includes($('s_local').value))
    ? $('s_local').value : 'oficina';
  const nomeLocal = (LOCAIS_DEF.find(l=>l.key===localVenda)||LOCAIS_DEF[0]).nome;
  const estAtual = estoqueLocal(p, localVenda);
  if(qtd > estAtual){
    toast('Em ' + nomeLocal + ' há apenas ' + estAtual + ' un. de ' + p.nome, 'warn');
    return;
  }

  // O filamento NÃO sai na venda: ele já foi consumido quando a peça foi produzida.
  // gramasBaixa e filId ficam zerados para que excluir a venda não devolva filamento.
  // (vendas ANTIGAS gravaram gramasBaixa > 0 e continuam estornando normalmente)
  let baixa='', gramasBaixa=0, filId=0;
  const clienteVenda = $('s_cliente_sel') ? $('s_cliente_sel').value : '';
  sales.push(carimbar({id:uid(), prodId:p.id, nome:p.nome, ico:p.ico,
    custoUnit:num(p.custo), precoUnit:preco, qtd, data, canal, taxaPlat, taxaCartao,
    descontoValor, pagamento, cartaoTipo, cartaoBandeira,
    filamentId:filId, gramasBaixa, qtdBaixa:qtd, clienteId:clienteVenda,
    pagamentos: pagPernas, taxaCartaoNominal: num($('s_taxacartao').value)||0,
    localBaixa: localVenda}));
  save('knx3d_sales',sales);
  registrar('registrou','Venda', p.nome + ' — ' + qtd + ' un. (' + canal + ')', preco*qtd - descontoValor);
  baixaLocal(p, localVenda, qtd); save('knx3d_products',products); renderProducts();
  updateLocalSaldo();
  
  // Limpa a tela para a próxima venda — inclusive a peça, para não repetir sem querer
  $('s_desc_val').value = '0';
  $('s_recebido').value = '';
  $('s_troco_val').textContent = 'R$ 0,00';
  $('s_pg1_val').value = '';
  limparPecaDaVenda();
  updatePagamentoUI();

  renderSales(); renderDashboard();
  toast('Venda registrada'+baixa,'ok');
  $('s_busca').focus();
};

function filteredSales(){
  const now=new Date();
  return sales.filter(s=>{
    if(filter==='all') return true;
    const d=new Date(s.data+'T00:00:00');
    if(filter==='month') return d.getMonth()===now.getMonth() && d.getFullYear()===now.getFullYear();
    if(filter==='30'){ const diff=(now-d)/86400000; return diff<=30 && diff>=-1; }
    return true;
  });
}

function renderSales(){
  const list=filteredSales();
  if(!list.length){ $('sales-list').innerHTML='<div class="empty">Nenhuma venda no período selecionado.</div>'; return; }
  const rows=[...list].sort((a,b)=>String(b.data||'').localeCompare(String(a.data||''))||String(b.id).localeCompare(String(a.id))).map(s=>{
    let pagtoBadge = s.pagamento ? `<span class="badge">${esc(s.pagamento)}</span>` : '';
    if(s.pagamento === 'Cartão' && s.cartaoTipo) {
      pagtoBadge = `<span class="badge">${esc(s.cartaoTipo)} ${esc(s.cartaoBandeira||'')}</span>`;
    }
    const descText = s.descontoValor ? `<br><small style="color:var(--amber)">Desc: -${money(s.descontoValor)}</small>` : '';
    return `
    <tr>
      <td>${fmtDate(s.data)}${s.usuarioNome?'<div class="autor">'+esc(s.usuarioNome)+'</div>':''}</td>
      <td>${prodImg(products.find(x=>String(x.id)===String(s.prodId))||{ico:s.ico},'prod-thumb')}${esc(s.nome)}${s.canal&&s.canal!=='Presencial'?' <span class="badge">'+esc(s.canal)+'</span>':''} ${pagtoBadge}</td>
      <td class="num">${s.qtd}</td>
      <td class="num">${money(num(s.precoUnit))}${descText}</td>
      <td class="num" style="color:var(--green)">${money(saleNet(s))}</td>
      <td style="white-space:nowrap; width:1%;"><div style="display:flex; justify-content:flex-end; gap:6px;">
        <button class="btn small" onclick="salePrint(\'${jsId(s.id)}\')" >Gerar Nota</button>
      </div></td>
    </tr>`;
  }).join('');
  $('sales-list').innerHTML=`<table><thead><tr>
    <th>Data / quem</th><th>Produto</th><th class="num">Qtd</th><th class="num">Preço un.</th>
    <th class="num">Líquido</th><th class="num">Ações</th>
    </tr></thead><tbody>${rows}</tbody></table>`;
}
function fmtDate(d){
  if(!d) return '—';
  const [y,m,day] = String(d).split('-');
  return esc(`${day||''}/${m||''}/${(y||'').slice(2)}`);
}
window.delSale=id=>{
  customConfirm('Excluir esta venda do histórico?', () => {
    const s=sales.find(x=>String(x.id)===String(id));
    if(s){
      // estorna a baixa de filamento feita na venda
      if(s.filamentId && s.gramasBaixa){
        const fil=filaments.find(f=>String(f.id)===String(s.filamentId));
        if(fil){ fil.estoque=(fil.estoque||0)+s.gramasBaixa; save('knx3d_filaments',filaments); }
      }
      // estorna a baixa do produto usando a quantidade REALMENTE baixada
      // (vendas antigas não têm qtdBaixa: cai no fallback para s.qtd)
      const estornoQtd = (s.qtdBaixa===undefined || s.qtdBaixa===null) ? num(s.qtd) : num(s.qtdBaixa);
      if(s.prodId && estornoQtd>0){
        const p=products.find(x=>String(x.id)===String(s.prodId));
        if(p){
          // Volta para o local de onde saiu. Vendas antigas caem na Oficina.
          const destEst = ['oficina','ml','shopee'].includes(s.localBaixa) ? s.localBaixa : 'oficina';
          entradaLocal(p, destEst, estornoQtd);
          save('knx3d_products',products); renderProducts();
        }
      }
    }
    sales=sales.filter(x=>String(x.id)!==String(id)); save('knx3d_sales',sales);
    if(s) registrar('excluiu','Venda', s.nome + ' — ' + s.qtd + ' un.', (num(s.precoUnit)*num(s.qtd)) - num(s.descontoValor));
    atualizarTudo(); toast('Venda excluída — estoque estornado','warn');
  });
};
