function sendWhats(q){
  if(!q.whatsapp){ toast('Cadastre o WhatsApp do cliente','warn'); return; }
  escolherOrigemZap((modo)=>{
    const url = waLink(q.whatsapp, quoteMsg(q), modo);
    if(!url){ toast('Número de WhatsApp inválido','warn'); return; }
    openOnce(url);
    downloadQuotePDF(q);
    toast('WhatsApp aberto — anexe o PDF na conversa','ok');
  });
}

