/* ---------- métricas de um cliente (LTV, última compra, follow-up) ---------- */
function clienteMetricas(c){
  const id = c.id;
  const nome = (c.nome||'').toLowerCase();

  const consigsCli = consignments.filter(x =>
    String(x.clienteId) === String(id) || (x.cliente && nome && x.cliente.toLowerCase() === nome));
  const ltvConsig = consigsCli.reduce((a, x) => a + consigRealizado(x).receber, 0);

  const vendasCli = sales.filter(x => x.clienteId && String(x.clienteId) === String(id));
  const ltvVendas = vendasCli.reduce((a, s) => {
    const bruto = ((num(s.precoUnit)||0) * (num(s.qtd)||0)) - (num(s.descontoValor)||0);
    const taxas = bruto * (((num(s.taxaPlat)||0) + (num(s.taxaCartao)||0)) / 100);
    return a + (bruto - taxas);
  }, 0);

  const datas = [];
  consigsCli.forEach(x => { if(x.data) datas.push(x.data); });
  vendasCli.forEach(s => { if(s.data) datas.push(s.data); });
  const ultima = datas.length ? datas.slice().sort().pop() : '';

  const logs = crmLogs.filter(x =>
    String(x.clienteId) === String(id) || (x.cliente && nome && x.cliente.toLowerCase() === nome));
  const hoje = hojeLocal();
  const followVencido = logs.some(l => l.followUp && l.followUp < hoje);
  const followAberto  = logs.some(l => l.followUp && l.followUp >= hoje);

  const orcsCli = quotes.filter(x => String(x.clienteId) === String(id));
  const orcs = orcsCli.length;

  // pedidos deste cliente: o que ele já pagou e o que ainda deve.
  // Antes a ficha só olhava vendas registradas, então um pedido entregue
  // e não pago não aparecia em lugar nenhum do cadastro.
  const pedidosCli = orcsCli.filter(ehPedido);
  const devendo    = pedidosCli.filter(q => prodFalta(q) >= 0.01);
  const aReceber   = devendo.reduce((a,q) => a + prodFalta(q), 0);
  const pagoPedidos = pedidosCli.reduce((a,q) => a + prodRecebido(q), 0);
  const entregueDevendo = devendo.some(jaEntregue);

  let dias = null;
  if(ultima){
    dias = Math.floor((new Date(hoje) - new Date(ultima)) / 86400000);
  }

  // etapa: último status informado, senão deduzido pelo tempo sem comprar
  const ultimoLog = logs.slice().sort((a,b)=>(b.data||'').localeCompare(a.data||''))[0];
  const temPedido = orcsCli.some(ehPedido);
  let etapa = ultimoLog && ultimoLog.status ? ultimoLog.status
            : (!ultima ? (temPedido ? 'Ativo' : 'Lead') : (dias > 60 ? 'Inativo' : 'Ativo'));

  return { ltv: ltvConsig + ltvVendas, ultima, dias, etapa, orcs,
           nVendas: vendasCli.length, nConsig: consigsCli.length,
           nLogs: logs.length, followVencido, followAberto,
           vendas: vendasCli, consigs: consigsCli, logs,
           pedidos: pedidosCli, devendo, aReceber, pagoPedidos, entregueDevendo };
}

function etapaCor(e){
  if(e === 'Inativo') return 'var(--red)';
  if(e === 'Recorrente') return 'var(--green)';
  if(e === 'Lead') return 'var(--ink-dim)';
  return 'var(--brand)';
}

