function salvarCliente(id){
  const d = readClientForm();
  if(!d.nome){ toast('Digite o nome do cliente','warn'); $('cl_nome').focus(); return; }
  if(id){
    const c = clients.find(x => String(x.id) === String(id));
    if(c) Object.assign(c, d);
  } else {
    clients.push(carimbar(Object.assign({ id: uid() }, d)));
  }
  save('knx3d_clients', clients);
  registrar(id ? 'editou' : 'criou', 'Cliente', d.nome);
  fecharModal();
  renderClientsList();
  renderClientSelect();
  if(typeof renderConsigClientSelect === 'function') renderConsigClientSelect();
  toast(id ? 'Cliente atualizado' : 'Cliente cadastrado','ok');
}

