window.clientFicha = id => {
  const c = clients.find(x => String(x.id) === String(id)); if(!c) return;
  const m = clienteMetricas(c);
  const hoje = hojeLocal();

  const contato = [
    c.whatsapp ? 'WhatsApp ' + esc(c.whatsapp) : '',
    c.email ? esc(c.email) : '',
    c.cpfCnpj ? 'CPF/CNPJ ' + esc(c.cpfCnpj) : ''
  ].filter(Boolean).join('  ·  ');

  const endereco = [
    c.endereco ? esc(c.endereco) + (c.numeroRua ? ', ' + esc(c.numeroRua) : '') : '',
    c.bairro ? esc(c.bairro) : '',
    c.cidade ? esc(c.cidade) : '',
    c.cep ? 'CEP ' + esc(c.cep) : '',
    c.complemento ? esc(c.complemento) : ''
  ].filter(Boolean).join(' — ');

  // últimas compras
  const compras = m.vendas.slice().sort((a,b)=>(b.data||'').localeCompare(a.data||'')).slice(0,8);
  const comprasHtml = compras.length
    ? '<table><thead><tr><th>Data</th><th>Peça</th><th class="num">Qtd</th><th class="num">Valor</th></tr></thead><tbody>' +
      compras.map(s => {
        const bruto = ((num(s.precoUnit)||0)*(num(s.qtd)||0)) - (num(s.descontoValor)||0);
        return '<tr><td>' + fmtDate(s.data) + '</td><td>' + esc(s.nome) + '</td><td class="num">' + s.qtd +
               '</td><td class="num">' + money(bruto) + '</td></tr>';
      }).join('') + '</tbody></table>'
    : '<div class="empty" style="padding:20px; font-size:13px">Nenhuma compra registrada.</div>';

  const corpo = `
    <div class="statstrip" style="margin:0 0 18px; grid-template-columns:repeat(auto-fit,minmax(140px,1fr))">
      <div><div class="k">Valor histórico</div><div class="v" style="color:var(--green)">${money(m.ltv + m.pagoPedidos)}</div><div class="s">líquido recebido</div></div>
      <div><div class="k">Última compra</div><div class="v" style="font-size:15px">${m.ultima ? fmtDate(m.ultima) : '—'}</div><div class="s">${m.dias === null ? 'nunca comprou' : 'há ' + m.dias + ' dia(s)'}</div></div>
      <div><div class="k">Compras</div><div class="v">${m.nVendas}</div><div class="s">${m.nConsig} consignado(s)</div></div>
      <div><div class="k">Etapa</div><div class="v" style="font-size:15px; color:${etapaCor(m.etapa)}">${esc(m.etapa)}</div><div class="s">${plural(m.orcs,'orçamento','orçamentos')}</div></div>
      ${m.aReceber > 0 ? `
      <div><div class="k">Está devendo</div>
        <div class="v" style="color:${m.entregueDevendo ? 'var(--red)' : 'var(--amber)'}">${money(m.aReceber)}</div>
        <div class="s">${m.entregueDevendo ? 'já entregue e sem pagar' : plural(m.devendo.length,'pedido em aberto','pedidos em aberto')}</div></div>` : ''}
    </div>

    ${m.pedidos.length ? `
    <h3 style="font-size:13px; margin:0 0 10px">Pedidos</h3>
    <table style="margin-bottom:18px"><thead><tr>
      <th class="num">Nº</th><th>Situação</th><th class="num">Total</th>
      <th class="num">Pago</th><th class="num">Falta</th><th class="num">Ação</th>
    </tr></thead><tbody>
      ${m.pedidos.slice().sort((a,b)=>String(b.data).localeCompare(String(a.data))).map(q => {
        const falta = prodFalta(q);
        const sit = jaEntregue(q)
          ? (falta >= 0.01 ? '<span class="mvtag mv-out">Entregue e devendo</span>'
                           : '<span class="mvtag mv-in">Entregue e pago</span>')
          : (diasParaEntrega(q) < 0 ? '<span class="mvtag mv-out">Atrasado</span>'
                                    : '<span class="mvtag mv-neutro">Entrega ' + fmtDate(q.prod.entrega) + '</span>');
        return `<tr>
          <td class="num">#${String(q.numero).padStart(3,'0')}</td>
          <td>${sit}</td>
          <td class="num">${money(num(q.total)||0)}</td>
          <td class="num" style="color:var(--green)">${money(prodRecebido(q))}</td>
          <td class="num" style="font-weight:600; color:${falta>=0.01?'var(--amber)':'var(--ink-dim)'}">${money(falta)}</td>
          <td style="white-space:nowrap; width:1%">${falta >= 0.01
            ? `<button class="btn small" data-ficha-rec="${q.id}">Receber</button>` : ''}</td>
        </tr>`;
      }).join('')}
    </tbody></table>` : ''}

    <div style="background:var(--panel-2); border:1px solid var(--line); border-radius:var(--radius-sm); padding:13px 15px; margin-bottom:18px">
      <div style="font-size:13.5px; color:var(--ink)">${contato || '<span style="color:var(--ink-dim)">Sem contato cadastrado</span>'}</div>
      ${endereco ? '<div style="font-size:12.5px; color:var(--ink-dim); margin-top:4px">' + endereco + '</div>' : ''}
    </div>

    <h3 style="font-size:13px; margin:0 0 12px">Registrar contato</h3>
    <div class="row3">
      <div class="field"><label>Data</label><input type="date" id="crm_data" value="${hoje}"></div>
      <div class="field"><label>Canal</label>
        <select id="crm_canal">
          <option value="WhatsApp">WhatsApp</option>
          <option value="Instagram">Instagram</option>
          <option value="Presencial">Presencial</option>
          <option value="Ligação">Ligação</option>
          <option value="Consignado">Consignado</option>
        </select>
      </div>
      <div class="field"><label>Etapa</label>
        <select id="crm_status">
          <option value="Lead"${m.etapa==='Lead'?' selected':''}>Lead — contato inicial</option>
          <option value="Ativo"${m.etapa==='Ativo'?' selected':''}>Ativo — comprando</option>
          <option value="Recorrente"${m.etapa==='Recorrente'?' selected':''}>Recorrente — fiel</option>
          <option value="Inativo"${m.etapa==='Inativo'?' selected':''}>Inativo — a recuperar</option>
        </select>
      </div>
    </div>
    <div class="row2">
      <div class="field"><label>Observação / assunto</label>
        <input type="text" id="crm_obs" placeholder="Ex.: pediu orçamento de 50 chaveiros"></div>
      <div class="field"><label>Lembrar de voltar em <span class="u">opcional</span></label>
        <div style="display:flex; gap:8px">
          <input type="date" id="crm_follow_data" style="flex:1">
          <button class="btn primary" type="button" id="btn_crm_add" style="flex:none">Salvar</button>
        </div>
      </div>
    </div>

    <div class="divider"></div>

    <h3 style="font-size:13px; margin:0 0 6px">Histórico de relacionamento</h3>
    <div id="crm_history_list"></div>

    <div class="divider"></div>

    <h3 style="font-size:13px; margin:0 0 6px">Últimas compras</h3>
    ${comprasHtml}`;

  const botoes = [{ txt:'Fechar', fn: fecharModal }];
  if(c.whatsapp){
    botoes.push({ txt:'Abrir WhatsApp', fn: () => {
      const d = String(c.whatsapp).replace(/\D/g,'');
      window.open('https://wa.me/' + (d.length<=11 ? '55'+d : d), '_blank');
    }});
  }
  botoes.push({ txt:'Editar cadastro', cls:'primary', fn: () => window.clientEdit(id) });

  abrirModal('Ficha de ' + c.nome, corpo, botoes, 'wide', () => {
    renderCrmList(id);
    $('btn_crm_add').dataset.cliente = id;
    $('btn_crm_add').onclick = () => crmSalvarLog(id);
    // receber direto da ficha, sem ir até Orçamentos
    $('modal-form-body').querySelectorAll('[data-ficha-rec]').forEach(b => {
      b.onclick = () => { const pid = b.dataset.fichaRec; fecharModal(); setTimeout(() => prodReceber(pid), 140); };
    });
  });
};

/* ---------- lista de clientes ---------- */
let clientPage = 1;

function renderCrmKpis(){
  const el = $('crm-kpis');
  if(!el) return;
  const hoje = hojeLocal();
  let ativos = 0, inativos = 0, ltvTotal = 0, pendentes = 0, devedores = 0, devido = 0;
  clients.forEach(c => {
    const m = clienteMetricas(c);
    ltvTotal += m.ltv + m.pagoPedidos;
    if(m.dias !== null && m.dias <= 60) ativos++;
    if(m.dias !== null && m.dias > 60) inativos++;
    if(m.followVencido) pendentes++;
    if(m.aReceber > 0){ devedores++; devido += m.aReceber; }
  });
  el.innerHTML = `
    <div><div class="k">Clientes</div><div class="v">${clients.length}</div><div class="s">cadastrados</div></div>
    <div><div class="k">Ativos</div><div class="v" style="color:var(--green)">${ativos}</div><div class="s">compraram nos últimos 60 dias</div></div>
    <div><div class="k">A recuperar</div><div class="v" style="color:${inativos?'var(--red)':'var(--ink)'}">${inativos}</div><div class="s">mais de 60 dias sem comprar</div></div>
    <div><div class="k">Follow-ups vencidos</div><div class="v" style="color:${pendentes?'var(--red)':'var(--ink)'}">${pendentes}</div><div class="s">retornos atrasados</div></div>
    ${devedores ? `<div><div class="k">Devendo</div><div class="v" style="color:var(--amber)">${money(devido)}</div>
      <div class="s">${plural(devedores,'cliente','clientes')} com saldo em aberto</div></div>` : ''}
    <div><div class="k">Valor histórico</div><div class="v">${money(ltvTotal)}</div><div class="s">soma de todos</div></div>`;
}

function renderClientsList(){
  const el=$('client-list'), pager=$('client-pager');
  renderCrmKpis();
  if(!clients.length){ el.innerHTML='<div class="empty">Nenhum cliente cadastrado ainda. Use o botão <b>Novo cliente</b>.</div>'; pager.innerHTML=''; return; }

  const termoBusca = norm($('client-search') ? $('client-search').value : '');
  let list = [...clients].sort((a,b)=>String(a.nome||'').localeCompare(String(b.nome||'')));
  if(termoBusca){
    list = list.filter(c => norm(c.nome).includes(termoBusca) || norm(c.cidade||'').includes(termoBusca) || norm(c.cpfCnpj||'').includes(termoBusca));
  }
  if(!list.length){ el.innerHTML='<div class="empty">Nenhum cliente encontrado.</div>'; pager.innerHTML=''; return; }

  const pageSizeVal = $('client-pagesize') ? $('client-pagesize').value : '10';
  const pageSize = pageSizeVal==='all' ? list.length : parseInt(pageSizeVal,10);
  const totalPaginas = Math.max(1, Math.ceil(list.length/pageSize));
  if(clientPage > totalPaginas) clientPage = totalPaginas;
  if(clientPage < 1) clientPage = 1;
  const inicio = (clientPage-1)*pageSize;
  const listPag = list.slice(inicio, inicio+pageSize);

  const rows = listPag.map(c => {
    const m = clienteMetricas(c);
    const alerta = m.followVencido
      ? '<span class="badge" style="color:var(--red); margin-left:6px">retorno atrasado</span>' : '';
    const deve = m.aReceber > 0
      ? '<span class="badge" style="color:' + (m.entregueDevendo ? 'var(--red)' : 'var(--amber)') +
        '; margin-left:6px">deve ' + money(m.aReceber) + '</span>' : '';
    const contato = c.whatsapp ? esc(c.whatsapp) : (c.email ? esc(c.email) : '—');
    const sub = [c.cidade ? esc(c.cidade) : '', c.cpfCnpj ? esc(c.cpfCnpj) : ''].filter(Boolean).join(' · ');
    return `
    <tr>
      <td>
        <div style="font-weight:600">${esc(c.nome)}${alerta}${deve}</div>
        ${sub ? '<div style="font-size:11.5px; color:var(--ink-dim)">' + sub + '</div>' : ''}
      </td>
      <td><span style="font-family:var(--mono); font-size:12.5px">${contato}</span></td>
      <td><span class="badge" style="color:${etapaCor(m.etapa)}">${esc(m.etapa)}</span></td>
      <td class="num">${(m.ltv + m.pagoPedidos) > 0 ? money(m.ltv + m.pagoPedidos) : '—'}</td>
      <td class="num">${m.ultima ? fmtDate(m.ultima) : '—'}${m.dias !== null ? '<div style="font-size:11px; color:var(--ink-dim)">há ' + m.dias + 'd</div>' : ''}</td>
      <td style="white-space:nowrap; width:1%"><div style="display:flex; justify-content:flex-end; gap:6px">
        <button class="btn small" onclick="clientFicha('${jsId(c.id)}')">Ficha</button>
        <button class="btn small" onclick="clientUse('${jsId(c.id)}')">Orçar</button>
        <button class="btn small danger" onclick="clientDel('${jsId(c.id)}')">Excluir</button>
      </div></td>
    </tr>`;
  }).join('');

  el.innerHTML = `<table><thead><tr>
    <th>Cliente</th><th>Contato</th><th>Etapa</th>
    <th class="num">Valor histórico</th><th class="num">Última compra</th><th class="num">Ações</th>
    </tr></thead><tbody>${rows}</tbody></table>`;

  if(totalPaginas <= 1){
    pager.innerHTML = `<small style="color:var(--ink-dim)">${list.length} ${list.length===1?'cliente':'clientes'}</small>`;
  } else {
    pager.innerHTML = `
      <button class="btn small ghost" id="client-pg-prev" ${clientPage<=1?'disabled':''}>← Anterior</button>
      <small style="color:var(--ink-dim)">Página ${clientPage} de ${totalPaginas} · ${list.length} clientes</small>
      <button class="btn small ghost" id="client-pg-next" ${clientPage>=totalPaginas?'disabled':''}>Próxima →</button>`;
    $('client-pg-prev').onclick = ()=>{ clientPage--; renderClientsList(); };
    $('client-pg-next').onclick = ()=>{ clientPage++; renderClientsList(); };
  }
}
$('client-search').addEventListener('input',()=>{ clientPage=1; renderClientsList(); });
$('client-pagesize').addEventListener('change',()=>{ clientPage=1; renderClientsList(); });

window.clientDel=id=>{
  const c=clients.find(x=>String(x.id)===String(id)); if(!c) return;

  // Conta vínculos para avisar antes de excluir (histórico NÃO é apagado)
  const nLogs   = crmLogs.filter(x=>String(x.clienteId)===String(id)).length;
  const nOrc    = quotes.filter(x=>String(x.clienteId)===String(id)).length;
  const nConsig = consignments.filter(x=>String(x.clienteId)===String(id)).length;

  let aviso='';
  if(nLogs)   aviso+='<br>• '+nLogs+' registro(s) de CRM serão <b style="color:var(--red)">apagados</b>';
  if(nOrc)    aviso+='<br>• '+nOrc+' orçamento(s) continuam no histórico (sem vínculo)';
  if(nConsig) aviso+='<br>• '+nConsig+' termo(s) de consignação continuam no histórico (sem vínculo)';

  customConfirm('Excluir o cliente <b>'+esc(c.nome)+'</b>?'+
    (aviso?'<br><br><small style="color:var(--ink-soft); font-weight:normal;">'+aviso+'</small>':''), () => {

    // Se este cliente estava aberto no formulário, limpa a tela
    clients = clients.filter(x=>String(x.id)!==String(id));
    save('knx3d_clients',clients);
    registrar('excluiu','Cliente', c.nome);

    // Remove os logs de CRM órfãos deste cliente
    crmLogs = crmLogs.filter(x=>String(x.clienteId)!==String(id));
    save('knx3d_crm_logs',crmLogs);

    renderClientsList();
    renderClientSelect();
    renderConsigClientSelect();
    toast('Cliente excluído','warn');
  });
};
window.clientUse=id=>{
  const c=clients.find(x=>String(x.id)===String(id)); if(!c) return;
  goTo('operacao','quote');
  renderClientSelect(); $('q_cliente_sel').value=id; $('q_cliente_sel').dispatchEvent(new Event('change'));
  $('q_cliente').value=c.nome;
  $('q_whatsapp').value=c.whatsapp||'';
  $('q_contato').value=c.email||'';
  $('q_cpf').value=c.cpfCnpj||'';
  const endCompleto = [c.endereco, c.numeroRua, c.bairro, c.cidade, c.cep].filter(Boolean).join(', ');
  if(endCompleto && !$('q_endereco').value) $('q_endereco').value = endCompleto;
  formatarCamposExistentes($('view-quote'));
  toast('Cliente carregado no orçamento','ok');
};
/* ---------- Lógica do CRM ---------- */
$('btn_cm_crm_add').onclick = () => {
  const clienteId = $('btn_cm_crm_add').dataset.cliente;
  if (!clienteId) return;
  const obs = ($('cm_crm_obs').value || '').trim();
  if (!obs) { toast('Digite a observação do contato', 'warn'); return; }

  const log = {
    id: uid(),
    clienteId: clienteId,
    data: $('cm_crm_data').value || hojeLocal(),
    canal: $('cm_crm_canal').value,
    status: $('cm_crm_status').value,
    obs: obs,
    followUp: $('cm_crm_follow_data').value || ''
  };

  crmLogs.push(carimbar(log));
  save('knx3d_crm_logs', crmLogs);
  registrar('registrou','Contato (CRM)', log.obs);

  $('cm_crm_obs').value = '';
  $('cm_crm_follow_data').value = '';

  renderCrmList(clienteId, 'cm_crm_history_list');
  toast('Interação de Consignado salva', 'ok');
};

window.crmSalvarLog = (clienteId) => {
  if (!clienteId) return;
  const obs = ($('crm_obs').value || '').trim();
  if (!obs) { toast('Digite a observação do contato', 'warn'); return; }

  const log = {
    id: uid(),
    clienteId: clienteId,
    data: $('crm_data').value || hojeLocal(),
    canal: $('crm_canal').value,
    status: $('crm_status').value,
    obs: obs,
    followUp: $('crm_follow_data').value || ''
  };

  crmLogs.push(carimbar(log));
  save('knx3d_crm_logs', crmLogs);
  registrar('registrou','Contato (CRM)', log.obs);

  $('crm_obs').value = '';
  $('crm_follow_data').value = '';

  renderCrmList(clienteId);
  toast('Interação salva no CRM', 'ok');
};

window.renderCrmList = (clienteId, targetId = 'crm_history_list') => {
  const el = $(targetId);
  
  // Busca o cliente atual para pegar o nome caso algum registro antigo tenha sido salvo sem ID direto
  const cliObj = clients.find(x => String(x.id) === String(clienteId));
  const cliNome = cliObj ? String(cliObj.nome||'').toLowerCase() : '';

  // Filtra logs que pertencem ao ID ou que possuem o nome correspondente
  const logs = crmLogs.filter(x => {
    if (String(x.clienteId) === String(clienteId)) return true;
    if (cliNome && x.cliente && x.cliente.toLowerCase() === cliNome) return true;
    return false;
  });

  if (!logs.length) {
    el.innerHTML = '<div class="empty" style="padding:16px; font-size:13px;">Nenhum registro de relacionamento para este cliente.</div>';
    return;
  }

  const hojeStr = hojeLocal();

  // Ordenação: Follow-ups (mais antigos/vencidos primeiro), depois logs sem follow-up (mais recentes primeiro)
  const sorted = [...logs].sort((a, b) => {
    if (a.followUp && b.followUp) return a.followUp.localeCompare(b.followUp);
    if (a.followUp) return -1;
    if (b.followUp) return 1;
    return String(b.data||'').localeCompare(String(a.data||'')) || String(b.id).localeCompare(String(a.id));
  });

  const rows = sorted.map(log => {
    let followBadge = '';
    if (log.followUp) {
      const isVencido = log.followUp < hojeStr;
      followBadge = isVencido
        ? '<span class="badge" style="color:var(--red)">Vencido: ' + fmtDate(log.followUp) + '</span>'
        : '<span class="badge" style="color:var(--cyan)">Follow-up: ' + fmtDate(log.followUp) + '</span>';
    }

    return `
      <div style="border-bottom: 1px solid var(--line); padding: 12px 0;">
        <div style="display:flex; justify-content:space-between; margin-bottom:6px;">
          <div>
            <span class="badge" style="background:var(--bg-2); border:none; margin-right:4px;">${esc(log.canal)}</span>
            <span class="badge" style="background:var(--bg-2); border:none;">${esc(log.status)}</span>
          </div>
          <div style="font-size:11px; color:var(--ink-dim); font-family:var(--mono); text-align:right">
            ${fmtDate(log.data)}
            ${log.usuarioNome?'<div class="autor" style="margin-top:2px">'+esc(log.usuarioNome)+'</div>':''}
          </div>
        </div>
        <div style="font-size:13px; color:var(--ink); margin-bottom:8px;">
          ${esc(log.obs)}
        </div>
        <div style="display:flex; justify-content:space-between; align-items:center;">
          <div>${followBadge}</div>
          <button class="btn small ghost" style="color:var(--red); font-size:11px; padding:2px 6px;" onclick="crmDel('${jsId(log.id)}')">Excluir</button>
        </div>
      </div>
    `;
  }).join('');

  el.innerHTML = rows;
};

window.crmDel = id => {
  customConfirm('Excluir este registro de CRM?', () => {
    const log = crmLogs.find(x => String(x.id) === String(id));
    if (!log) return;
    const clienteId = log.clienteId;
    crmLogs = crmLogs.filter(x => String(x.id) !== String(id));
    save('knx3d_crm_logs', crmLogs);
    
    // Atualiza a tela que estiver visível no momento
    if ($('crm_history_list')) {
      renderCrmList(clienteId, 'crm_history_list');
    }
    if ($('modal-consig-manage') && $('modal-consig-manage').classList.contains('active')) {
      renderCrmList(clienteId, 'cm_crm_history_list');
    }
    
    toast('Registro excluído', 'warn');
  });
};

/* ---------- serviços ---------- */
function adicionarServicoAoOrcamento(sv){
  const qtd = Math.max(1, Math.round(num($('q_serv_qtd').value)||1));
  quoteItems.push({prodId:'', nome:sv.nome, foto:'', qtd, preco:sv.preco});
  $('q_serv_qtd').value = '1';

  if (sv.mostrarObs && sv.descOrcamento) {
    const obsAtual = ($('q_obs').value || '').trim();
    if (!obsAtual.includes(sv.descOrcamento)) {
      $('q_obs').value = obsAtual ? obsAtual + '\n\n' + sv.descOrcamento : sv.descOrcamento;
    }
  }
  renderQuoteItems();
  toast(qtd + ' × ' + sv.nome + ' no orçamento', 'ok');
  $('q_serv_busca').focus();
}

const buscaQuoteServ = criarBusca({
  input: 'q_serv_busca',
  results: 'q_serv_results',
  itens: () => services,
  campos: sv => [sv.nome, sv.descInterna || ''],
  vazio: 'Nenhum serviço cadastrado ainda.',
  linha: sv => ({ nome: esc(sv.nome), preco: money(sv.preco) }),
  aoEscolher: adicionarServicoAoOrcamento
});
function renderServiceSelect(){ if(buscaQuoteServ) buscaQuoteServ.desenhar(); }
let servPage = 1;
function renderServices(){
  const el=$('serv-list'), pager=$('serv-pager');
  if(!services.length){ el.innerHTML='<div class="empty">Nenhum serviço cadastrado. Adicione acima.</div>'; pager.innerHTML=''; return; }

  const termoBusca = norm($('serv-search') ? $('serv-search').value : '');
  let list = [...services].sort((a,b)=>String(a.nome||'').localeCompare(String(b.nome||'')));
  if(termoBusca){
    list = list.filter(sv => norm(sv.nome).includes(termoBusca));
  }
  if(!list.length){ el.innerHTML='<div class="empty">Nenhum serviço encontrado.</div>'; pager.innerHTML=''; return; }

  const pageSizeVal = $('serv-pagesize') ? $('serv-pagesize').value : '10';
  const pageSize = pageSizeVal==='all' ? list.length : parseInt(pageSizeVal,10);
  const totalPaginas = Math.max(1, Math.ceil(list.length/pageSize));
  if(servPage > totalPaginas) servPage = totalPaginas;
  if(servPage < 1) servPage = 1;
  const inicio = (servPage-1)*pageSize;
  const listPag = list.slice(inicio, inicio+pageSize);

  const rows=listPag.map(sv=>`
    <tr><td><div style="font-weight:600">${esc(sv.nome)}</div>${sv.descInterna?'<div style="font-size:12px; color:var(--ink-dim); margin-top:2px; padding-left:22px;">'+esc(sv.descInterna)+'</div>':''}</td><td class="num">${money(sv.preco)}</td>
    <td style="white-space:nowrap; width:1%;"><div style="display:flex; justify-content:flex-end; gap:6px;"><button class="btn small" onclick="svEdit(\'${jsId(sv.id)}\')">Editar</button>
      <button class="btn small danger" onclick="svDel(\'${jsId(sv.id)}\')">Excluir</button>
    </div></td></tr>`).join('');
  el.innerHTML=`<table><thead><tr><th>Serviço</th><th class="num">Preço</th><th class="num">Ações</th></tr></thead><tbody>${rows}</tbody></table>`;

  if(totalPaginas <= 1){
    pager.innerHTML = `<small style="color:var(--ink-dim)">${list.length} ${list.length===1?'item':'itens'}</small>`;
  } else {
    pager.innerHTML = `
      <button class="btn small ghost" id="serv-pg-prev" ${servPage<=1?'disabled':''}>← Anterior</button>
      <small style="color:var(--ink-dim)">Página ${servPage} de ${totalPaginas} · ${list.length} itens</small>
      <button class="btn small ghost" id="serv-pg-next" ${servPage>=totalPaginas?'disabled':''}>Próxima →</button>`;
    $('serv-pg-prev').onclick = ()=>{ servPage--; renderServices(); };
    $('serv-pg-next').onclick = ()=>{ servPage++; renderServices(); };
  }
}
$('serv-search').addEventListener('input',()=>{ servPage=1; renderServices(); });
$('serv-pagesize').addEventListener('change',()=>{ servPage=1; renderServices(); });
$('sv_add').onclick=()=>{
  const nome=($('sv_nome').value||'').trim();
  if(!nome){ toast('Informe o nome do serviço','warn'); return; }
  
  const descInterna = ($('sv_desc_int').value||'').trim();
  const descOrcamento = ($('sv_desc_orc').value||'').trim();
  const mostrarObs = $('sv_mostrar_obs').checked;
  
  const obj={ nome, preco:num($('sv_preco').value), descInterna, descOrcamento, mostrarObs };
  
  const editing=$('sv_add').dataset.editing;
  if(editing){ const i=services.findIndex(x=>String(x.id)===String(editing)); if(i>=0){ obj.id=editing; services[i]=obj; } }
  else{ obj.id=uid(); services.push(carimbar(obj)); }
  
  save('knx3d_services',services);
  
  $('sv_nome').value=''; $('sv_preco').value=''; 
  $('sv_desc_int').value=''; $('sv_desc_orc').value=''; $('sv_mostrar_obs').checked=true;
  $('sv_add').dataset.editing=''; $('sv_add').textContent='Adicionar';
  
  registrar(editing?'editou':'criou','Serviço', obj.nome, obj.preco);
  fecharModal(); renderServices(); renderServiceSelect(); toast('Serviço salvo','ok');
};
window.svEdit=id=>{
  const sv=services.find(x=>String(x.id)===String(id)); if(!sv) return;
  $('sv_nome').value=sv.nome; $('sv_preco').value=String(sv.preco).replace('.',',');
  $('sv_desc_int').value=sv.descInterna||'';
  $('sv_desc_orc').value=sv.descOrcamento||'';
  $('sv_mostrar_obs').checked=sv.mostrarObs!==false;
  $('sv_add').dataset.editing=id; $('sv_add').textContent='Salvar alterações';
  abrirModalForm('Editar serviço', 'form-serv', 'sv_add');
};
window.svDel=id=>{
  customConfirm('Excluir este serviço?', () => {
    const _sv = services.find(x=>String(x.id)===String(id));
    services=services.filter(x=>String(x.id)!==String(id)); save('knx3d_services',services);
    registrar('excluiu','Serviço', _sv ? _sv.nome : id);
    renderServices(); renderServiceSelect(); toast('Serviço excluído','warn');
  });
};

/* ---------- financeiro ---------- */
/* O Dashboard e o Financeiro falam do mesmo dinheiro, então usam o MESMO
   recorte de tempo. Antes um abria em "Tudo" e o outro em "Mês atual", e
   os números pareciam não conversar. Mudar num lugar muda no outro. */
let periodoFiltro = 'all';
function setPeriodo(f){
  periodoFiltro = f;
  ['dash-filters','fin-filters'].forEach(id => {
    const box = $(id); if(!box) return;
    box.querySelectorAll('button').forEach(x => x.classList.toggle('active', x.dataset.f === f));
  });
  const aberta = document.querySelector('.view.active')?.id?.replace('view-','');
  if(aberta === 'dash') renderDashboard();
  if(aberta === 'fin')  renderFinance();
}
$('fin-filters').querySelectorAll('button').forEach(b=>{
  b.onclick=()=>setPeriodo(b.dataset.f);
});
$('ex_data').value=hojeLocal();
$('ex_add').onclick=()=>{
  const valor=numBR($('ex_valor').value);
  if(valor<=0){ toast('Informe um valor válido','warn'); return; }
  const _gasto = carimbar({ id:uid(), data:$('ex_data').value||hojeLocal(),
    categoria:$('ex_cat').value, descricao:($('ex_desc').value||'').trim(), valor });
  expenses.push(_gasto);
  registrar('lançou','Despesa', _gasto.categoria + (_gasto.descricao ? ' — ' + _gasto.descricao : ''), valor);
  save('knx3d_expenses',expenses);
  $('ex_valor').value=''; $('ex_desc').value='';
  fecharModal(); renderFinance(); renderDashboard(); toast('Gasto lançado','ok');
};
function inPeriod(dateStr, f){
  if(f==='all') return true;
  const now=new Date(), d=new Date(dateStr+'T00:00:00');
  if(f==='month') return d.getMonth()===now.getMonth() && d.getFullYear()===now.getFullYear();
  if(f==='30'){ const diff=(now-d)/86400000; return diff<=30 && diff>=-1; }
  return true;
}
/* ================================================================
   EXTRATO DO FINANCEIRO — todo dinheiro num lugar só
   Entrada: venda direta e recebimento de pedido (pelo dia que entrou).
   Saída:   lançamento de gasto.
   A venda gerada por um pedido NÃO entra aqui: o dinheiro dela já
   entrou pelos recebimentos. Ela aparece marcada como faturamento.
   ================================================================ */
let movPage = 1;

function montarMovimentos(filtro){
  const lista = [];

  sales.forEach(s => {
    if(!inPeriod(s.data, filtro)) return;
    const dePedido = !!s.pedidoId;
    lista.push({
      tipo: dePedido ? 'faturamento' : 'venda',
      dir:  dePedido ? 0 : 1,
      data: s.data,
      titulo: esc(s.nome || 'Venda') + (s.mkt && s.mkt.pedido ? ' <span class="mvsub" style="display:inline">· ' + esc(s.canal) + ' #' + esc(s.mkt.pedido) + '</span>' : ''),
      detalhe: [ (num(s.qtd)||0) + ' un.', esc(s.canal || 'Presencial'), esc(s.pagamento || ''),
                 s.mkt && s.mkt.pedido ? esc('#' + s.mkt.pedido) : '' ]
               .filter(Boolean).join(' · '),
      valor: saleNet(s),
      quem: s.usuarioNome || '',
      acao: dePedido
        ? ['Cancelar faturamento', () => finCancelarFaturamento(s.pedidoId)]
        : (s.mkt && s.mkt.pedido
            ? ['Cancelar pedido', () => finCancelarMkt(s.canal + '|' + s.mkt.pedido)]
            : ['Excluir venda', () => delSale(s.id)]),
      ref: s.id
    });
  });

  quotes.forEach(q => {
    if(!ehPedido(q)) return;
    prodRecebimentos(q).forEach(r => {
      if(!inPeriod(r.data, filtro)) return;
      lista.push({
        tipo: 'pedido', dir: 1, data: r.data,
        titulo: 'Pedido #' + String(q.numero).padStart(3,'0') + ' — ' + esc(q.cliente || 'sem cliente'),
        detalhe: [ esc(r.obs || 'Recebimento'), esc(r.forma || '') ].filter(Boolean).join(' · '),
        valor: num(r.valor)||0,
        quem: '',
        acao: ['Estornar', () => finEstornar(q.id, r.id)],
        ref: r.id
      });
    });
  });

  expenses.forEach(e => {
    if(!inPeriod(e.data, filtro)) return;
    lista.push({
      tipo: 'gasto', dir: -1, data: e.data,
      titulo: esc(e.categoria || 'Gasto'),
      detalhe: esc(e.descricao || ''),
      valor: num(e.valor)||0,
      quem: e.usuarioNome || '',
      acao: ['Excluir lançamento', () => expDel(e.id)],
      ref: e.id
    });
  });

  return lista.sort((a,b) => String(b.data||'').localeCompare(String(a.data||'')) || String(b.ref).localeCompare(String(a.ref)));
}

/* Cancelar o faturamento de um pedido: desfaz a finalização inteira.
   Apaga TODAS as vendas que aquele pedido gerou (não dá pra apagar uma
   linha só, senão o pedido ficaria meio faturado), devolve o estoque e
   volta o pedido pra produção. Os recebimentos não são mexidos — dinheiro
   recebido se estorna separado, linha por linha. */
function finCancelarFaturamento(quoteId){
  if(!precisa('excluir','Sua conta não tem permissão para cancelar vendas')) return;
  const q = quotes.find(x => String(x.id) === String(quoteId));
  if(!q){ toast('Pedido não encontrado','warn'); return; }
  const vendas = pedidoVendas(q);
  if(!vendas.length){ toast('Este pedido não tem venda registrada','warn'); return; }

  const total = vendas.reduce((a,s) => a + saleNet(s), 0);
  const pecas = vendas.filter(s => s.prodId).reduce((a,s) => a + (num(s.qtd)||0), 0);
  const recebido = prodRecebido(q);

  customConfirm(
    'Cancelar o faturamento do pedido #' + String(q.numero).padStart(3,'0') + '?<br><br>' +
    'Apaga ' + plural(vendas.length,'venda','vendas') + ' do histórico (' + money(total) + '), ' +
    'devolve ' + plural(pecas,'peça','peças') + ' ao estoque e volta o pedido pra produção.' +
    (recebido > 0
      ? '<br><br><b>Atenção:</b> ' + money(recebido) + ' já recebido continua lançado. ' +
        'Se o cliente foi devolvido, estorne os recebimentos também.'
      : ''),
    () => {
      const qq = quotes.find(x => String(x.id) === String(quoteId));
      const vv = qq ? pedidoVendas(qq) : [];
      if(!qq || !vv.length){ toast('Esse faturamento já não existe — a tela foi atualizada','warn'); atualizarTudo(); return; }
      const ids = new Set(vv.map(v => String(v.id)));
      vv.forEach(v => {
        if(!v.prodId) return;
        const p = products.find(x => String(x.id) === String(v.prodId));
        if(!p) return;
        // devolve o que de fato saiu (qtdBaixa), pro local de onde saiu (localBaixa)
        const qtd = (v.qtdBaixa === undefined || v.qtdBaixa === null) ? (num(v.qtd)||0) : (num(v.qtdBaixa)||0);
        const loc = ['oficina','ml','shopee'].includes(v.localBaixa) ? v.localBaixa : 'oficina';
        entradaLocal(p, loc, qtd);
      });
      sales = sales.filter(x => !ids.has(String(x.id)));
      save('knx3d_sales', sales);
      save('knx3d_products', products);

      delete qq.prod.vendaIds;
      qq.prod.entregue = false;
      delete qq.prod.entregueEm;
      delete qq.prod.vendaEm;
      save('knx3d_quotes', quotes);

      registrar('cancelou o faturamento','Pedido',
                (qq.cliente||'sem cliente') + ' — pedido #' + String(qq.numero).padStart(3,'0'), total);
      atualizarTudo();
      toast('Faturamento cancelado — pedido voltou pra produção','warn');
    });
}

/* Pedido de marketplace se cancela INTEIRO: todas as linhas saem juntas e
   cada peça volta pro local de onde saiu (ML Full, Shopee Full ou Oficina). */
function finCancelarMkt(chave){
  if(!precisa('excluir','Sua conta não tem permissão para cancelar vendas')) return;
  const linhas = sales.filter(s => s.mkt && s.mkt.pedido && (s.canal + '|' + s.mkt.pedido) === chave);
  if(!linhas.length){ toast('Pedido não encontrado','warn'); return; }
  const l0 = linhas[0];
  const total = linhas.reduce((a,s) => a + saleNet(s), 0);
  const locais = {};
  linhas.forEach(s => { const n = (LOCAIS_DEF.find(x=>x.key===s.localBaixa)||{nome:'Oficina'}).nome;
                        locais[n] = (locais[n]||0) + (num(s.qtdBaixa!=null ? s.qtdBaixa : s.qtd)||0); });
  customConfirm('Cancelar o pedido ' + esc(l0.canal) + ' #' + esc(l0.mkt.pedido) + '?<br><br>' +
    '<small style="font-weight:normal">Sai do histórico (' + money(total) + ' que você receberia) e as peças voltam: ' +
    Object.entries(locais).map(([n,q]) => plural(q,'peça','peças') + ' pro ' + esc(n)).join(', ') + '.</small>', () => {
    const agora = sales.filter(s => s.mkt && s.mkt.pedido && (s.canal + '|' + s.mkt.pedido) === chave);
    if(!agora.length){ toast('Esse pedido já não existe — a tela foi atualizada','warn'); atualizarTudo(); return; }
    agora.forEach(v => {
      const p = products.find(x => String(x.id) === String(v.prodId));
      if(!p) return;
      const qtd = (v.qtdBaixa === undefined || v.qtdBaixa === null) ? (num(v.qtd)||0) : (num(v.qtdBaixa)||0);
      const loc = ['oficina','ml','shopee'].includes(v.localBaixa) ? v.localBaixa : 'oficina';
      entradaLocal(p, loc, qtd);
    });
    const ids = new Set(agora.map(v => String(v.id)));
    sales = sales.filter(x => !ids.has(String(x.id)));
    save('knx3d_sales', sales);
    save('knx3d_products', products);
    registrar('cancelou','Pedido', l0.canal + ' #' + l0.mkt.pedido, total);
    atualizarTudo();
    toast('Pedido cancelado — peças de volta ao estoque','warn');
  });
}

// estorno de recebimento, agora morando no Financeiro
function finEstornar(quoteId, recId){
  if(!precisa('excluir','Sua conta não tem permissão para estornar')) return;
  const q = quotes.find(x => String(x.id) === String(quoteId));
  if(!q) return;
  const recs = prodRecebimentos(q);
  const i = recs.findIndex(r => String(r.id) === String(recId));
  if(i < 0) return;
  const r = recs[i];
  customConfirm('Estornar o recebimento de ' + money(num(r.valor)) + ' do pedido #' +
                String(q.numero).padStart(3,'0') + '? O valor volta a constar como a receber.', () => {
    // relê: se outro computador sincronizou enquanto a pergunta estava aberta,
    // os objetos de antes já não são os que vão ser gravados
    const qq = quotes.find(x => String(x.id) === String(quoteId));
    const rr = qq ? prodRecebimentos(qq) : [];
    const ii = rr.findIndex(x => String(x.id) === String(recId));
    if(ii < 0){ toast('Esse recebimento não existe mais — a tela foi atualizada','warn'); atualizarTudo(); return; }
    rr.splice(ii,1);
    save('knx3d_quotes', quotes);
    registrar('estornou','Pedido', (qq.cliente||'sem cliente') + ' — pedido #' + String(qq.numero).padStart(3,'0'), num(r.valor));
    if(typeof fecharModal === 'function') fecharModal();
    atualizarTudo();
    toast('Recebimento estornado','warn');
  });
}

const MOV_ROTULO = {
  venda:       ['Venda',        'mv-in'],
  pedido:      ['Pedido',       'mv-in'],
  gasto:       ['Gasto',        'mv-out'],
  faturamento: ['Faturado',     'mv-neutro']
};

function renderMovimentos(){
  const el = $('mov-list'); if(!el) return;
  let lista = montarMovimentos(periodoFiltro);

  const tipo = $('mov-tipo') ? $('mov-tipo').value : 'all';
  if(tipo === 'in')  lista = lista.filter(m => m.dir === 1);
  if(tipo === 'out') lista = lista.filter(m => m.dir === -1);
  if(['venda','pedido','gasto'].includes(tipo)) lista = lista.filter(m => m.tipo === tipo);

  const termo = norm($('mov-search') ? $('mov-search').value : '');
  const semTag = t => String(t||'').replace(/<[^>]*>/g,' ');
  if(termo) lista = lista.filter(m => norm(semTag(m.titulo) + ' ' + semTag(m.detalhe) + ' ' + m.quem).includes(termo));

  // totais sempre do período inteiro, não da página
  const todos = montarMovimentos(periodoFiltro);
  const entrou = todos.filter(m => m.dir === 1).reduce((a,m) => a + m.valor, 0);
  const saiu   = todos.filter(m => m.dir === -1).reduce((a,m) => a + m.valor, 0);
  const kpis = $('fin-kpis');
  if(kpis){
    const receber = totalAReceber();
    kpis.innerHTML =
      '<div><div class="k">Entrou</div><div class="v" style="color:var(--green)">' + money(entrou) + '</div><div class="s">vendas e recebimentos</div></div>' +
      '<div><div class="k">Saiu</div><div class="v" style="color:var(--red)">' + money(saiu) + '</div><div class="s">gastos lançados</div></div>' +
      '<div><div class="k">Sobrou</div><div class="v" style="color:' + (entrou-saiu>=0?'var(--green)':'var(--red)') + '">' + money(entrou-saiu) + '</div><div class="s">no período</div></div>' +
      (receber > 0 ? '<div><div class="k">A receber</div><div class="v" style="color:var(--amber)">' + money(receber) + '</div><div class="s">pedidos em aberto</div></div>' : '');
  }

  if(!lista.length){
    el.innerHTML = '<div class="empty">Nada movimentou o caixa neste período.</div>';
    if($('mov-pager')) $('mov-pager').innerHTML = '';
    return;
  }

  const tam = $('mov-pagesize') ? $('mov-pagesize').value : '25';
  const porPag = tam === 'all' ? lista.length : parseInt(tam,10);
  const totalPag = Math.max(1, Math.ceil(lista.length/porPag));
  if(movPage > totalPag) movPage = totalPag;
  if(movPage < 1) movPage = 1;
  const pagina = lista.slice((movPage-1)*porPag, (movPage-1)*porPag + porPag);

  const podeMexer = (typeof pode !== 'function') || pode('excluir');
  const rows = pagina.map((m,i) => {
    const [rot, cls] = MOV_ROTULO[m.tipo] || ['—','mv-neutro'];
    const sinal = m.dir === 1 ? '+' : (m.dir === -1 ? '−' : '');
    const cor = m.dir === 1 ? 'var(--green)' : (m.dir === -1 ? 'var(--red)' : 'var(--ink-dim)');
    return `<tr>
      <td>${fmtDate(m.data)}${m.quem?'<div class="autor">'+esc(m.quem)+'</div>':''}</td>
      <td><span class="mvtag ${cls}">${rot}</span></td>
      <td>${m.titulo}${m.detalhe?'<div class="mvsub">'+m.detalhe+'</div>':''}</td>
      <td class="num" style="font-weight:600; color:${cor}; white-space:nowrap">${sinal} ${money(m.valor)}</td>
      <td style="white-space:nowrap; width:1%">${
        (m.acao && podeMexer) ? `<button class="btn small danger" data-mov="${i}">${esc(m.acao[0])}</button>` : ''
      }</td>
    </tr>`;
  }).join('');

  el.innerHTML = `<table><thead><tr>
    <th>Data / quem</th><th>Tipo</th><th>Descrição</th><th class="num">Valor</th><th class="num">Ação</th>
    </tr></thead><tbody>${rows}</tbody></table>
    <p class="hint" style="margin:12px 0 0; font-size:11.5px">
      <b>Faturado</b> é a venda gerada por um pedido. Não soma no caixa porque o dinheiro dela entra
      pelas linhas de <b>Pedido</b>. Estornar um recebimento tira o dinheiro do caixa mas mantém a venda;
      para apagar a venda e devolver o estoque, use <b>Cancelar faturamento</b>.
    </p>`;

  el.querySelectorAll('[data-mov]').forEach(b => {
    const m = pagina[parseInt(b.dataset.mov,10)];
    if(m && m.acao) b.onclick = m.acao[1];
  });

  const pager = $('mov-pager');
  if(!pager) return;
  if(totalPag <= 1){
    pager.innerHTML = `<small style="color:var(--ink-dim)">${plural(lista.length,'movimento','movimentos')}</small>`;
  } else {
    pager.innerHTML = `
      <button class="btn small ghost" id="mov-prev" ${movPage<=1?'disabled':''}>← Anterior</button>
      <small style="color:var(--ink-dim)">Página ${movPage} de ${totalPag} · ${lista.length} movimentos</small>
      <button class="btn small ghost" id="mov-next" ${movPage>=totalPag?'disabled':''}>Próxima →</button>`;
    $('mov-prev').onclick = () => { movPage--; renderMovimentos(); };
    $('mov-next').onclick = () => { movPage++; renderMovimentos(); };
  }
}

/* ---------- quadro "a receber" ---------- */
function renderAReceber(){
  const el = $('fin-receber'); if(!el) return;
  const abertos = quotes.filter(q => ehPedido(q) && prodFalta(q) >= 0.01)
    .sort((a,b) => {
      const ea = jaEntregue(a) ? -1 : 0, eb = jaEntregue(b) ? -1 : 0;
      if(ea !== eb) return ea - eb;
      return String(a.prod.entrega).localeCompare(String(b.prod.entrega));
    });

  if(!abertos.length){
    el.innerHTML = '<div class="empty">Ninguém está te devendo. Todos os pedidos estão quitados.</div>';
    return;
  }
  const total = abertos.reduce((a,q) => a + prodFalta(q), 0);
  const rows = abertos.map(q => {
    const falta = prodFalta(q);
    const pago  = prodRecebido(q);
    const sit = jaEntregue(q)
      ? '<span class="mvtag mv-out">Entregue e devendo</span>'
      : (diasParaEntrega(q) < 0
          ? '<span class="mvtag mv-out">Atrasado</span>'
          : '<span class="mvtag mv-neutro">Entrega ' + fmtDate(q.prod.entrega) + '</span>');
    return `<tr>
      <td class="num">#${String(q.numero).padStart(3,'0')}</td>
      <td>${esc(q.cliente || 'sem cliente')}<div class="mvsub">${sit}</div></td>
      <td class="num">${money(num(q.total)||0)}</td>
      <td class="num" style="color:var(--green)">${money(pago)}</td>
      <td class="num" style="font-weight:600; color:var(--amber)">${money(falta)}</td>
      <td style="white-space:nowrap; width:1%">
        <button class="btn small" data-rec-pedido="${q.id}">Registrar recebimento</button>
      </td></tr>`;
  }).join('');

  el.innerHTML = `<table><thead><tr>
    <th class="num">Nº</th><th>Cliente</th><th class="num">Total</th>
    <th class="num">Já pago</th><th class="num">Falta</th><th class="num">Ação</th>
    </tr></thead><tbody>${rows}</tbody>
    <tfoot><tr><td colspan="4"></td>
      <td class="num" style="font-weight:700; color:var(--amber)">${money(total)}</td><td></td></tr></tfoot></table>`;

  el.querySelectorAll('[data-rec-pedido]').forEach(b => {
    b.onclick = () => prodReceber(b.dataset.recPedido);
  });
}

/* ---------- CSV do extrato ---------- */
function baixarExtratoCSV(){
  const lista = montarMovimentos(periodoFiltro);
  if(!lista.length){ toast('Nada para exportar neste período','warn'); return; }
  const linhas = [['Data','Tipo','Descrição','Detalhe','Entrada','Saída','Quem']];
  lista.forEach(m => {
    const [rot] = MOV_ROTULO[m.tipo] || ['—'];
    linhas.push([ m.data, rot,
      String(m.titulo).replace(/<[^>]*>/g,''), String(m.detalhe).replace(/<[^>]*>/g,''),
      m.dir === 1 ? money2(m.valor) : '', m.dir === -1 ? money2(m.valor) : '', m.quem ]);
  });
  const csv = '﻿' + linhas.map(l => l.map(c => '"' + String(c).replace(/"/g,'""') + '"').join(';')).join('\n');
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([csv], {type:'text/csv;charset=utf-8'}));
  a.download = 'extrato-144lab-' + hojeISO() + '.csv';
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 1500);
}

let finPage = 1;
function renderFinance(){
  renderMovimentos();
  renderAReceber();
  const list=expenses.filter(e=>inPeriod(e.data,periodoFiltro));
  // por categoria
  const porCat={}; list.forEach(e=>porCat[e.categoria]=(porCat[e.categoria]||0)+num(e.valor));
  const ents=Object.entries(porCat).sort((a,b)=>b[1]-a[1]);
  const max=Math.max(1,...ents.map(e=>e[1]));
  $('fin-chart').innerHTML= ents.length
    ? ents.map(([c,v])=>`<div class="bar-row"><span class="lab">${esc(c)}</span>
        <div class="bar-track"><div class="bar-fill" style="width:${(v/max)*100}%; background:var(--red)"></div></div>
        <span class="val">${money(v)}</span></div>`).join('')
    : '<div class="empty">Sem gastos no período.</div>';
  // lançamentos
  const pager=$('fin-pager');
  if(!list.length){ $('fin-list').innerHTML='<div class="empty">Nenhum lançamento no período.</div>'; pager.innerHTML=''; return; }

  const termoBusca = norm($('fin-search') ? $('fin-search').value : '');
  let listBusca = [...list].sort((a,b)=>String(b.data||'').localeCompare(String(a.data||''))||b.id-a.id);
  if(termoBusca){
    listBusca = listBusca.filter(e => norm(e.categoria||'').includes(termoBusca) || norm(e.descricao||'').includes(termoBusca));
  }
  if(!listBusca.length){ $('fin-list').innerHTML='<div class="empty">Nenhum lançamento encontrado.</div>'; pager.innerHTML=''; return; }

  const pageSizeVal = $('fin-pagesize') ? $('fin-pagesize').value : '10';
  const pageSize = pageSizeVal==='all' ? listBusca.length : parseInt(pageSizeVal,10);
  const totalPaginas = Math.max(1, Math.ceil(listBusca.length/pageSize));
  if(finPage > totalPaginas) finPage = totalPaginas;
  if(finPage < 1) finPage = 1;
  const inicio = (finPage-1)*pageSize;
  const listPag = listBusca.slice(inicio, inicio+pageSize);

  const rows=listPag.map(e=>`
    <tr><td>${fmtDate(e.data)}${e.usuarioNome?'<div class="autor">'+esc(e.usuarioNome)+'</div>':''}</td><td><span class="badge">${esc(e.categoria)}</span></td>
    <td>${esc(e.descricao)||'—'}</td><td class="num" style="color:var(--red)">${money(num(e.valor))}</td>
    <td class="num"><button class="btn small danger" onclick="expDel(\'${jsId(e.id)}\')">×</button></td></tr>`).join('');
  $('fin-list').innerHTML=`<table><thead><tr><th>Data / quem</th><th>Categoria</th><th>Descrição</th><th class="num">Valor</th><th></th></tr></thead><tbody>${rows}</tbody></table>`;

  if(totalPaginas <= 1){
    pager.innerHTML = `<small style="color:var(--ink-dim)">${listBusca.length} ${listBusca.length===1?'lançamento':'lançamentos'}</small>`;
  } else {
    pager.innerHTML = `
      <button class="btn small ghost" id="fin-pg-prev" ${finPage<=1?'disabled':''}>← Anterior</button>
      <small style="color:var(--ink-dim)">Página ${finPage} de ${totalPaginas} · ${listBusca.length} lançamentos</small>
      <button class="btn small ghost" id="fin-pg-next" ${finPage>=totalPaginas?'disabled':''}>Próxima →</button>`;
    $('fin-pg-prev').onclick = ()=>{ finPage--; renderFinance(); };
    $('fin-pg-next').onclick = ()=>{ finPage++; renderFinance(); };
  }
}
window.expDel=id=>{
  const _e = expenses.find(x=>String(x.id)===String(id));
  // compra de filamento: cancelar a compra devolve as gramas (tudo conversa)
  const fil = (_e && _e.filamentId) ? filaments.find(f=>String(f.id)===String(_e.filamentId)) : null;
  const gramas = fil ? (num(_e.gramas)||0) : 0;
  const msg = fil && gramas > 0
    ? 'Cancelar esta compra de filamento?<br><br><small style="font-weight:normal">Tira ' + money(num(_e.valor)) +
      ' das despesas e remove ' + gramas + ' g do estoque de ' + esc((fil.marca+' '+(fil.corNome||'')).trim()) +
      ' (hoje com ' + Math.round(num(fil.estoque)) + ' g).</small>'
    : 'Excluir este lançamento?';
  customConfirm(msg, () => {
    // relê: o rolo pode ter mudado por sincronização enquanto a pergunta estava aberta
    const ee = expenses.find(x=>String(x.id)===String(id));
    if(!ee){ toast('Esse lançamento não existe mais — a tela foi atualizada','warn'); atualizarTudo(); return; }
    const ff = ee.filamentId ? filaments.find(f=>String(f.id)===String(ee.filamentId)) : null;
    expenses=expenses.filter(x=>String(x.id)!==String(id)); save('knx3d_expenses',expenses);
    if(ff && gramas > 0){
      ff.estoque = Math.max(0, (num(ff.estoque)||0) - gramas);
      save('knx3d_filaments', filaments);
      if(typeof renderFilaments === 'function') renderFilaments();
    }
    registrar('excluiu','Despesa', _e ? (_e.categoria+(_e.descricao?' — '+_e.descricao:'')) : id, _e?_e.valor:0);
    atualizarTudo();
    toast(fil && gramas > 0 ? 'Compra cancelada — ' + gramas + ' g saíram do estoque' : 'Lançamento excluído','warn');
  });
};
