if($('mov-search'))   $('mov-search').addEventListener('input', ()=>{ movPage=1; renderMovimentos(); });
if($('mov-tipo'))     $('mov-tipo').addEventListener('change', ()=>{ movPage=1; renderMovimentos(); });
if($('mov-pagesize')) $('mov-pagesize').addEventListener('change', ()=>{ movPage=1; renderMovimentos(); });
if($('mov_csv'))      $('mov_csv').onclick = baixarExtratoCSV;
$('fin-pagesize').addEventListener('change',()=>{ finPage=1; renderFinance(); });

/* ---------- dashboard ---------- */
// periodoFiltro e periodoFiltro viraram o mesmo periodoFiltro
$('dash-filters').querySelectorAll('button').forEach(b=>{
  b.onclick=()=>setPeriodo(b.dataset.f);
});
function renderDashboard(){
  const vs=sales.filter(s=>inPeriod(s.data,periodoFiltro));
  const bruto=vs.reduce((s,x)=>s+saleGross(x),0);
  const taxasVenda=vs.reduce((s,x)=>s+saleFee(x),0);
  const receita=bruto-taxasVenda;               // o que foi VENDIDO no período
  const custoProd=vs.reduce((s,x)=>s+num(x.custoUnit)*num(x.qtd),0);
  const desp=expenses.filter(e=>inPeriod(e.data,periodoFiltro)).reduce((s,e)=>s+num(e.valor),0);

  // CAIXA = o que de fato ENTROU no período.
  // Venda comum entra na data da venda. Pedido entra pelas datas dos
  // recebimentos (sinal num mês, saldo no outro) — por isso a venda
  // gerada pelo pedido não é contada aqui, senão contaria duas vezes.
  const entrouVendas  = vs.filter(x => !x.pedidoId).reduce((a,x)=>a+saleNet(x),0);
  const entrouPedidos = recebidoDePedidos(periodoFiltro);
  const entrou    = entrouVendas + entrouPedidos;
  const resultado = entrou - desp;              // caixa: entrou − saiu
  const aReceber  = totalAReceber();
  // um pedido com 5 itens gera 5 linhas de venda — contar linhas inflava o
  // número de pedidos e cortava o ticket médio pela metade
  const chavePedido = s => s.pedidoId ? 'P'+s.pedidoId : (s.mkt && s.mkt.pedido ? 'M'+s.canal+s.mkt.pedido : 'V'+s.id);
  const pedidos=new Set(vs.map(chavePedido)).size, unidades=vs.reduce((s,x)=>s+num(x.qtd),0);
  const ticket=pedidos?receita/pedidos:0;
  const margem=receita?((receita-desp)/receita)*100:0;
  
  const activeProds = products.filter(p=>p.ativo!==false);
  // Inclui as peças em poder de parceiros: elas saíram de p.estoque mas continuam sendo suas
  const estoquePreco = activeProds.reduce((s,p) => s + (estoqueTotalPeca(p)*num(p.preco)), 0);
  const estoqueCusto = activeProds.reduce((s,p) => s + (estoqueTotalPeca(p)*num(p.custo)), 0);

  // Quebra do valor de venda por local
  const porLocal = {};
  LOCAIS_DEF.forEach(l => { porLocal[l.key] = 0; });
  let valConsig = 0;
  activeProds.forEach(p => {
    LOCAIS_DEF.forEach(l => { porLocal[l.key] += estoqueLocal(p,l.key) * num(p.preco); });
    valConsig += consignadoDe(p) * num(p.preco);
  });
  const linhaLocais = LOCAIS_DEF.filter(l=>porLocal[l.key]>0)
      .map(l => l.nome+' '+money(porLocal[l.key]))
      .concat(valConsig>0 ? ['Com parceiros '+money(valConsig)] : [])
      .join(' · ');

  $('dash-kpis').innerHTML=`
    <div class="kpi hero"><div><div class="k">Faturado no período</div><div class="v money">${money(receita)}</div></div>
      <div class="sub">${plural(pedidos,'pedido','pedidos')} · ${plural(unidades,'peça','peças')} · já sem as taxas</div></div>
    <div class="kpi"><div><div class="k">Despesas</div><div class="v" style="color:var(--red)">${money(desp)}</div></div>
      <div class="sub">o que saiu no período</div></div>
    <div class="kpi"><div><div class="k">Resultado (caixa)</div><div class="v" style="color:${resultado>=0?'var(--green)':'var(--red)'}">${money(resultado)}</div></div>
      <div class="sub">o que entrou &minus; o que saiu</div></div>
    <div class="kpi"><div><div class="k">Margem</div><div class="v" style="color:${margem>=0?'var(--ink)':'var(--red)'}">${pct(margem)}</div></div>
      <div class="sub">sobre o faturado</div></div>

    <div class="statstrip">
      <div><div class="k">Estoque a venda</div><div class="v">${money(estoquePreco)}</div>
        ${veCustoAgora() ? `<div class="s">${money(estoqueCusto)} investido</div>` : ''}${linhaLocais?`<div class="s" style="white-space:nowrap; overflow:hidden; text-overflow:ellipsis" title="${linhaLocais}">${linhaLocais}</div>`:''}</div>
      <div><div class="k">Pedidos</div><div class="v">${pedidos}</div><div class="s">no período (não linhas)</div></div>
      <div><div class="k">Ticket médio</div><div class="v">${money(ticket)}</div><div class="s">por pedido</div></div>
      <div><div class="k">Unidades vendidas</div><div class="v">${unidades}</div><div class="s">peças</div></div>
      ${veCustoAgora() ? `<div><div class="k">Custo das vendas</div><div class="v">${money(custoProd)}</div><div class="s">matéria-prima</div></div>` : ''}
      ${aReceber>0?`<div><div class="k">A receber</div><div class="v" style="color:var(--amber)">${money(aReceber)}</div>
        <div class="s">saldo de pedidos em aberto</div></div>`:''}
    </div>`;
  // resultado de caixa detalhado
  $('dash-resultado').innerHTML=`
    <div class="q-sub"><span>Entrou de vendas</span><span>${money(entrouVendas)}</span></div>
    ${entrouPedidos>0?`<div class="q-sub"><span>Entrou de pedidos (sinais e saldos)</span><span>${money(entrouPedidos)}</span></div>`:''}
    <div class="q-sub"><span>− Despesas (filamentos, equipamento, etc.)</span><span style="color:var(--red)">${money(desp)}</span></div>
    <div class="q-sub" style="border-top:1px solid var(--line); margin-top:6px; padding-top:8px; color:var(--ink); font-weight:600">
      <span>= Resultado (caixa)</span><span style="color:${resultado>=0?'var(--green)':'var(--red)'}">${money(resultado)}</span></div>
    <div class="q-sub" style="margin-top:8px; color:var(--ink-dim); font-size:12px"><span>Faturado no período (vendas registradas, já sem taxas)</span><span>${money(receita)}</span></div>
    ${aReceber>0?`<div class="q-sub" style="color:var(--amber); font-size:12px"><span>Ainda a receber de pedidos em aberto</span><span>${money(aReceber)}</span></div>`:''}
    ${veCustoAgora() ? `<div class="q-sub" style="color:var(--ink-dim); font-size:12px"><span>Custo estimado dos produtos vendidos (só precificação)</span><span>${money(custoProd)}</span></div>` : ''}`;
  // alertas + cadastros
  const low=filaments.filter(f=>(num(f.estoque)||0)<200);
  const abertos=quotes.length;
  let al='';
  al+=`<div class="q-sub"><span>Impressoras</span><span>${printers.reduce((s,p)=>s+(num(p.qtd)||0),0)}</span></div>`;
  al+=`<div class="q-sub"><span>Produtos</span><span>${products.filter(p=>p.ativo!==false).length}</span></div>`;
  al+=`<div class="q-sub"><span>Filamentos</span><span>${filaments.length}</span></div>`;
  al+=`<div class="q-sub"><span>Clientes</span><span>${clients.length}</span></div>`;
  al+=`<div class="q-sub"><span>Orçamentos salvos</span><span>${abertos}</span></div>`;
  if(low.length){
    al+=`<div style="margin-top:10px" class="stock-low">Estoque baixo</div>`;
    low.forEach(f=>al+=`<div class="q-sub stock-low"><span>${esc(f.marca)}</span><span>${(f.estoque||0)} g</span></div>`);
  } else {
    al+=`<div style="margin-top:10px" class="stock-ok">Estoques de filamento ok</div>`;
  }
  $('dash-alertas').innerHTML=al;
  // gráfico faturamento por produto
  // Usa o mesmo bruto do KPI de Receita: preço × qtd menos o desconto
  const porProd={}; vs.forEach(s=>porProd[s.nome]=(porProd[s.nome]||0)+Math.max(0,(num(s.precoUnit)||0)*(num(s.qtd)||0)-(num(s.descontoValor)||0)));
  const ents=Object.entries(porProd).sort((a,b)=>b[1]-a[1]);
  const max=Math.max(1,...ents.map(e=>e[1]));
  $('dash-chart').innerHTML= ents.length
    ? ents.map(([n,v])=>`<div class="bar-row"><span class="lab">${esc(n)}</span>
        <div class="bar-track"><div class="bar-fill" style="width:${(v/max)*100}%"></div></div>
        <span class="val">${money(v)}</span></div>`).join('')
    : '<div class="empty">Sem vendas no período.</div>';

  if(typeof renderAlertasResumo === 'function') renderAlertasResumo();
}


/* ================================================================
   FILAMENTOS (estoque) e IMPRESSORAS (parque)
   ================================================================ */
function money2(n){ return (isFinite(n)?n:0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}); }

// ---- selects da calculadora ----
function fillSelect(sel, items, fmt){
  const prev=sel.value;
  sel.innerHTML = items.length
    ? items.map(it=>`<option value="${it.id}">${fmt(it)}</option>`).join('')
    : '<option value="">— usar padrão das Configurações —</option>';
  if(prev && items.some(it=>String(it.id)===prev)) sel.value=prev;
}
function renderCalcSelects(){
  fillSelect($('c_printer'), printers, p=>`${esc(p.nome)}${p.qtd>1?' (×'+p.qtd+')':''}`);
  fillSelect($('c_filament'), filaments, f=>`${esc(f.marca)} ${esc(f.corNome||f.material||'')} — R$ ${money2(f.prkg)}/kg`);
}
function updateHprinter(){
  const total=printers.reduce((s,p)=>s+(num(p.qtd)||0),0);
  $('hprinter').textContent=total+' impressora'+(total===1?'':'s');
}

// ---- Filamentos ----
let filPage = 1;
function renderFilaments(){
  const el=$('fil-list'), pager=$('fil-pager');
  if(!filaments.length){ el.innerHTML='<div class="empty">Nenhum filamento cadastrado. Adicione acima.</div>'; pager.innerHTML=''; return; }

  const termoBusca = norm($('fil-search') ? $('fil-search').value : '');
  let list = filaments;
  if(termoBusca){
    list = list.filter(f => norm(f.marca).includes(termoBusca) || norm(f.corNome||'').includes(termoBusca) || norm(f.material||'').includes(termoBusca));
  }
  if(!list.length){ el.innerHTML='<div class="empty">Nenhum filamento encontrado.</div>'; pager.innerHTML=''; return; }

  const pageSizeVal = $('fil-pagesize') ? $('fil-pagesize').value : '10';
  const pageSize = pageSizeVal==='all' ? list.length : parseInt(pageSizeVal,10);
  const totalPaginas = Math.max(1, Math.ceil(list.length/pageSize));
  if(filPage > totalPaginas) filPage = totalPaginas;
  if(filPage < 1) filPage = 1;
  const inicio = (filPage-1)*pageSize;
  const listPag = list.slice(inicio, inicio+pageSize);

  const rows=listPag.map(f=>{
    const low=(num(f.estoque)||0)<200;
    return `<tr>
      <td><span class="swatch-lg" style="background:${corSegura(f.cor)}"></span>${esc(f.marca)}${f.corNome?' <span style="color:var(--ink-soft)">'+esc(f.corNome)+'</span>':''}</td>
      <td>${f.material?esc(f.material):'—'}</td>
      <td class="num">R$ ${money2(f.prkg)}</td>
      <td class="num ${low?'stock-low':''}">
      ${(f.estoque||0).toLocaleString('pt-BR')} g <span style="font-size:11px; opacity:0.7">(${Math.min(100, Math.max(0, (f.estoque||0)/10)).toFixed(0)}%)</span>
      <div style="height:4px; background:var(--line-soft); border-radius:2px; margin-top:4px; overflow:hidden"><div style="height:100%; width:${Math.min(100, Math.max(0, (f.estoque||0)/10))}%; background:${low?'var(--red)':'var(--ink-dim)'}"></div></div>
    </td>
      <td style="white-space:nowrap; width:1%;"><div style="display:flex; justify-content:flex-end; gap:6px;"><button class="btn small" onclick="filComprar(\'${jsId(f.id)}\')">Comprar 1kg</button>
        <button class="btn small" onclick="filEdit(\'${jsId(f.id)}\')">Editar</button>
        <button class="btn small danger" onclick="filDel(\'${jsId(f.id)}\')">Excluir</button>
      </div></td></tr>`;
  }).join('');
  el.innerHTML=`<table><thead><tr>
    <th>Filamento</th><th>Material</th><th class="num">R$/kg</th><th class="num">Estoque</th><th class="num">Ações</th>
    </tr></thead><tbody>${rows}</tbody></table>`;

  if(totalPaginas <= 1){
    pager.innerHTML = `<small style="color:var(--ink-dim)">${list.length} ${list.length===1?'item':'itens'}</small>`;
  } else {
    pager.innerHTML = `
      <button class="btn small ghost" id="fil-pg-prev" ${filPage<=1?'disabled':''}>← Anterior</button>
      <small style="color:var(--ink-dim)">Página ${filPage} de ${totalPaginas} · ${list.length} itens</small>
      <button class="btn small ghost" id="fil-pg-next" ${filPage>=totalPaginas?'disabled':''}>Próxima →</button>`;
    $('fil-pg-prev').onclick = ()=>{ filPage--; renderFilaments(); };
    $('fil-pg-next').onclick = ()=>{ filPage++; renderFilaments(); };
  }
}
$('fil-search').addEventListener('input',()=>{ filPage=1; renderFilaments(); });
$('fil-pagesize').addEventListener('change',()=>{ filPage=1; renderFilaments(); });
function clearFilForm(){
  $('f_marca').value=''; $('f_material').value=''; $('f_cor').value='#9aa3b2'; $('f_cornome').value='';
  $('f_prkg').value=''; $('f_estoque').value=''; $('f_pct').value='';
  $('f_add').dataset.editing=''; $('f_add').textContent='Adicionar';
}
$('f_add').onclick=()=>{
  const marca=($('f_marca').value||'').trim();
  if(!marca){ toast('Informe a marca do filamento','warn'); return; }
  const obj={ marca, material:($('f_material').value||'').trim(), cor:$('f_cor').value,
    corNome:($('f_cornome').value||'').trim(), prkg:num($('f_prkg').value), estoque:num($('f_estoque').value) };
  const editing=$('f_add').dataset.editing;
  if(editing){ const i=filaments.findIndex(x=>String(x.id)===String(editing)); if(i>=0){ obj.id=editing; filaments[i]=Object.assign({}, filaments[i], obj); } }
  else{ obj.id=uid(); filaments.push(carimbar(obj)); }
  save('knx3d_filaments',filaments);
  registrar(editing?'editou':'criou','Filamento', (obj.marca+' '+(obj.corNome||'')).trim(), obj.prkg);
  // cadastrar um filamento NOVO com estoque e preço lança o investimento automaticamente
  if(!editing && obj.estoque>0 && obj.prkg>0){
    const custoCompra=(obj.estoque/1000)*obj.prkg;
    const nome=(obj.marca+(obj.corNome?' '+obj.corNome:'')).trim();
    expenses.push(carimbar({ id:uid(), data:hojeLocal(), categoria:'Filamento',
      descricao:'Compra '+nome+' ('+obj.estoque+' g)', valor:custoCompra,
      filamentId: obj.id, gramas: obj.estoque }));
    save('knx3d_expenses',expenses);
    registrar('comprou','Filamento', nome + ' — ' + obj.estoque + ' g', custoCompra);
    atualizarTudo();
    toast('Filamento salvo · '+money(custoCompra)+' lançado como investimento','ok');
  } else {
    toast('Filamento salvo','ok');
  }
  fecharModal(); clearFilForm(); renderFilaments(); renderCalcSelects();
};

$('f_estoque').addEventListener('input', e => { $('f_pct').value = (num(e.target.value) / 10).toFixed(1).replace('.0','').replace('.',','); });
$('f_pct').addEventListener('input', e => { $('f_estoque').value = Math.round(num(e.target.value) * 10); });

window.filEdit=id=>{
  const f=filaments.find(x=>String(x.id)===String(id)); if(!f) return;
  $('f_marca').value=f.marca; $('f_material').value=f.material||''; $('f_cor').value=f.cor||'#9aa3b2';
  $('f_cornome').value=f.corNome||'';
  $('f_prkg').value=String(f.prkg).replace('.',','); $('f_estoque').value=f.estoque; $('f_pct').value=f.estoque ? (f.estoque/10).toFixed(1).replace('.0','').replace('.',',') : '0';
  $('f_add').dataset.editing=id; $('f_add').textContent='Salvar alterações';
  abrirModalForm('Editar filamento', 'form-fil', 'f_add');
};
// comprar rolo: repõe estoque E lança o gasto no financeiro (vai pro dashboard)
window.filComprar=id=>{
  const f=filaments.find(x=>String(x.id)===String(id)); if(!f) return;
  const valor=f.prkg||0;
  const nome=(f.marca+(f.corNome?' '+f.corNome:'')).trim();
  customConfirm('Comprar 1 rolo (1000 g) de ' + esc(nome) + '?<br><br><small style="color:var(--ink-soft); font-weight:normal;">Repõe +1000 g no estoque e lança <b style="color:var(--amber)">'+money(valor)+'</b> no Financeiro.</small>', () => {
    f.estoque=(f.estoque||0)+1000; save('knx3d_filaments',filaments);
    expenses.push(carimbar({ id:uid(), data:hojeLocal(), categoria:'Filamento',
      descricao:'Rolo '+nome+' (1000 g)', valor, filamentId: f.id, gramas: 1000 }));
    save('knx3d_expenses',expenses);
    registrar('comprou','Filamento', nome + ' — 1000 g', valor);
    renderFilaments(); atualizarTudo();
    toast('Comprado: +1000 g · '+money(valor)+' lançado no financeiro','ok');
  });
};
window.filDel=id=>{
  customConfirm('Excluir este filamento?', () => {
    const _f = filaments.find(x=>String(x.id)===String(id));
    filaments=filaments.filter(x=>String(x.id)!==String(id)); save('knx3d_filaments',filaments);
    registrar('excluiu','Filamento', _f ? (_f.marca+' '+(_f.corNome||'')).trim() : id);
    renderFilaments(); renderCalcSelects(); toast('Filamento excluído','warn');
  });
};

// ---- Impressoras ----
function renderPrinters(){
  const el=$('printer-list');
  if(!printers.length){ el.innerHTML='<div class="empty">Nenhuma impressora cadastrada.</div>'; return; }
  const rows=printers.map(p=>`<tr>
    <td>${esc(p.nome)}</td>
    <td class="num">${p.qtd}</td>
    <td class="num">${p.pot} kW</td>
    <td class="num">R$ ${money2(p.maq)}/h</td>
    <td style="white-space:nowrap; width:1%;"><div style="display:flex; justify-content:flex-end; gap:6px;"><button class="btn small" onclick="prEdit(\'${jsId(p.id)}\')">Editar</button>
      <button class="btn small danger" onclick="prDel(\'${jsId(p.id)}\')">Excluir</button>
    </div></td></tr>`).join('');
  el.innerHTML=`<table><thead><tr>
    <th>Impressora</th><th class="num">Qtd</th><th class="num">Potência</th><th class="num">Máquina/h</th><th class="num">Ações</th>
    </tr></thead><tbody>${rows}</tbody></table>`;
}
function clearPrForm(){
  $('p_nome').value=''; $('p_qtd').value='1'; $('p_pot').value=''; $('p_maq').value='';
  $('p_add').dataset.editing=''; $('p_add').textContent='Adicionar';
}
$('p_add').onclick=()=>{
  const nome=($('p_nome').value||'').trim();
  if(!nome){ toast('Informe o nome/modelo da impressora','warn'); return; }
  const obj={ nome, qtd:Math.max(1,Math.round(num($('p_qtd').value)||1)),
    pot:num($('p_pot').value), maq:num($('p_maq').value) };
  const editing=$('p_add').dataset.editing;
  if(editing){ const i=printers.findIndex(x=>String(x.id)===String(editing)); if(i>=0){ obj.id=editing; printers[i]=obj; } }
  else{ obj.id=uid(); printers.push(carimbar(obj)); }
  save('knx3d_printers',printers);
  registrar(editing?'editou':'criou','Impressora', obj.nome);
  fecharModal(); clearPrForm(); renderPrinters(); renderCalcSelects(); updateHprinter();
  toast('Impressora salva','ok');
};
window.prEdit=id=>{
  const p=printers.find(x=>String(x.id)===String(id)); if(!p) return;
  $('p_nome').value=p.nome; $('p_qtd').value=p.qtd;
  $('p_pot').value=String(p.pot).replace('.',','); $('p_maq').value=String(p.maq).replace('.',',');
  $('p_add').dataset.editing=id; $('p_add').textContent='Salvar alterações';
  abrirModalForm('Editar impressora', 'form-printer', 'p_add');
};
window.prDel=id=>{
  customConfirm('Excluir esta impressora?', () => {
    const _pr = printers.find(x=>String(x.id)===String(id));
    printers=printers.filter(x=>String(x.id)!==String(id)); save('knx3d_printers',printers);
    registrar('excluiu','Impressora', _pr ? _pr.nome : id);
    renderPrinters(); renderCalcSelects(); updateHprinter(); toast('Impressora excluída','warn');
  });
};

/* ---------- Estimador de Prazo ---------- */
let estCfg = load('knx3d_est_cfg', { maq: 2, pcs: 25, hrs: 9, dia: 24, folga: 2 });

function fillEstCfg() {
  $('est_maq').value = estCfg.maq;
  $('est_pcs_maq').value = estCfg.pcs;
  $('est_hrs_ciclo').value = String(estCfg.hrs).replace('.', ',');
  $('est_hrs_dia').value = String(estCfg.dia).replace('.', ',');
  $('est_folga').value = estCfg.folga;
}

$('est_save_cfg').onclick = () => {
  estCfg = {
    maq: Math.max(1, Math.round(num($('est_maq').value) || 2)),
    pcs: Math.max(1, Math.round(num($('est_pcs_maq').value) || 25)),
    hrs: num($('est_hrs_ciclo').value) || 9,
    dia: Math.max(1, num($('est_hrs_dia').value) || 24),
    folga: Math.round(num($('est_folga').value) || 0)
  };
  save('knx3d_est_cfg', estCfg);
  fillEstCfg();
  toast('Padrões do estimador salvos', 'ok');
};

$('btn_calc_est').onclick = () => {
  const qtdPedido = Math.round(num($('est_qtd_pedido').value));
  if (qtdPedido <= 0) { toast('Informe a quantidade do pedido', 'warn'); return; }

  // Pega os valores direto da tela (caso você tenha mudado para este cálculo específico sem salvar como padrão)
  const numMaquinas = Math.max(1, Math.round(num($('est_maq').value) || 2));
  const pecasPorMaquina = Math.max(1, Math.round(num($('est_pcs_maq').value) || 25));
  const horasPorCiclo = num($('est_hrs_ciclo').value) || 9;
  const horasPorDia = Math.max(1, num($('est_hrs_dia').value) || 24);
  const folgaSeguranca = Math.round(num($('est_folga').value) || 0);

  // Fórmula exata
  const pecasPorCiclo = numMaquinas * pecasPorMaquina;
  const ciclos = Math.ceil(qtdPedido / pecasPorCiclo);
  const horasImpressao = ciclos * horasPorCiclo;
  const diasImpressao = Math.ceil(horasImpressao / horasPorDia);
  const prazoDias = diasImpressao + folgaSeguranca;

  // Calculando a data prevista
  const dataPrev = new Date();
  dataPrev.setDate(dataPrev.getDate() + prazoDias);

  // Exibição
  $('est_res_dias').textContent = prazoDias + (prazoDias === 1 ? ' DIA' : ' DIAS');
  $('est_res_data').textContent = 'Previsto para: ' + dataPrev.toLocaleDateString('pt-BR');
  $('est_res_detalhes').textContent = ciclos + (ciclos === 1 ? ' ciclo' : ' ciclos') + ' · ' + horasImpressao.toLocaleString('pt-BR', {maximumFractionDigits:1}) + ' horas totais de impressão';
  
  $('est_resultado_box').style.display = 'block';
};

