// mostra/esconde o bloco de permissões conforme o perfil e liga os atalhos
function ligarPermissoesUI(){
  const sel = $('u_perfil');
  if(!sel) return;
  const atualiza = () => {
    const admin = sel.value === 'ADMIN';
    if($('u_perm_box'))   $('u_perm_box').style.display   = admin ? 'none' : '';
    if($('u_perm_admin')) $('u_perm_admin').style.display = admin ? '' : 'none';
  };
  sel.onchange = atualiza;
  atualiza();

  const marcar = v => $('modal-form-body')
    .querySelectorAll('#u_perm_box input[type=checkbox]')
    .forEach(c => c.checked = v);
  if($('u_perm_todas'))   $('u_perm_todas').onclick   = () => marcar(true);
  if($('u_perm_nenhuma')) $('u_perm_nenhuma').onclick = () => marcar(false);
}

function lerPermissoesForm(){
  return [...$('modal-form-body').querySelectorAll('#u_perm_box input[type=checkbox]')]
    .filter(c => c.checked)
    .map(c => c.dataset.perm);
}

async function salvarUsuario(id){
  const nome  = ($('u_nome').value||'').trim();
  const login = ($('u_login').value||'').trim();
  const senha = $('u_senha') ? $('u_senha').value : '';
  const perfil= $('u_perfil').value;

  const aviso = $('u_erro');
  if(aviso){ aviso.style.display = 'none'; aviso.textContent = ''; }

  if(!nome){ toast('Informe o nome','warn'); $('u_nome').focus(); return; }
  if(!id){
    if(!login || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(login)){ toast('Informe um e-mail válido','warn'); $('u_login').focus(); return; }
    if(!senha || senha.length < 8){
      if(aviso){
        aviso.innerHTML = '<b>Senha curta demais.</b><br>Use pelo menos 8 caracteres. ' +
          'Seu projeto no Supabase recusa senhas menores.';
        aviso.style.display = 'block';
      }
      toast('A senha precisa de pelo menos 8 caracteres','warn');
      $('u_senha').focus(); return;
    }
  }

  const btn = $('u_salvar');
  if(btn){ btn.disabled = true; btn.textContent = 'Salvando…'; }
  try{
    const lista = perfil === 'ADMIN' ? [] : lerPermissoesForm();
    const r = await Cloud.usersAction({ action: id ? 'update' : 'create', id, nome, login, senha, perfil });
    // guarda as permissões pelo id do usuário (novo ou existente)
    const alvo = id || (r && (r.id || (r.user && r.user.id))) ||
                 ((users.find(x => x.login === login) || {}).id);
    if(alvo && perfil !== 'ADMIN') salvarPermissoes(alvo, lista);
    if(alvo && perfil === 'ADMIN' && permissoes[alvo]){ delete permissoes[alvo]; cfg.permissoes = permissoes; save('knx3d_config', cfg); }
    fecharModal();
    renderUsers();
    toast(id ? 'Usuário atualizado' : 'Usuário criado', 'ok');
  }catch(e){
    // A mensagem fica na tela até você fechar — erro de servidor some rápido demais num toast.
    const texto = (e && e.message) ? e.message : String(e);
    console.error('[Usuários] falha ao salvar:', e);
    if(aviso){
      aviso.innerHTML = '<b>Não foi possível salvar.</b><br>' + esc(texto) +
        '<br><small>Se a mensagem citar “erp-users” ou “Function not found”, a função de criação de ' +
        'usuários não está publicada no Supabase.</small>';
      aviso.style.display = 'block';
      aviso.scrollIntoView({block:'nearest'});
    }
    toast(texto, 'warn');
    if(btn){ btn.disabled = false; btn.textContent = id ? 'Salvar' : 'Criar usuário'; }
  }
}

