/* ---------- Login Logic ---------- */
$('login_logo_img').src = LOGO;

// mesAlvo: 'YYYY-MM' do mês que a foto representa. Sem valor = mês de hoje.
// tipo: 'fechamento' (mês encerrado) ou 'manual' (foto parcial no meio do mês).
window.takeStockSnapshot = (isAuto = false, mesAlvo = null, tipo = 'manual') => {
  const hoje = new Date();
  const mesAno = mesAlvo || (hoje.getFullYear() + '-' + String(hoje.getMonth() + 1).padStart(2, '0'));
  
  const snapshotData = products.filter(p => p.ativo !== false).map(p => ({
    id: p.id,
    nome: p.nome,
    categoria: p.categoria,
    local: p.local,
    locais: Object.assign({oficina:0, ml:0, shopee:0}, p.locais || {}),
    consignado: consignadoDe(p),
    estoque: estoqueTotalPeca(p),
    preco: p.preco || 0,
    custo: p.custo || 0
  }));
  
  const existingIdx = stockSnapshots.findIndex(s => s.mesAno === mesAno);
  if (existingIdx >= 0) {
    if (isAuto) {
      // Fechamento de mês sobrescreve qualquer foto parcial anterior daquele mês.
      // Fechamento já existente nunca é sobrescrito automaticamente.
      if (tipo === 'fechamento' && stockSnapshots[existingIdx].tipo !== 'fechamento') {
        stockSnapshots[existingIdx].dataHora = hoje.toISOString();
        stockSnapshots[existingIdx].tipo = 'fechamento';
        stockSnapshots[existingIdx].itens = snapshotData;
        save('knx3d_stock_snapshots', stockSnapshots);
      }
    } else {
      customConfirm('Já existe uma foto do estoque para este mês (' + mesAno + '). Deseja sobrescrever com os dados de AGORA?', () => {
        stockSnapshots[existingIdx].dataHora = hoje.toISOString();
        stockSnapshots[existingIdx].tipo = tipo;
        stockSnapshots[existingIdx].itens = snapshotData;
        save('knx3d_stock_snapshots', stockSnapshots);
        toast('Foto do estoque atualizada!', 'ok');
      });
    }
  } else {
    stockSnapshots.push({
      id: mesAno,
      mesAno: mesAno,
      dataHora: hoje.toISOString(),
      tipo: tipo,
      itens: snapshotData
    });
    save('knx3d_stock_snapshots', stockSnapshots);
    if (!isAuto) toast('Foto do estoque salva com sucesso!', 'ok');
  }
};

window.openMonthlyReportModal = () => {
  if (!stockSnapshots.length) {
    toast('Nenhum Snapshot (Foto de Estoque) encontrado.', 'warn');
    return;
  }
  
  const sel = $('rm_month_sel');
  sel.innerHTML = [...stockSnapshots].sort((a,b) => b.mesAno.localeCompare(a.mesAno)).map(s => {
    const [y, m] = s.mesAno.split('-');
    const date = new Date(y, parseInt(m)-1, 1);
    const label = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });
    return `<option value="${s.mesAno}">${label.charAt(0).toUpperCase() + label.slice(1)}</option>`;
  }).join('');
  
  $('rm_pdf_preview').style.display = 'none';
  $('rm_preview_msg').style.display = 'block';
  $('rm_preview_msg').textContent = 'Selecione o mês acima e clique em Gerar';
  
  $('modal-monthly-report').classList.add('active');
};

$('btn_rm_close').onclick = () => {
  $('modal-monthly-report').classList.remove('active');
  $('rm_pdf_preview').src = ''; // Limpa a memória do navegador ao fechar
};

$('btn_rm_generate').onclick = () => {
  const mesAno = $('rm_month_sel').value;
  if (!mesAno) return;

  $('rm_preview_msg').textContent = 'Gerando relatório na memória, aguarde...';
  $('rm_pdf_preview').style.display = 'none';

  const snapshot = stockSnapshots.find(s => s.mesAno === mesAno);
  if (!snapshot) {
    toast('Snapshot não encontrado para o mês', 'warn');
    return;
  }

  // --- 1. Vendas do mês ---
  const vendasMes = sales.filter(s => s.data.startsWith(mesAno));
  let totalVendasLiq = 0;
  let totalVendasQtd = 0;

  let vendasRows = '';
  if(vendasMes.length === 0) {
    vendasRows = '<tr><td colspan="4" style="text-align:center; padding:12px; color:#6b7280;">Nenhuma venda registrada neste mês.</td></tr>';
  } else {
    const vSort = [...vendasMes].sort((a,b) => String(a.data||'').localeCompare(String(b.data||'')));
    vSort.forEach(s => {
      const liq = saleNet(s);
      totalVendasLiq += liq;
      totalVendasQtd += s.qtd;
      vendasRows += `<tr>
        <td style="padding: 8px 10px; border-bottom: 1px solid #e5e7eb;">${fmtDate(s.data)}</td>
        <td style="padding: 8px 10px; border-bottom: 1px solid #e5e7eb; font-weight:600; color:#111827;">${esc(s.nome)} <span style="font-weight:normal; color:#6b7280; font-size:10px;">(${esc(s.canal)})</span></td>
        <td style="padding: 8px 10px; border-bottom: 1px solid #e5e7eb; text-align:center;">${s.qtd}</td>
        <td style="padding: 8px 10px; border-bottom: 1px solid #e5e7eb; text-align:right;">${money(liq)}</td>
      </tr>`;
    });
  }

  // --- 2. Estoque do snapshot (agrupado por local) ---
  let estoqueHtml = '';
  // 3 locais próprios + consignado. Fotos antigas caem no rótulo que tinham.
  const baldes = LOCAIS_DEF.map(l => ({ key:l.key, nome:l.nome }))
                 .concat([{ key:'consignado', nome:'Com parceiros' }]);
  const qtdBalde = (i, key) => {
    if(i.locais || i.consignado !== undefined){
      return (key === 'consignado') ? (num(i.consignado)||0) : (num(i.locais && i.locais[key])||0);
    }
    const antigo = (i.local === 'ML Full') ? 'ml'
                 : (i.local === 'Shopee Full' || i.local === 'Shopee') ? 'shopee' : 'oficina';
    return (key === antigo) ? (num(i.estoque)||0) : 0;
  };
  const locais = baldes;
  
  let valorTotalEstoque = 0;
  let pecasTotalEstoque = 0;

  locais.forEach(b => {
    const loc = b.nome;
    const itensLocal = snapshot.itens.filter(i => qtdBalde(i, b.key) > 0);
    if(!itensLocal.length) return;

    let rows = '';
    let subQtd = 0;
    let subVal = 0;
    
    itensLocal.forEach(it => {
      const qBal = qtdBalde(it, b.key);
      if (qBal <= 0) return;
      const val = qBal * it.preco;
      subQtd += qBal;
      subVal += val;
      rows += `<tr>
        <td style="padding: 8px 10px; border-bottom: 1px solid #e5e7eb; font-weight:600; color:#111827;">${esc(it.nome)} <span style="font-weight:normal; color:#6b7280; font-size:10px;">(${esc(it.categoria || 'Sem categoria')})</span></td>
        <td style="padding: 8px 10px; border-bottom: 1px solid #e5e7eb; text-align:center;">${qBal}</td>
        <td style="padding: 8px 10px; border-bottom: 1px solid #e5e7eb; text-align:right;">${money(it.preco)}</td>
        <td style="padding: 8px 10px; border-bottom: 1px solid #e5e7eb; text-align:right;">${money(val)}</td>
      </tr>`;
    });

    if(subQtd > 0) {
      valorTotalEstoque += subVal;
      pecasTotalEstoque += subQtd;
      estoqueHtml += `
        <h4 style="margin: 16px 0 8px; font-size: 12px; color: #4b5563; text-transform: uppercase; letter-spacing:0.5px;">Local: ${esc(loc)}</h4>
        <table style="width: 100%; border-collapse: collapse; border: 1px solid #e5e7eb; margin-bottom: 12px; font-size: 11px;">
          <thead style="background: #f9fafb;">
            <tr>
              <th style="text-align:left; padding:8px 10px; border-bottom: 1px solid #e5e7eb; color:#6b7280;">Produto</th>
              <th style="text-align:center; padding:8px 10px; border-bottom: 1px solid #e5e7eb; color:#6b7280;">Qtd</th>
              <th style="text-align:right; padding:8px 10px; border-bottom: 1px solid #e5e7eb; color:#6b7280;">Preço Venda</th>
              <th style="text-align:right; padding:8px 10px; border-bottom: 1px solid #e5e7eb; color:#6b7280;">Valor Total</th>
            </tr>
          </thead>
          <tbody>${rows}</tbody>
          <tfoot style="background: #f9fafb;">
            <tr>
              <td style="padding:8px 10px; text-align:right; font-weight:bold;">Subtotal ${esc(loc)}</td>
              <td style="padding:8px 10px; text-align:center; font-weight:bold; color:#111827;">${subQtd}</td>
              <td></td>
              <td style="padding:8px 10px; text-align:right; font-weight:bold; color: #111827;">${money(subVal)}</td>
            </tr>
          </tfoot>
        </table>
      `;
    }
  });

  if(!estoqueHtml) {
    estoqueHtml = '<div style="padding:16px; border: 1px dashed #d1d5db; border-radius:8px; text-align:center; color:#6b7280; font-size:12px;">Nenhum produto em estoque neste fechamento.</div>';
  }

  // --- 3. Montagem do HTML e injeção no PDF ---
  const [y, m] = mesAno.split('-');
  const nomeMes = new Date(y, parseInt(m)-1, 1).toLocaleString('pt-BR', { month: 'long', year: 'numeric' });
  const dataFechamento = new Date(snapshot.dataHora).toLocaleString('pt-BR');
  const tipoFoto = (snapshot.tipo === 'fechamento')
    ? 'Fechamento do mês (estoque final)'
    : 'Foto parcial — tirada durante o mês';

  const docHtml = `
    <div style="font-family: 'Inter', system-ui, sans-serif; color: #374151; padding: 24px; font-size: 12px; background: #ffffff; width: 720px; box-sizing: border-box; margin: 0 auto;">
      
      <!-- Cabeçalho -->
      <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #e5e7eb; padding-bottom: 16px; margin-bottom: 20px;">
        <div style="display: flex; align-items: center; gap: 12px;">
          <img src="${LOGO}" style="width: 56px; height: 56px; border-radius: 10px;">
          <div>
            <div style="font-size: 20px; font-weight: 800; color: #111827;">${esc(cfg.negocio||'144 Laboratório 3D')}</div>
            <div style="font-size: 11px; color: #6b7280;">Relatório de Fechamento Mensal</div>
          </div>
        </div>
        <div style="text-align: right;">
          <h2 style="margin: 0 0 4px; font-size: 20px; font-weight: 800; color: #e54c00; text-transform: capitalize;">${nomeMes}</h2>
          <div style="font-size: 11px; color: #4b5563;">Foto registrada em: <b>${dataFechamento}</b></div>
          <div style="font-size: 10px; color: #6b7280; margin-top: 2px;">${tipoFoto}</div>
        </div>
      </div>

      <!-- Resumo de Vendas -->
      <h3 style="margin: 0 0 12px; font-size: 15px; color: #111827; border-bottom: 2px solid #15803d; display: inline-block; padding-bottom: 4px;">Vendas do Mês</h3>
      <table style="width: 100%; border-collapse: collapse; border: 1px solid #e5e7eb; margin-bottom: 8px; font-size: 11px;">
        <thead style="background: #f9fafb;">
          <tr>
            <th style="text-align:left; padding:8px 10px; border-bottom: 1px solid #e5e7eb; color:#6b7280;">Data</th>
            <th style="text-align:left; padding:8px 10px; border-bottom: 1px solid #e5e7eb; color:#6b7280;">Produto</th>
            <th style="text-align:center; padding:8px 10px; border-bottom: 1px solid #e5e7eb; color:#6b7280;">Qtd</th>
            <th style="text-align:right; padding:8px 10px; border-bottom: 1px solid #e5e7eb; color:#6b7280;">Líquido Recebido</th>
          </tr>
        </thead>
        <tbody>${vendasRows}</tbody>
        <tfoot style="background: #f9fafb;">
          <tr>
            <td colspan="2" style="padding:10px; text-align:right; font-weight:bold; border-top:2px solid #e5e7eb;">Totais do Mês</td>
            <td style="padding:10px; text-align:center; font-weight:bold; font-size:14px; border-top:2px solid #e5e7eb; color:#111827;">${totalVendasQtd}</td>
            <td style="padding:10px; text-align:right; font-weight:bold; color:#15803d; font-size:14px; border-top:2px solid #e5e7eb;">${money(totalVendasLiq)}</td>
          </tr>
        </tfoot>
      </table>
      <div style="margin-bottom: 28px; font-size: 11px; color: #6b7280; text-align: right;">
        Ticket Médio Líquido do Mês: <b>${totalVendasQtd > 0 ? money(totalVendasLiq / vendasMes.length) : money(0)}</b>
      </div>

      <!-- Posição de Estoque -->
      <h3 style="margin: 0 0 4px; font-size: 15px; color: #111827; border-bottom: 2px solid #0369a1; display: inline-block; padding-bottom: 4px;">Posição de Estoque (Snapshot)</h3>
      ${estoqueHtml}
      
      <div style="background: #f9fafb; border: 1px dashed #d1d5db; border-radius: 8px; padding: 16px; margin-top: 20px; display: flex; justify-content: space-between; align-items: center;">
        <div style="font-size: 13px; font-weight: 700; color: #4b5563; text-transform: uppercase;">Total Geral em Estoque</div>
        <div style="text-align: right;">
          <span style="font-size: 14px; font-weight: 800; color: #111827; margin-right: 16px;">${pecasTotalEstoque} peças</span>
          <span style="font-size: 16px; font-weight: 700; color: #0369a1;">${money(valorTotalEstoque)}</span>
        </div>
      </div>
      
    </div>
  `;

  const opt = {
    margin:       [5, 5, 5, 5],
    filename:     `Fechamento_${mesAno}.pdf`,
    image:        { type: 'jpeg', quality: 0.98 },
    html2canvas:  { scale: 2, useCORS: true },
    jsPDF:        { unit: 'mm', format: 'a4', orientation: 'portrait' }
  };

  if(!pdfDisponivel()){
    carregarPDF(() => $('btn_rm_generate').onclick(), () => {
      $('rm_preview_msg').textContent = 'Não foi possível gerar: o arquivo html2pdf.bundle.min.js não está na pasta do sistema.';
    });
    return;
  }

  const element = document.createElement('div');
  element.innerHTML = docHtml;

  // Usa outputPdf('bloburl') para gerar a URL nativa do PDF e evitar o download forçado
  html2pdf().set(opt).from(element).outputPdf('bloburl').then((pdfUrl) => {
    $('rm_preview_msg').style.display = 'none';
    const iframe = $('rm_pdf_preview');
    iframe.src = pdfUrl;
    iframe.style.display = 'block';
    toast('Relatório do mês renderizado na tela!', 'ok');
  }).catch(err => {
    $('rm_preview_msg').textContent = 'Erro ao processar o arquivo. Verifique o console.';
    toast('Erro ao gerar relatório.', 'warn');
    console.error(err);
  });
};

