/* ================================================================
   RELATÓRIOS GERENCIAIS
   Regime de COMPETÊNCIA: o custo do produto entra como CMV no momento
   da venda. Compra de filamento é investimento em estoque, e compra de
   equipamento é imobilizado — nenhum dos dois é despesa operacional.
   Somar os três seria contar o mesmo custo duas vezes.
   ================================================================ */
function repPeriodo(){
  return { ini: $('rep_ini').value || '0000-01-01', fim: $('rep_fim').value || '9999-12-31' };
}
function repSales(){ const p=repPeriodo(); return sales.filter(s=>s.data>=p.ini && s.data<=p.fim); }
function repExp(){   const p=repPeriodo(); return expenses.filter(e=>e.data>=p.ini && e.data<=p.fim); }
function saleCMV(s){ return (num(s.custoUnit)||0)*(num(s.qtd)||0); }
function repPct(v,base){ return base>0 ? (v/base*100) : 0; }
function fpct(v){ return (isFinite(v)?v:0).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})+'%'; }

window.repPreset = tipo => {
  const h=new Date(), y=h.getFullYear(), m=h.getMonth();
  const f=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10);
  let a,b;
  if(tipo==='mes'){ a=new Date(y,m,1);   b=new Date(y,m+1,0); }
  else if(tipo==='ant'){ a=new Date(y,m-1,1); b=new Date(y,m,0); }
  else if(tipo==='90'){  b=h; a=new Date(h.getTime()-89*864e5); }
  else if(tipo==='ano'){ a=new Date(y,0,1); b=new Date(y,11,31); }
  else { a=new Date(2000,0,1); b=new Date(2099,11,31); }
  $('rep_ini').value=f(a); $('rep_fim').value=f(b);
  renderRelatorios();
};

function calcDRE(){
  const vs=repSales(), ex=repExp();
  const bruta   = vs.reduce((t,s)=>t+((num(s.precoUnit)||0)*(num(s.qtd)||0)),0);
  const desc    = vs.reduce((t,s)=>t+(num(s.descontoValor)||0),0);
  const taxas   = vs.reduce((t,s)=>t+saleFee(s),0);
  const liquida = bruta - desc - taxas;
  const cmv     = vs.reduce((t,s)=>t+saleCMV(s),0);
  const mc      = liquida - cmv;                        // margem de contribuição
  const opex    = ex.filter(e=>e.categoria!=='Filamento' && e.categoria!=='Equipamento')
                    .reduce((t,e)=>t+num(e.valor),0);
  const capex   = ex.filter(e=>e.categoria==='Equipamento').reduce((t,e)=>t+num(e.valor),0);
  const estq    = ex.filter(e=>e.categoria==='Filamento').reduce((t,e)=>t+num(e.valor),0);
  const unid    = vs.reduce((t,s)=>t+(num(s.qtd)||0),0);
  const mcPct   = repPct(mc, liquida);
  // CAIXA pela mesma regra do Dashboard e do Financeiro: venda comum entra na
  // data da venda; pedido entra pelas datas dos recebimentos (a venda gerada
  // pelo pedido não entra, senão o sinal contaria duas vezes).
  const per = repPeriodo();
  const entrouVendas = vs.filter(s => !s.pedidoId).reduce((t,s)=>t+saleNet(s),0);
  let entrouPedidos = 0;
  quotes.forEach(q => { if(!ehPedido(q)) return;
    prodRecebimentos(q).forEach(r => { if(r.data >= per.ini && r.data <= per.fim) entrouPedidos += num(r.valor)||0; }); });
  // um pedido de 5 itens são 5 linhas de venda — conta pedido, não linha
  const nPedidos = new Set(vs.map(s => s.pedidoId ? 'P'+s.pedidoId : (s.mkt && s.mkt.pedido ? 'M'+s.canal+s.mkt.pedido : 'V'+s.id))).size;
  return { bruta, desc, taxas, liquida, cmv, mc, mcPct, opex, capex, estq,
           resultado: mc - opex,
           caixa: entrouVendas + entrouPedidos - (opex + capex + estq),
           nVendas: nPedidos, unid,
           ticket: nPedidos ? liquida/nPedidos : 0,
           equilibrio: mcPct>0 ? opex/(mcPct/100) : 0 };
}

function calcABC(){
  const map={};
  repSales().forEach(s=>{
    const k=s.nome||'—';
    if(!map[k]) map[k]={nome:k, rec:0, qtd:0, cmv:0};
    map[k].rec += saleNet(s); map[k].qtd += num(s.qtd)||0; map[k].cmv += saleCMV(s);
  });
  const arr=Object.values(map).sort((a,b)=>b.rec-a.rec);
  const tot=arr.reduce((t,x)=>t+x.rec,0);
  let acc=0;
  arr.forEach(x=>{
    const antes = repPct(acc,tot);      // acumulado ANTES deste item
    acc+=x.rec;
    x.share=repPct(x.rec,tot); x.acum=repPct(acc,tot);
    // O item que ATRAVESSA a barreira pertence à classe de baixo:
    // sem isso, um produto único acumula 100% e cairia em C sendo o carro-chefe
    x.classe = antes < 80 ? 'A' : (antes < 95 ? 'B' : 'C');
    x.mc = x.rec - x.cmv; x.mcPct = repPct(x.mc, x.rec);
  });
  return {arr, tot};
}

