    '--green':'#059669', '--red':'#dc2626', '--amber':'#d97706',
    '--cyan':'#0369a1',  '--violet':'#7c3aed',
    '--ink':'#111827',   '--ink-soft':'#4b5563', '--ink-dim':'#6b7280',
