/* ---------- Gestão de Consignados ---------- */
let currentManageConsigId = null;

function renderConsigManage(id) {
  const c = consignments.find(x => String(x.id) === String(id));
  if (!c) return;
  
  // Inicializa controles caso não existam (termos antigos)
  c.status = c.status || 'Ativo';
  c.valorRecebido = num(c.valorRecebido || 0);
  (c.itens||[]).forEach(it => {
    it.qtdVendida = num(it.qtdVendida || 0);
    it.qtdDevolvida = num(it.qtdDevolvida || 0);
    it.qtdReposta = num(it.qtdReposta || 0);
  });

  // POTENCIAL do termo: valor da mercadoria em poder do parceiro (entregue + reposta - devolvida).
  // Serve para o documento/PDF do termo, NÃO para cobrança.
  let tVenda = 0, tReceber = 0;
  (c.itens||[]).forEach(it => {
    const ativa = (it.qtd || 0) + (it.qtdReposta || 0) - (it.qtdDevolvida || 0);
    const sub = Math.max(0, ativa) * (it.preco || 0);
    const rec = sub - (sub * ((it.repassePct || 0) / 100));
    tVenda += sub;
    tReceber += rec;
  });
  c.totalVenda = tVenda;
  c.totalReceber = tReceber;

  // REALIZADO: só o que foi vendido. É este valor que o parceiro deve.
  const real = consigRealizado(c);

  $('cm_title').textContent = 'Termo #' + String(c.numero).padStart(3,'0') + ' — ' + c.cliente;
  const pendente = Math.max(0, real.receber - c.valorRecebido);
  $('cm_subtitle').innerHTML = 'Status: <b style="color:'+(c.status==='Acertado'?'var(--green)':'var(--amber)')+'">' + c.status + '</b> | Pendente: <b>' + money(pendente) + '</b>';

  $('cm_total_receber').innerHTML = money(real.receber) +
    '<div style="font-size:11px; font-weight:500; color:var(--ink-dim); margin-top:4px;">' +
    'Potencial do termo: ' + money(c.totalReceber) + '</div>';
  $('cm_ja_recebido').textContent = money(c.valorRecebido);

  let rows = '';
  (c.itens||[]).forEach((it, i) => {
    const naRua = (it.qtd || 0) + (it.qtdReposta || 0) - (it.qtdVendida || 0) - (it.qtdDevolvida || 0);
    rows += `
      <tr>
        <td style="padding: 10px; border-bottom: 1px solid var(--line);">
          <div style="font-weight:600; color:var(--ink);">${esc(it.nome)}</div>
          <div style="font-size:11px; color:var(--ink-dim); margin-top:2px;">
            Env: ${it.qtd} | Vend: <span style="color:var(--green)">${it.qtdVendida}</span> | Dev: <span style="color:var(--red)">${it.qtdDevolvida}</span> | Rep: <span>${it.qtdReposta}</span>
          </div>
        </td>
        <td class="num" style="padding: 10px; border-bottom: 1px solid var(--line); text-align:center; font-size:16px; font-weight:700; color:${naRua>0?'var(--brand)':'var(--ink-dim)'};">${naRua}</td>
        <td style="padding: 10px; border-bottom: 1px solid var(--line); text-align:center;">
          <div style="display:flex; justify-content:center; gap:4px; flex-wrap:wrap;">
            <button class="btn small" style="padding:4px 6px; font-size:11px;" onclick="cmAcao(${jsId(i)}, 'vendeu')">+ Vend</button>
            <button class="btn small" style="padding:4px 6px; font-size:11px;" onclick="cmAcao(${jsId(i)}, 'devolveu')">+ Dev</button>
            <button class="btn small" style="padding:4px 6px; font-size:11px;" onclick="cmAcao(${jsId(i)}, 'repos')">+ Rep</button>
          </div>
        </td>
      </tr>
    `;
  });
  $('cm_items_list').innerHTML = rows;
  
  if(c.status === 'Acertado'){
    $('btn_cm_acertar').style.display = 'none';
  } else {
    $('btn_cm_acertar').style.display = 'inline-block';
  }

  // --- HISTÓRICO DE CONSIGNADO ---
  const hist = consigHistory.filter(h => String(h.consigId) === String(c.id));
  const elHist = $('cm_history_list');
  if (!hist.length) {
    elHist.innerHTML = '<div style="padding:8px 0; text-align:center; color:var(--ink-dim);">Nenhuma movimentação registrada para este termo.</div>';
  } else {
    const sortedHist = [...hist].sort((a,b) => String(b.data||'').localeCompare(String(a.data||'')));
    let histHtml = '';
    let currentMonth = '';

    sortedHist.forEach(h => {
      const d = new Date(h.data + 'T00:00:00');
      const mesAno = d.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });
      if (mesAno !== currentMonth) {
        histHtml += `<div style="font-weight:700; color:var(--ink); margin: 8px 0 4px; text-transform:capitalize; border-bottom:1px solid var(--line-soft); padding-bottom:2px;">${mesAno}</div>`;
        currentMonth = mesAno;
      }
      
      let acaoTxt = '';
      if (h.acao === 'entrega') acaoTxt = `<b style="color:var(--ink)">Entrega:</b> ${esc(h.detalhes)}`;
      else if (h.acao === 'vendeu') acaoTxt = `<b style="color:var(--green)">Vendeu:</b> ${h.qtd} un. ${esc(h.prodNome)}`;
      else if (h.acao === 'devolveu') acaoTxt = `<b style="color:var(--red)">Devolveu:</b> ${h.qtd} un. ${esc(h.prodNome)}`;
      else if (h.acao === 'repos') acaoTxt = `<b style="color:var(--cyan)">Repôs:</b> ${h.qtd} un. ${esc(h.prodNome)}`;
      else if (h.acao === 'pagamento') acaoTxt = `<b style="color:var(--amber)">Acerto/Pagto:</b> ${money(h.valor)}`;

      histHtml += `<div style="display:flex; justify-content:space-between; padding:4px 0; border-bottom:1px dashed var(--line-soft);">
        <span style="flex:1; padding-right:8px;">${acaoTxt}</span>
        <span style="font-family:var(--mono); font-size:11px; color:var(--ink-dim); flex:none;">${fmtDate(h.data)}</span>
      </div>`;
    });
    elHist.innerHTML = histHtml;
  }

  // --- INICIA O CRM NO CONSIGNADO ---
  $('cm_crm_data').value = hojeLocal();
  $('btn_cm_crm_add').dataset.cliente = c.clienteId || '';
  
  if(c.clienteId) {
    renderCrmList(c.clienteId, 'cm_crm_history_list');
    $('btn_cm_crm_add').disabled = false;
  } else {
    $('cm_crm_history_list').innerHTML = '<div class="empty" style="padding:16px; font-size:13px;">Termo avulso sem cliente vinculado. Não é possível usar o CRM.</div>';
    $('btn_cm_crm_add').disabled = true;
  }
}

