window.cmAcao = (idx, acao) => {
  if (!currentManageConsigId) return;
  const c = consignments.find(x => String(x.id) === String(currentManageConsigId));
  if (!c || c.status === 'Acertado') { toast('Termo já finalizado!', 'warn'); return; }
  
  const it = c.itens[idx];
  const naRua = (it.qtd || 0) + (it.qtdReposta || 0) - (it.qtdVendida || 0) - (it.qtdDevolvida || 0);

  let msg = '';
  if (acao === 'vendeu') msg = 'Quantas unidades de <b>' + esc(it.nome) + '</b> o parceiro VENDEU?';
  if (acao === 'devolveu') msg = 'Quantas unidades de <b>' + esc(it.nome) + '</b> o parceiro DEVOLVEU? <br><small>(Voltam pro seu estoque no sistema)</small>';
  if (acao === 'repos') msg = 'Quantas unidades de <b>' + esc(it.nome) + '</b> você REPÔS no ponto? <br><small>(Saem do seu estoque no sistema)</small>';

  customPrompt(msg, '1', (qtdStr) => {
    const q = Math.round(num(qtdStr));
    if (q <= 0) return;
    
    // Validar se não está devolvendo/vendendo mais do que tem na rua
    if ((acao === 'vendeu' || acao === 'devolveu') && q > naRua) {
      toast('Quantidade informada é maior do que a disponível no ponto!', 'warn');
      return;
    }

    // Busca pelo ID (seguro contra renomeação) ou pelo nome (fallback p/ termos velhos)
    const p = products.find(x => it.prodId ? String(x.id) === String(it.prodId) : x.nome === it.nome);

    if (acao === 'vendeu') {
      it.qtdVendida += q;

      // Baixa automática do rolo de filamento correspondente ao produto consignado vendido
      // Filamento não sai aqui: foi consumido na produção da peça,
      // antes mesmo dela ser entregue ao parceiro.

      toast('Venda registrada no ponto', 'ok');
    } else if (acao === 'devolveu') {
      it.qtdDevolvida += q;
      if(p) { entradaLocal(p, 'oficina', q); save('knx3d_products', products); }
      toast('Devolução registrada (+'+q+' no estoque)', 'ok');
    } else if (acao === 'repos') {
      if(p) migraLocais(p);
      if(p && q > estoqueLocal(p, 'oficina')){
        toast('Na Oficina há apenas ' + estoqueLocal(p,'oficina') + ' un. de ' + p.nome, 'warn');
        return;
      }
      it.qtdReposta += q;
      if(p) { baixaLocal(p, 'oficina', q); save('knx3d_products', products); }
      toast('Reposição registrada (-'+q+' do estoque)', 'ok');
    }

    consigHistory.push({
      id: uid(),
      consigId: currentManageConsigId,
      data: hojeLocal(),
      acao: acao,
      prodNome: it.nome,
      qtd: q
    });
    save('knx3d_consig_history', consigHistory);

    save('knx3d_consignments', consignments);
    renderConsigManage(currentManageConsigId);
    if(p) renderProducts(); // Atualiza a aba de produtos em background
  });
};

$('btn_cm_pagto').onclick = () => {
  if (!currentManageConsigId) return;
  const c = consignments.find(x => String(x.id) === String(currentManageConsigId));
  if (!c) return;
  
  const val = num($('cm_add_pagto').value);
  if (val <= 0) { toast('Digite um valor válido', 'warn'); return; }
  
  c.valorRecebido = (c.valorRecebido || 0) + val;
  save('knx3d_consignments', consignments);
  
  consigHistory.push({
    id: uid(),
    consigId: currentManageConsigId,
    data: hojeLocal(),
    acao: 'pagamento',
    valor: val
  });
  save('knx3d_consig_history', consigHistory);

  // CUSTO REAL DO ACERTO (COGS)
  // Antes o acerto entrava com custo 0 e virava 100% de margem no Dashboard.
  // O custo verdadeiro são as peças que o parceiro vendeu. Como o pagamento pode
  // ser parcelado, o custo é rateado na mesma proporção do que já foi recebido.
  // c.custoLancado guarda o acumulado, então cada acerto lança só a diferença.
  let custoAgora = 0;
  try{
    const realNow = consigRealizado(c);
    let custoVendidoTotal = 0;
    (c.itens||[]).forEach(it => {
      const p = products.find(x => it.prodId ? String(x.id)===String(it.prodId) : x.nome===it.nome);
      custoVendidoTotal += (num(it.qtdVendida)||0) * (p ? (num(p.custo)||0) : 0);
    });
    if(realNow.receber > 0){
      const prop        = Math.min(1, (num(c.valorRecebido)||0) / realNow.receber);
      const custoDevido = custoVendidoTotal * prop;
      const jaLancado   = num(c.custoLancado)||0;
      custoAgora = Math.max(0, Math.round((custoDevido - jaLancado)*100)/100);
    }
    c.custoLancado = (num(c.custoLancado)||0) + custoAgora;
    save('knx3d_consignments', consignments);
  }catch(e){ console.warn('Falha ao ratear custo do acerto', e); custoAgora = 0; }

  // Lança o recebimento como venda para injetar a receita no Dashboard e Caixa
  sales.push(carimbar({
    id: uid(),
    prodId: '',
    nome: 'Acerto Consig. #' + String(c.numero).padStart(3, '0') + ' (' + c.cliente + ')',
    custoUnit: custoAgora,
    precoUnit: val,
    qtd: 1,
    data: hojeLocal(),
    canal: 'Consignado',
    taxaPlat: 0,
    taxaCartao: 0,
    descontoValor: 0,
    pagamento: 'Acerto',
    cartaoTipo: '',
    cartaoBandeira: '',
    filamentId: 0,
    gramasBaixa: 0
  }));
  save('knx3d_sales', sales);
  registrar('recebeu','Acerto de consignado', c.cliente || '', val);
  renderSales();
  renderDashboard();
  
  $('cm_add_pagto').value = '';
  renderConsigManage(currentManageConsigId);
  toast('Pagamento de ' + money(val) + ' injetado no caixa!', 'ok');
};

$('btn_cm_acertar').onclick = () => {
  if (!currentManageConsigId) return;
  const _cAc = consignments.find(x => String(x.id) === String(currentManageConsigId));
  const _naRua = _cAc ? (_cAc.itens||[]).reduce((s,it)=>s+Math.max(0,(num(it.qtd)||0)+(num(it.qtdReposta)||0)-(num(it.qtdVendida)||0)-(num(it.qtdDevolvida)||0)),0) : 0;
  customConfirm('Deseja finalizar o acerto deste consignado?<br><br><small style="color:var(--ink-soft); font-weight:normal;">O status mudará para "Acertado" e não avisará mais sobre vencimentos.' + (_naRua>0 ? '<br><br><b style="color:var(--amber)">Atenção:</b> ainda há <b>'+_naRua+' un.</b> no ponto. Elas serão devolvidas ao seu estoque da Oficina.' : '') + '</small>', () => {
    const c = consignments.find(x => String(x.id) === String(currentManageConsigId));
    if (c) {
      // As peças que sobraram no ponto voltam para a Oficina. Sem isso elas somem
      // do inventário: saem de p.estoque na entrega e o consignadoDe ignora
      // termos "Acertado".
      let devolvidas = 0;
      (c.itens||[]).forEach(it => {
        const naRua = Math.max(0, (num(it.qtd)||0) + (num(it.qtdReposta)||0)
                                - (num(it.qtdVendida)||0) - (num(it.qtdDevolvida)||0));
        if(naRua <= 0) return;
        const p = products.find(x => it.prodId ? String(x.id)===String(it.prodId) : x.nome===it.nome);
        if(p){ entradaLocal(p, 'oficina', naRua); devolvidas += naRua; }
        it.qtdDevolvida = (num(it.qtdDevolvida)||0) + naRua;   // zera o saldo do termo
      });
      if(devolvidas > 0){ save('knx3d_products', products); renderProducts(); }

      c.status = 'Acertado';
      save('knx3d_consignments', consignments);
      if(devolvidas > 0) toast(devolvidas + ' un. voltaram para a Oficina', 'ok');
      renderConsigManage(currentManageConsigId);
      toast('Consignado finalizado!', 'ok');
    }
  });
};

