const blockSeller = (fn) => function(...args) {
  if (!pode('excluir')) {
    toast('Sua conta não tem permissão para excluir registros', 'warn');
    return;
  }
  return fn.apply(this, args);
};
const exigePerm = (chave, msg) => (fn) => function(...args) {
  if (!pode(chave)) { toast(msg, 'warn'); return; }
  return fn.apply(this, args);
};

