  values:()=>({config:cfg,products:products,sales:sales,quotes:quotes,printers:printers,filaments:filaments,clients:clients,crm_logs:crmLogs,services:services,expenses:expenses,stock_snapshots:stockSnapshots,prod_log:prodLog,consignments:consignments,consig_history:consigHistory,est_cfg:estCfg}),
