/* ---------- utilidades ---------- */
function ferNum(id, padrao) {
  var el = document.getElementById(id);
  if (!el) return padrao;
  var v = parseFloat(String(el.value).replace(',', '.'));
  return isFinite(v) ? v : padrao;
}
function ferLigado(id) {
  var el = document.getElementById(id);
  return el ? !!el.checked : false;
}
function ferSeg(id) {
  var box = document.getElementById(id);
  if (!box) return null;
  var b = box.querySelector('button.active');
  return b ? (b.dataset.v || null) : null;
}
function ferMarcarSeg(id, valor) {
  var box = document.getElementById(id);
  if (!box) return;
  box.querySelectorAll('button').forEach(function (b) {
    b.classList.toggle('active', b.dataset.v === valor);
  });
}
function ferDefinirOrigem(chave, dados) {
  FER.fontes[chave] = dados;
  if (FER.modo === chave) { FER.origem = dados; ferRecalcular(); }
}
function ferBindSeg(id, aoTrocar) {
  var box = document.getElementById(id);
  if (!box) return;
  box.onclick = function (ev) {
    var b = ev.target.closest('button');
    if (!b || !box.contains(b)) return;
    box.querySelectorAll('button').forEach(function (x) { x.classList.remove('active'); });
    b.classList.add('active');
    if (aoTrocar) aoTrocar(b.dataset.v);
  };
}

/* ---------- entrada: imagem ---------- */
function ferCarregarArquivo(file) {
  if (!file) return;
  if (!/^image\//.test(file.type)) { ferAviso('Isso não é uma imagem.'); return; }
  if (file.size > 25 * 1024 * 1024) { ferAviso('Imagem muito grande (máximo 25 MB).'); return; }
  FER.nomeArquivo = (file.name || 'peca').replace(/\.[^.]+$/, '').slice(0, 40);
  var url = URL.createObjectURL(file);
  var img = new Image();
  img.onload = function () {
    URL.revokeObjectURL(url);
    ferUsarImagem(img);
  };
  img.onerror = function () {
    URL.revokeObjectURL(url);
    ferAviso('Não consegui abrir essa imagem.');
  };
  img.src = url;
}

function ferUsarImagem(img) {
  var maxLado = 900;
  var w = img.naturalWidth || img.width, h = img.naturalHeight || img.height;
  if (!w || !h) { ferAviso('Imagem vazia.'); return; }
  var esc = Math.min(1, maxLado / Math.max(w, h));
  w = Math.max(2, Math.round(w * esc)); h = Math.max(2, Math.round(h * esc));
  var cv = document.createElement('canvas');
  cv.width = w; cv.height = h;
  var ctx = cv.getContext('2d', { willReadFrequently: true });
  ctx.clearRect(0, 0, w, h);
  ctx.drawImage(img, 0, 0, w, h);
  var d = ctx.getImageData(0, 0, w, h);

  // decide sozinho como recortar: transparência, fundo de uma cor, ou claro/escuro
  var an = GEO.analisarPixels(d.data, w, h);
  FER.analise = an;
  if (an.temAlfa) FER.recorteAuto = 'alfa';
  else if (an.fundoLiso) FER.recorteAuto = 'fundo';
  else FER.recorteAuto = 'tom';
  FER.limiarAuto = (FER.recorteAuto === 'alfa') ? 128
                 : (FER.recorteAuto === 'fundo') ? 60
                 : GEO.limiarOtsu(d.data, w, h);
  ferMarcarSeg('fer_recorte_seg', 'auto');
  var sl = document.getElementById('fer_limiar');
  if (sl) sl.value = FER.limiarAuto;
  var inv = document.getElementById('fer_inverter');
  if (inv) inv.checked = (FER.recorteAuto === 'tom') && an.fundoEscuro;

  var box = document.getElementById('fer_dropinfo');
  if (box) box.textContent = FER.nomeArquivo + ' — ' + w + '×' + h;

  FER.cores = {};
  FER.fontes.imagem = { px: d.data, w: w, h: h };
  if (FER.modo !== 'imagem') {
    ferMarcarSeg('fer_entrada_seg', 'imagem');
    ferTrocarModo('imagem');
  } else {
    FER.origem = FER.fontes.imagem;
    ferRecalcular();
  }
}

/* ---------- entrada: texto ---------- */
function ferDesenharTexto() {
  var txt = (document.getElementById('fer_texto') || {}).value || '';
  txt = txt.slice(0, 40);
  if (!txt.trim()) {
    FER.fontes.texto = null; FER.origem = null;
    FER.peca = null; FER.malhas = null;
    ferAviso(''); ferPintarTudo(); return;
  }
  var fonte = (document.getElementById('fer_fonte') || {}).value || 'Impact';
  var tamanho = 260;
  var cv = document.createElement('canvas');
  var ctx = cv.getContext('2d', { willReadFrequently: true });
  ctx.font = '700 ' + tamanho + 'px "' + fonte + '", sans-serif';
  var larg = Math.ceil(ctx.measureText(txt).width) + 80;
  cv.width = Math.min(2400, Math.max(40, larg));
  cv.height = Math.round(tamanho * 1.6);
  ctx = cv.getContext('2d', { willReadFrequently: true });
  ctx.fillStyle = '#fff';
  ctx.fillRect(0, 0, cv.width, cv.height);
  ctx.fillStyle = '#000';
  ctx.font = '700 ' + tamanho + 'px "' + fonte + '", sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(txt, cv.width / 2, cv.height / 2);
  var d = ctx.getImageData(0, 0, cv.width, cv.height);
  FER.origem = FER.fontes.texto = { px: d.data, w: cv.width, h: cv.height };
  FER.nomeArquivo = txt.replace(/[^\wÀ-ÿ -]/g, '').trim().slice(0, 24) || 'texto';
  var i = document.getElementById('fer_inverter'); if (i) i.checked = false;
  ferMarcarSeg('fer_recorte_seg', 'auto');
  FER.recorteAuto = 'tom'; FER.limiarAuto = 128;
  var sl2 = document.getElementById('fer_limiar'); if (sl2) sl2.value = 128;
  ferRecalcular();
}

/* ---------- entrada: formas ---------- */
function ferDesenharForma(nome) {
  var N = 600, cv = document.createElement('canvas');
  cv.width = N; cv.height = N;
  var ctx = cv.getContext('2d', { willReadFrequently: true });
  ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, N, N);
  ctx.fillStyle = '#000';
  ctx.beginPath();
  var c = N / 2, r = N * 0.42, i, a;
  if (nome === 'circulo') {
    ctx.arc(c, c, r, 0, Math.PI * 2);
  } else if (nome === 'quadrado') {
    var q = N * 0.16;
    ctx.moveTo(c - r + q, c - r); ctx.arcTo(c + r, c - r, c + r, c + r, q);
    ctx.arcTo(c + r, c + r, c - r, c + r, q); ctx.arcTo(c - r, c + r, c - r, c - r, q);
    ctx.arcTo(c - r, c - r, c + r, c - r, q); ctx.closePath();
  } else if (nome === 'coracao') {
    for (i = 0; i <= 200; i++) {
      var t = (i / 200) * Math.PI * 2;
      var x = 16 * Math.pow(Math.sin(t), 3);
      var y = 13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t);
      var px = c + x * (r / 17), py = c - y * (r / 17);
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.closePath();
  } else if (nome === 'estrela') {
    for (i = 0; i < 10; i++) {
      var rr = i % 2 ? r * 0.45 : r;
      a = (i / 10) * Math.PI * 2 - Math.PI / 2;
      var sx = c + Math.cos(a) * rr, sy = c + Math.sin(a) * rr;
      if (i === 0) ctx.moveTo(sx, sy); else ctx.lineTo(sx, sy);
    }
    ctx.closePath();
  } else if (nome === 'escudo') {
    ctx.moveTo(c - r, c - r * 0.95);
    ctx.lineTo(c + r, c - r * 0.95);
    ctx.lineTo(c + r, c + r * 0.15);
    ctx.quadraticCurveTo(c + r * 0.9, c + r * 0.85, c, c + r);
    ctx.quadraticCurveTo(c - r * 0.9, c + r * 0.85, c - r, c + r * 0.15);
    ctx.closePath();
  } else if (nome === 'hexagono') {
    for (i = 0; i < 6; i++) {
      a = (i / 6) * Math.PI * 2 - Math.PI / 2;
      var hx = c + Math.cos(a) * r, hy = c + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(hx, hy); else ctx.lineTo(hx, hy);
    }
    ctx.closePath();
  } else if (nome === 'flor') {
    for (i = 0; i <= 240; i++) {
      var tt = (i / 240) * Math.PI * 2;
      var rad = r * (0.62 + 0.38 * Math.abs(Math.cos(2.5 * tt)));
      var fx = c + Math.cos(tt) * rad, fy = c + Math.sin(tt) * rad;
      if (i === 0) ctx.moveTo(fx, fy); else ctx.lineTo(fx, fy);
    }
    ctx.closePath();
  } else { // gota
    ctx.moveTo(c, c - r);
    ctx.bezierCurveTo(c + r * 1.05, c - r * 0.15, c + r * 0.78, c + r, c, c + r);
    ctx.bezierCurveTo(c - r * 0.78, c + r, c - r * 1.05, c - r * 0.15, c, c - r);
    ctx.closePath();
  }
  ctx.fill();
  var d = ctx.getImageData(0, 0, N, N);
  FER.origem = FER.fontes.forma = { px: d.data, w: N, h: N };
  FER.nomeArquivo = nome;
  var iv = document.getElementById('fer_inverter'); if (iv) iv.checked = false;
  ferMarcarSeg('fer_recorte_seg', 'auto');
  FER.recorteAuto = 'tom'; FER.limiarAuto = 128;
  var sl3 = document.getElementById('fer_limiar'); if (sl3) sl3.value = 128;
  ferRecalcular();
}


/* ---------- separar o desenho nas cores reais da imagem ---------- */
/* Quantos pixels da imagem valem o menor detalhe que o bico imprime.        */
function ferMinPx(mascara, larguraMM, bicoMM) {
  var x0 = mascara.w, y0 = mascara.h, x1 = -1, y1 = -1;
  for (var y = 0; y < mascara.h; y++) for (var x = 0; x < mascara.w; x++) {
    if (!mascara.d[y * mascara.w + x]) continue;
    if (x < x0) x0 = x; if (x > x1) x1 = x;
    if (y < y0) y0 = y; if (y > y1) y1 = y;
  }
  if (x1 < 0) return 0;
  var maiorLado = Math.max(x1 - x0 + 1, y1 - y0 + 1);
  var pxPorMM = maiorLado / Math.max(1, larguraMM);
  var lado = 2.0 * bicoMM * pxPorMM;
  return Math.max(4, Math.round(lado * lado));
}

function ferQuantizar(px, w, h, mascara, k, minPx) {
  if (k <= 1) return null;
  var i, p, total = 0;
  for (i = 0; i < w * h; i++) if (mascara.d[i]) total++;
  if (total < 200) return null;

  // a borda suavizada mistura duas cores; se ela votar, vira uma "cor" falsa
  var lumTmp = new Float32Array(w * h);
  for (i = 0; i < w * h; i++) {
    if (!mascara.d[i]) continue;
    p = i * 4;
    lumTmp[i] = 0.299 * px[p] + 0.587 * px[p + 1] + 0.114 * px[p + 2];
  }
  var planaC = ferMascaraPlana(lumTmp, mascara, w, h, 6) || mascara;
  var totalPlano = 0;
  for (i = 0; i < w * h; i++) if (planaC.d[i]) totalPlano++;

  // amostra espalhada, pra dar sempre o mesmo resultado
  var passo = Math.max(1, Math.floor(totalPlano / 12000));
  var am = [], c = 0;
  for (i = 0; i < w * h; i++) {
    if (!planaC.d[i]) continue;
    if ((c++ % passo) !== 0) continue;
    p = i * 4;
    am.push([px[p], px[p + 1], px[p + 2]]);
  }
  if (am.length < k * 4) return null;

  // primeiro centro = cor media; os outros = o mais distante do que ja tem
  var media = [0, 0, 0];
  am.forEach(function (a) { media[0] += a[0]; media[1] += a[1]; media[2] += a[2]; });
  media = media.map(function (v) { return v / am.length; });
  var centros = [media];
  function distC(a, b) {
    var dr = a[0] - b[0], dg = a[1] - b[1], db = a[2] - b[2];
    return dr * dr + dg * dg + db * db;
  }
  while (centros.length < k) {
    var melhor = null, melhorD = -1;
    for (i = 0; i < am.length; i++) {
      var dm = Infinity;
      for (var j = 0; j < centros.length; j++) dm = Math.min(dm, distC(am[i], centros[j]));
      if (dm > melhorD) { melhorD = dm; melhor = am[i]; }
    }
    if (!melhor || melhorD <= 0) break;
    centros.push(melhor.slice());
  }
  k = centros.length;
  if (k < 2) return null;

  // Lloyd
  for (var it = 0; it < 12; it++) {
    var soma = [], cnt = [];
    for (i = 0; i < k; i++) { soma.push([0, 0, 0]); cnt.push(0); }
    for (i = 0; i < am.length; i++) {
      var qq = 0, dd = Infinity;
      for (var m = 0; m < k; m++) { var d2 = distC(am[i], centros[m]); if (d2 < dd) { dd = d2; qq = m; } }
      soma[qq][0] += am[i][0]; soma[qq][1] += am[i][1]; soma[qq][2] += am[i][2]; cnt[qq]++;
    }
    for (i = 0; i < k; i++) {
      if (!cnt[i]) continue;
      centros[i] = [soma[i][0] / cnt[i], soma[i][1] / cnt[i], soma[i][2] / cnt[i]];
    }
  }

  // rotula todo mundo
  var mascaras = [], contas = [];
  for (i = 0; i < k; i++) { mascaras.push(GEO.mascaraNova(w, h)); contas.push(0); }
  for (i = 0; i < w * h; i++) {
    if (!mascara.d[i]) continue;
    p = i * 4;
    var q = 0, best = Infinity;
    for (var n = 0; n < k; n++) {
      var dr = px[p] - centros[n][0], dg = px[p + 1] - centros[n][1], db = px[p + 2] - centros[n][2];
      var dv = dr * dr + dg * dg + db * db;
      if (dv < best) { best = dv; q = n; }
    }
    mascaras[q].d[i] = 1; contas[q]++;
  }

  var saida = [];
  for (i = 0; i < k; i++) {
    if (contas[i] < total * 0.005) continue;       // cor irrelevante: descarta
    saida.push({
      mascara: (minPx > 1) ? GEO.removerPequenos(mascaras[i], minPx, Math.max(2, minPx / 6))
                           : mascaras[i],
      cor: centros[i].map(function (v) { return Math.max(0, Math.min(255, Math.round(v))); }),
      n: contas[i]
    });
  }
  saida.sort(function (a, b) { return b.n - a.n; });
  return saida.length > 1 ? saida : null;
}

function ferCorCSS(c) {
  return 'rgb(' + (c[0] | 0) + ',' + (c[1] | 0) + ',' + (c[2] | 0) + ')';
}


/* Pixels LISOS: onde a cor nao esta mudando. A borda suavizada de um desenho
   (antialias) tem tom intermediario e, se entrar na conta, vira um nivel
   proprio — era isso que fazia degrauzinho concentrico dentro de cada letra. */
function ferMascaraPlana(lum, mascara, w, h, limiar) {
  // afasta 2 px da borda: ali a cor ainda esta misturada com o fundo
  var dentro = GEO.erodir(mascara, 2);
  if (!GEO.mascaraConta(dentro)) dentro = mascara;
  var plana = GEO.mascaraNova(w, h);
  var n = 0;
  for (var y = 1; y < h - 1; y++) {
    for (var x = 1; x < w - 1; x++) {
      var i = y * w + x;
      if (!dentro.d[i]) continue;
      if (!dentro.d[i - 1] || !dentro.d[i + 1] || !dentro.d[i - w] || !dentro.d[i + w]) continue;
      var gx = lum[i + 1] - lum[i - 1];
      var gy = lum[i + w] - lum[i - w];
      if (Math.sqrt(gx * gx + gy * gy) <= limiar) { plana.d[i] = 1; n++; }
    }
  }
  return n > 500 ? plana : null;       // desenho todo em degrade: usa tudo
}

/* Mediana 3x3 por dentro do desenho. Tira pontinho de ruido SEM apagar traço
   fino — que era o que quebrava o desenho da impressora em farelo. Borrão
   comum puxava a linha fina pra cor do fundo e ela sumia em pedaços.        */
function ferMediana(lum, mascara, w, h) {
  var out = new Float32Array(lum);
  var v = new Float32Array(9);
  for (var y = 0; y < h; y++) {
    for (var x = 0; x < w; x++) {
      var i = y * w + x;
      if (!mascara.d[i]) continue;
      var n = 0;
      for (var dy = -1; dy <= 1; dy++) {
        var yy = y + dy; if (yy < 0 || yy >= h) continue;
        for (var dx = -1; dx <= 1; dx++) {
          var xx = x + dx; if (xx < 0 || xx >= w) continue;
          var j = yy * w + xx;
          if (mascara.d[j]) v[n++] = lum[j];
        }
      }
      if (n < 5) continue;
      // insercao: n e no maximo 9
      for (var a = 1; a < n; a++) {
        var tmp = v[a], b = a - 1;
        while (b >= 0 && v[b] > tmp) { v[b + 1] = v[b]; b--; }
        v[b + 1] = tmp;
      }
      out[i] = v[(n - 1) >> 1];
    }
  }
  return out;
}

/* Borra o tom so por dentro do desenho (nao puxa o vazio pra dentro).        */
function ferBorrarTom(lum, mascara, w, h, raio) {
  if (raio < 1) return lum;
  var n = w * h;
  var soma = new Float32Array(n), peso = new Float32Array(n);
  var t1 = new Float32Array(n), p1 = new Float32Array(n);
  var x, y, i, acc, accP, idx;

  for (y = 0; y < h; y++) {
    acc = 0; accP = 0;
    for (x = -raio; x <= raio; x++) {
      idx = y * w + Math.min(w - 1, Math.max(0, x));
      if (mascara.d[idx]) { acc += lum[idx]; accP++; }
    }
    for (x = 0; x < w; x++) {
      t1[y * w + x] = acc; p1[y * w + x] = accP;
      var sai = y * w + Math.min(w - 1, Math.max(0, x - raio));
      var ent = y * w + Math.min(w - 1, Math.max(0, x + raio + 1));
      if (mascara.d[ent]) { acc += lum[ent]; accP++; }
      if (mascara.d[sai]) { acc -= lum[sai]; accP--; }
    }
  }
  for (x = 0; x < w; x++) {
    acc = 0; accP = 0;
    for (y = -raio; y <= raio; y++) {
      idx = Math.min(h - 1, Math.max(0, y)) * w + x;
      acc += t1[idx]; accP += p1[idx];
    }
    for (y = 0; y < h; y++) {
      soma[y * w + x] = acc; peso[y * w + x] = accP;
      var ys = Math.min(h - 1, Math.max(0, y - raio)) * w + x;
      var ye = Math.min(h - 1, Math.max(0, y + raio + 1)) * w + x;
      acc += t1[ye] - t1[ys]; accP += p1[ye] - p1[ys];
    }
  }
  var out = new Float32Array(n);
  for (i = 0; i < n; i++) out[i] = peso[i] > 0 ? soma[i] / peso[i] : lum[i];
  return out;
}

/* ---------- relevo: transforma os tons da imagem em degraus de altura ----------
   Agrupa os tons que a imagem REALMENTE tem, em vez de fatiar em partes
   iguais. Arte de cor chapada tem poucos tons: fatiar por quantil cortava no
   meio de uma cor lisa e o degrau saia granulado, meio positivo meio negativo.
   -------------------------------------------------------------------------- */
function ferNiveisDeTom(px, w, h, mascara, n, inverter, minPx) {
  if (n < 2) return null;
  var i, p, total = 0;
  var lum = new Float32Array(w * h);
  for (i = 0; i < w * h; i++) {
    if (!mascara.d[i]) continue;
    p = i * 4;
    // só a cor: compor com branco distorce a borda suavizada do PNG
    var L = 0.299 * px[p] + 0.587 * px[p + 1] + 0.114 * px[p + 2];
    if (inverter) L = 255 - L;
    lum[i] = L; total++;
  }
  if (total < 200) return null;

  // borra o tom só por dentro do desenho: sem isso, ruído da imagem vira
  // pontinho solto no relevo
  // duas passadas de mediana: limpa ruído e mantém traço fino inteiro
  lum = ferMediana(lum, mascara, w, h);
  lum = ferMediana(lum, mascara, w, h);

  // histograma SÓ dos pixels lisos: borda suavizada nao vota
  var plana = ferMascaraPlana(lum, mascara, w, h, 6) || mascara;
  var hist = new Float64Array(256);
  var totalPlano = 0;
  for (i = 0; i < w * h; i++) {
    if (!plana.d[i]) continue;
    hist[Math.max(0, Math.min(255, Math.round(lum[i])))]++;
    totalPlano++;
  }
  if (totalPlano < 200) return null;
  var ocupados = [];
  for (i = 0; i < 256; i++) if (hist[i] > 0) ocupados.push(i);
  if (ocupados.length < 2) return null;
  var menor = ocupados[0], maior = ocupados[ocupados.length - 1];
  if (maior - menor < 10) return null;               // imagem chapada de verdade

  // k-means de 1 dimensão em cima do histograma (rápido: só 256 caixinhas)
  var centros = [];
  for (i = 0; i < n; i++) centros.push(menor + (maior - menor) * (i + 0.5) / n);
  for (var it = 0; it < 40; it++) {
    var soma = new Float64Array(n), peso = new Float64Array(n);
    for (var t = menor; t <= maior; t++) {
      if (!hist[t]) continue;
      var melhor = 0, dd = Infinity;
      for (var c = 0; c < n; c++) {
        var d = Math.abs(t - centros[c]);
        if (d < dd) { dd = d; melhor = c; }
      }
      soma[melhor] += t * hist[t]; peso[melhor] += hist[t];
    }
    var mexeu = false;
    for (var k = 0; k < n; k++) {
      if (!peso[k]) continue;
      var novoC = soma[k] / peso[k];
      if (Math.abs(novoC - centros[k]) > 0.05) mexeu = true;
      centros[k] = novoC;
    }
    if (!mexeu) break;
  }

  // joga fora centro vazio e junta os que caíram quase no mesmo tom:
  // é o que impede uma cor lisa de virar dois degraus
  var pesoFinal = new Float64Array(n);
  for (var t2 = menor; t2 <= maior; t2++) {
    if (!hist[t2]) continue;
    var m2 = 0, d2 = Infinity;
    for (var c2 = 0; c2 < n; c2++) {
      var dv = Math.abs(t2 - centros[c2]);
      if (dv < d2) { d2 = dv; m2 = c2; }
    }
    pesoFinal[m2] += hist[t2];
  }
  var lista = [];
  for (var q = 0; q < n; q++) {
    if (pesoFinal[q] < totalPlano * 0.04) continue;  // tom de borda, nao e degrau
    lista.push({ c: centros[q], w: pesoFinal[q] });
  }
  lista.sort(function (a, b) { return a.c - b.c; });
  var juntos = [];
  for (var j = 0; j < lista.length; j++) {
    var ult = juntos[juntos.length - 1];
    var junta = Math.max(18, (maior - menor) * 0.14);
    if (ult && (lista[j].c - ult.c) < junta) {       // mesmo tom: funde
      var pw = ult.w + lista[j].w;
      ult.c = (ult.c * ult.w + lista[j].c * lista[j].w) / pw;
      ult.w = pw;
    } else {
      juntos.push({ c: lista[j].c, w: lista[j].w });
    }
  }
  if (juntos.length < 2) return null;

  var cortes = [];
  for (i = 1; i < juntos.length; i++) cortes.push((juntos[i - 1].c + juntos[i].c) / 2);

  var nn = juntos.length;
  // abertura pequena: so pra tirar pontinho. Grande demais quebra traco fino
  // em farelo, que era o que sujava o relevo
  var limpa = Math.max(1, Math.round(Math.min(w, h) / 600));
  var camadas = [];
  for (var nv = 0; nv < nn; nv++) {
    var m = GEO.mascaraNova(w, h);
    var corte = nv === 0 ? -Infinity : cortes[nv - 1];
    var teto = nv < nn - 1 ? cortes[nv] : Infinity;
    var sr = 0, sg = 0, sb = 0, cnt = 0;
    for (i = 0; i < w * h; i++) {
      if (!mascara.d[i] || lum[i] < corte) continue;
      m.d[i] = 1;                                    // acumulado: degrau segura o de cima
      if (lum[i] < teto) { p = i * 4; sr += px[p]; sg += px[p + 1]; sb += px[p + 2]; cnt++; }
    }
    if (!GEO.mascaraConta(m)) continue;
    // abre e fecha: mata pontinho solto e furinho, que é o que deixava o
    // degrau com cara de granulado
    m = GEO.dilatar(GEO.erodir(m, limpa), limpa);
    m = GEO.erodir(GEO.dilatar(m, limpa), limpa);
    m = GEO.mascaraInterseccao(m, mascara);
    if (nv > 0 && camadas.length) {
      m = GEO.mascaraInterseccao(m, camadas[camadas.length - 1].mascara);
    }
    // tira farelo que o bico nao imprime, mas NAO tapa buraco: buraco aqui e
    // o degrau de baixo aparecendo, e e o desenho
    if (minPx > 1) m = GEO.removerPequenos(m, minPx, Math.max(2, minPx / 6));
    if (nv > 0 && camadas.length) {
      m = GEO.mascaraInterseccao(m, camadas[camadas.length - 1].mascara);
    }
    if (!GEO.mascaraConta(m)) continue;
    camadas.push({
      mascara: m,
      cor: cnt ? [Math.round(sr / cnt), Math.round(sg / cnt), Math.round(sb / cnt)]
               : [17, 24, 39],
      altura: 0,
      empilhada: true,
      _tom: juntos[nv].c
    });
  }
  if (camadas.length < 2) return null;
  for (i = 0; i < camadas.length; i++) camadas[i].altura = (i + 1) / camadas.length;
  camadas.pedidos = n;
  return camadas;
}

/* ---------- cores escolhidas na mão ---------- */
function ferHexParaRGB(hex) {
  var m = /^#?([0-9a-f]{6})$/i.exec(String(hex || ''));
  if (!m) return null;
  var v = parseInt(m[1], 16);
  return [(v >> 16) & 255, (v >> 8) & 255, v & 255];
}
function ferRGBParaHex(c) {
  function d(v) { var s = Math.max(0, Math.min(255, Math.round(v))).toString(16); return s.length < 2 ? '0' + s : s; }
  return '#' + d(c[0]) + d(c[1]) + d(c[2]);
}
function ferCorDe(nome, padrao) {
  var esc2 = FER.cores && FER.cores[nome];
  return esc2 ? esc2 : (padrao || [150, 165, 186]);
}

/* ---------- o cálculo ---------- */
function ferRecalcular(atraso) {
  clearTimeout(FER.timer);
  FER.timer = setTimeout(ferProcessar, atraso == null ? 90 : atraso);
}

function ferProcessar() {
  if (!FER.origem) { FER.peca = null; FER.malhas = null; ferPintarTudo(); return; }
  if (FER.ocupado) { ferRecalcular(120); return; }
  FER.ocupado = true;
  FER.avisoLeve = '';
  FER.marca = (FER.marca || 0) + 1;
  FER.reparadas = null;
  FER.diag = null;
  var marca = document.getElementById('fer_calculando');
  if (marca) marca.style.display = '';
  try {
    var o = FER.origem;
    var modoRec = ferSeg('fer_recorte_seg') || 'auto';
    if (modoRec === 'auto') modoRec = FER.recorteAuto || 'tom';
    var lim = ferNum('fer_limiar', 128);
    var inverter = ferLigado('fer_inverter');
    var m;
    if (modoRec === 'fundo' && FER.analise && FER.analise.corFundo) {
      var dentroLigado = ferLigado('fer_fundo_dentro');
      m = GEO.mascaraPorFundo(o.px, o.w, o.h, FER.analise.corFundo, lim, !dentroLigado);
      FER.mioloTirado = 0;
      if (!dentroLigado) {
        // quanto ficou de fora por ser da cor do fundo mas estar DENTRO do
        // desenho: se for bastante, pode ser arte (letra branca) e o usuario
        // precisa saber que da pra trazer de volta num clique
        var comMiolo = GEO.mascaraPorFundo(o.px, o.w, o.h, FER.analise.corFundo, lim, false);
        var dif = GEO.mascaraConta(comMiolo) - GEO.mascaraConta(m);
        if (dif > GEO.mascaraConta(comMiolo) * 0.02) FER.mioloTirado = dif;
      }
      if (inverter) { for (var iq = 0; iq < m.d.length; iq++) m.d[iq] = m.d[iq] ? 0 : 1; }
    } else {
      m = GEO.mascaraDePixels(o.px, o.w, o.h, {
        usarAlfa: modoRec === 'alfa',
        limiar: lim,
        inverter: inverter
      });
    }
    ferAtualizarRotuloRecorte(modoRec);
    var suave = Math.round(ferNum('fer_suavizar', 1));
    if (suave > 0) m = GEO.suavizar(m, suave);
    var sujeira = ferNum('fer_sujeira', 1) / 100;
    if (sujeira > 0) m = GEO.limparSujeira(m, sujeira);

    var modelo = ferSeg('fer_modelo_seg') || 'chaveiro';
    var cfgTam = Math.min(300, Math.max(5, ferNum('fer_tamanho', 50)));
    var cfgBico = Math.max(0.1, ferNum('fer_bico', 0.4));
    var detalhe = ferSeg('fer_detalhe_seg') || 'chapado';
    if (FER.modo !== 'imagem') detalhe = 'chapado';   // texto e forma nao tem tom nem cor
    var nNiveis = parseInt(ferSeg('fer_niveis_seg') || '3', 10) || 3;
    var coresArte = null;
    if (detalhe === 'cor') {
      coresArte = ferQuantizar(o.px, o.w, o.h, m, Math.min(4, nNiveis),
                               ferMinPx(m, cfgTam, cfgBico));
      if (!coresArte) ferAvisoLeve('A imagem tem uma cor só — não deu pra separar.');
    } else if (detalhe === 'relevo') {
      coresArte = ferNiveisDeTom(o.px, o.w, o.h, m, nNiveis,
                                 ferLigado('fer_relevo_inv'), ferMinPx(m, cfgTam, cfgBico));
      if (!coresArte) {
        ferAvisoLeve('A imagem tem uma cor só — não tem tom pra virar relevo. '
          + 'Use "Chapado" ou uma imagem com sombreado.');
      } else if (coresArte.length < nNiveis) {
        ferAvisoLeve('A imagem tem ' + coresArte.length + ' tons de verdade, então usei '
          + coresArte.length + ' níveis. Pedir mais que isso só picotaria o desenho.');
      }
    }
    FER.detalhe = detalhe;

    var cfg = {
      modelo: modelo,
      larguraMM: Math.min(300, Math.max(5, ferNum('fer_tamanho', 50))),
      altBase: Math.min(20, Math.max(0.2, ferNum('fer_altbase', 2.4))),
      altArte: Math.min(20, Math.max(0, ferNum('fer_altarte', 1.2))),
      bordaMM: Math.min(30, Math.max(0, ferNum('fer_borda', 2.5))),
      arteVazada: ferLigado('fer_vazada'),
      argolaLigada: ferLigado('fer_argola'),
      argolaFuroMM: Math.min(15, Math.max(1, ferNum('fer_furo', 4))),
      argolaPosicao: ferSeg('fer_argola_seg') || 'topo',
      argolaParedeMM: Math.min(10, Math.max(0.4, ferNum('fer_parede', 2.2))),
      cantoMM: Math.max(0, ferNum('fer_canto', 3)),
      bicoMM: Math.max(0.1, ferNum('fer_bico', 0.4)),
      coresArte: coresArte,
      corBase: ferCorDe('base', null),
      corArte: ferCorDe('desenho', [17, 24, 39]),
      nfcLigado: ferLigado('fer_nfc'),
      nfcDiametroMM: Math.min(60, Math.max(8, ferNum('fer_nfc_diam', 25))),
      nfcProfundidadeMM: Math.min(6, Math.max(0.3, ferNum('fer_nfc_prof', 0.9))),
      nfcModo: ferSeg('fer_nfc_seg') || 'baixo'
    };
    var peca = MODELOS.construir(m, cfg);
    if (peca.erro) {
      FER.peca = null; FER.malhas = null;
      ferAviso(peca.erro);
    } else {
      FER.peca = peca;
      FER.malhas = MODELOS.malhas(peca);
    }
  } catch (e) {
    console.error('Ferramentas:', e);
    FER.peca = null; FER.malhas = null;
    ferAviso('Deu erro ao montar a peça. Tente uma imagem mais simples.');
  }
  if (marca) marca.style.display = 'none';
  FER.ocupado = false;
  ferPintarTudo();
}

var FER_RECORTE_DICA = {
  alfa:  'usando a transparência do PNG',
  fundo: 'tirando o fundo de uma cor só',
  tom:   'separando por claro e escuro'
};
function ferAtualizarRotuloRecorte(modo) {
  var el = document.getElementById('fer_recorte_dica');
  if (el) el.textContent = FER_RECORTE_DICA[modo] || '';
}

function ferAvisoLeve(txt) { FER.avisoLeve = txt; }

function ferAviso(txt) {
  var el = document.getElementById('fer_erro');
  if (!el) return;
  if (!txt) { el.style.display = 'none'; el.textContent = ''; return; }
  el.style.display = '';
  el.textContent = txt;
}

/* ---------- desenho ---------- */
function ferPintarTudo() {
  if (FER.visor === '2d') ferPintar2D(); else ferPintar3D();
  ferPintarInfo();
}

function ferPintar2D() {
  var cv = document.getElementById('fer_cv2d');
  if (!cv) return;
  var ctx = cv.getContext('2d');
  var W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H);
  var p = FER.peca;
  if (!p) return;
  var pad = 14;
  var k = Math.min((W - pad * 2) / p.larguraMM, (H - pad * 2) / p.alturaMM);
  var ox = (W - p.larguraMM * k) / 2, oy = (H - p.alturaMM * k) / 2;

  function caminho(grupos, cor, contorno) {
    if (!grupos || !grupos.length) return;
    ctx.beginPath();
    grupos.forEach(function (g) {
      [g.externo].concat(g.furos).forEach(function (anel) {
        anel.forEach(function (pt, i) {
          var x = ox + (pt[0] - p.minX) * p.escala * k;
          var y = oy + (pt[1] - p.minY) * p.escala * k;
          if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
        });
        ctx.closePath();
      });
    });
    ctx.fillStyle = cor;
    ctx.fill('evenodd');
    if (contorno) {
      ctx.strokeStyle = 'rgba(23,20,15,.35)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  }

  caminho(p.base, ferCorCSS(ferCorDe('base', [203, 213, 225])), true);

  // o bolso da tag aparece pontilhado, so pra conferir onde ficou
  if (p.nfc) {
    var bx = ox + (p.nfc.x - p.minX) * p.escala * k;
    var by = oy + (p.nfc.y - p.minY) * p.escala * k;
    ctx.save();
    ctx.setLineDash([4, 3]);
    ctx.strokeStyle = 'rgba(180,60,0,.75)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(bx, by, p.nfc.raioMM * k, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  }

  (p.camadas || []).forEach(function (c, i) {
    var nome = p.camadas.length > 1 ? ('cor' + (i + 1)) : 'desenho';
    caminho(c.grupos, ferCorCSS(ferCorDe(nome, c.cor)), (p.camadas.length > 1));
  });
}

/* mini render 3D por software: sem biblioteca, sem WebGL.
   Desenha a mesa, a sombra e depois a peca camada por camada, de baixo pra
   cima. Parede vem de anel (quadrilatero), nao de triangulo solto: e o que
   tirava aqueles fiapos na borda quando tinha muito nivel de relevo.        */
function ferPintar3D() {
  var cv = document.getElementById('fer_cv3d');
  if (!cv) return;
  var ctx = cv.getContext('2d');
  var W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H);
  var p = FER.peca;
  if (!p || !p.solidos || !p.solidos.length) return;

  var cx = p.larguraMM / 2, cy = p.alturaMM / 2;
  var zMax = 0;
  p.solidos.forEach(function (s) { if (s.z1 > zMax) zMax = s.z1; });
  var v = FER.vista;
  var cz1 = Math.cos(v.rz), sz1 = Math.sin(v.rz);
  var ca = Math.cos(v.rx), sa = Math.sin(v.rx);
  var tam = Math.max(p.larguraMM, p.alturaMM) || 1;
  var k = (Math.min(W, H) * 0.74 / tam) * v.zoom;

  function cam(x, y, z) {
    var dx = x - cx, dy = y - cy, dz = z - zMax / 2;
    var x1 = dx * cz1 - dy * sz1, y1 = dx * sz1 + dy * cz1;
    return [x1, y1 * ca + dz * sa, -y1 * sa + dz * ca];
  }
  function tela(x, y, z) {
    var c = cam(x, y, z);
    return [W / 2 + c[0] * k, H / 2 - c[1] * k];
  }
  // ponto do anel -> mm no espaco final (Y ja espelhado)
  function mm(pt) {
    return [(pt[0] - p.minX) * p.escala, p.alturaMM - (pt[1] - p.minY) * p.escala];
  }

  var luzD = [-0.34, 0.46, 0.82];
  function sombraDe(nx, ny, nz) {
    var L = Math.hypot(nx, ny, nz) || 1;
    return 0.44 + 0.56 * Math.max(0, (nx * luzD[0] + ny * luzD[1] + nz * luzD[2]) / L);
  }
  function corDe(base, luz) {
    return 'rgb(' + Math.min(255, Math.round(base[0] * luz + 30 * luz)) + ',' +
                    Math.min(255, Math.round(base[1] * luz + 30 * luz)) + ',' +
                    Math.min(255, Math.round(base[2] * luz + 30 * luz)) + ')';
  }

  /* ---------- a mesa da impressora ---------- */
  var meia = tam * 0.72;
  var zMesa = -0.02;
  (function mesa() {
    var q = [tela(cx - meia, cy - meia, zMesa), tela(cx + meia, cy - meia, zMesa),
             tela(cx + meia, cy + meia, zMesa), tela(cx - meia, cy + meia, zMesa)];
    ctx.beginPath();
    ctx.moveTo(q[0][0], q[0][1]);
    for (var i = 1; i < 4; i++) ctx.lineTo(q[i][0], q[i][1]);
    ctx.closePath();
    var g = ctx.createLinearGradient(0, H * 0.15, 0, H);
    g.addColorStop(0, '#d9d5cf'); g.addColorStop(1, '#c6c1ba');
    ctx.fillStyle = g; ctx.fill();
    ctx.save(); ctx.clip();
    ctx.strokeStyle = 'rgba(255,255,255,.55)'; ctx.lineWidth = 1;
    var passo = tam / 6;
    for (var t = -meia; t <= meia + 1e-6; t += passo) {
      var a1 = tela(cx + t, cy - meia, zMesa), a2 = tela(cx + t, cy + meia, zMesa);
      var b1 = tela(cx - meia, cy + t, zMesa), b2 = tela(cx + meia, cy + t, zMesa);
      ctx.beginPath(); ctx.moveTo(a1[0], a1[1]); ctx.lineTo(a2[0], a2[1]); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(b1[0], b1[1]); ctx.lineTo(b2[0], b2[1]); ctx.stroke();
    }
    ctx.restore();
    ctx.strokeStyle = 'rgba(23,20,15,.16)'; ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(q[0][0], q[0][1]);
    for (var j = 1; j < 4; j++) ctx.lineTo(q[j][0], q[j][1]);
    ctx.closePath(); ctx.stroke();
  })();

  /* ---------- sombra da peca na mesa ---------- */
  (function sombra() {
    ctx.save();
    ctx.fillStyle = 'rgba(23,20,15,.13)';
    ctx.beginPath();
    p.base.forEach(function (g) {
      [g.externo].concat(g.furos).forEach(function (anel) {
        for (var i = 0; i < anel.length; i++) {
          var m = mm(anel[i]);
          var t = tela(m[0] + tam * 0.012, m[1] - tam * 0.012, zMesa);
          if (i === 0) ctx.moveTo(t[0], t[1]); else ctx.lineTo(t[0], t[1]);
        }
        ctx.closePath();
      });
    });
    ctx.fill('evenodd');
    ctx.restore();
  })();

  /* ---------- paredes de um anel, em quadrilateros ---------- */
  function paredeAnel(anel, z0, z1, corBase, paraFora) {
    var n = anel.length;
    if (n < 3) return;
    var pts = [];
    for (var i = 0; i < n; i++) pts.push(mm(anel[i]));
    // area com sinal no espaco final decide de que lado esta o material
    var area = 0;
    for (var a = 0, b = n - 1; a < n; b = a++) {
      area += (pts[b][0] * pts[a][1]) - (pts[a][0] * pts[b][1]);
    }
    var horario = area < 0;
    var lados = [];
    for (var j = 0; j < n; j++) {
      var P1 = pts[j], P2 = pts[(j + 1) % n];
      var dx = P2[0] - P1[0], dy = P2[1] - P1[1];
      var L = Math.hypot(dx, dy);
      if (L < 1e-9) continue;
      // normal pra fora do material
      var nx = (horario ? dy : -dy) / L, ny = (horario ? -dx : dx) / L;
      if (!paraFora) { nx = -nx; ny = -ny; }
      var nc = cam(cx + nx, cy + ny, 0), no = cam(cx, cy, 0);
      var vnx = nc[0] - no[0], vny = nc[1] - no[1], vnz = nc[2] - no[2];
      if (vnz <= 0.02) continue;                       // costas da peca
      // estica meio pixel nas pontas pra nao abrir fresta entre vizinhos.
      // Em segmento curto a esticada passaria do proprio lado e viraria espeto
      var estica = Math.min(0.45 / k, L * 0.2);
      var ex = (dx / L) * estica, ey = (dy / L) * estica;
      var A = [P1[0] - ex, P1[1] - ey], B = [P2[0] + ex, P2[1] + ey];
      var q = [tela(A[0], A[1], z1), tela(B[0], B[1], z1),
               tela(B[0], B[1], z0), tela(A[0], A[1], z0)];
      var prof = (cam(A[0], A[1], z1)[2] + cam(B[0], B[1], z1)[2]) / 2;
      lados.push({ q: q, prof: prof, cor: corDe(corBase, sombraDe(vnx, vny, vnz)) });
    }
    lados.sort(function (m, n2) { return m.prof - n2.prof; });
    for (var w = 0; w < lados.length; w++) {
      var S = lados[w];
      ctx.fillStyle = S.cor;
      ctx.beginPath();
      ctx.moveTo(S.q[0][0], S.q[0][1]);
      for (var e = 1; e < 4; e++) ctx.lineTo(S.q[e][0], S.q[e][1]);
      ctx.closePath();
      ctx.fill();
    }
  }

  function tampa(grupos, z, corBase) {
    if (!grupos || !grupos.length) return;
    var n = cam(cx, cy, 1), o = cam(cx, cy, 0);
    ctx.fillStyle = corDe(corBase, sombraDe(n[0] - o[0], n[1] - o[1], n[2] - o[2]));
    ctx.beginPath();
    grupos.forEach(function (g) {
      [g.externo].concat(g.furos).forEach(function (anel) {
        for (var i = 0; i < anel.length; i++) {
          var m = mm(anel[i]);
          var t = tela(m[0], m[1], z);
          if (i === 0) ctx.moveTo(t[0], t[1]); else ctx.lineTo(t[0], t[1]);
        }
        ctx.closePath();
      });
    });
    ctx.fill('evenodd');
  }

  /* ---------- a peca, de baixo pra cima ---------- */
  var ordem = p.solidos.map(function (s, i) { return { s: s, i: i }; });
  ordem.sort(function (a, b) { return (a.s.z0 - b.s.z0) || (a.s.z1 - b.s.z1) || (a.i - b.i); });
  ordem.forEach(function (it) {
    var s = it.s;
    var cor = ferCorDe(s.nome, s.cor);
    s.grupos.forEach(function (g) {
      paredeAnel(g.externo, s.z0, s.z1, cor, true);
      g.furos.forEach(function (f) { paredeAnel(f, s.z0, s.z1, cor, false); });
    });
    tampa(s.grupos, s.z1, cor);
  });
}

function ferPintarInfo() {
  var box = document.getElementById('fer_info');
  var acoes = document.getElementById('fer_acoes');
  var p = FER.peca;
  if (!box) return;
  if (!p) {
    box.innerHTML = '<span class="u">Escolha uma imagem, escreva um texto ou pegue uma forma pronta.</span>';
    if (acoes) acoes.style.display = 'none';
    return;
  }
  ferAviso('');
  if (acoes) acoes.style.display = '';

  var ms = FER.malhas || { base: [], arte: [], pecas: [] };
  var nTri = (ms.pecas || []).reduce(function (a, x) { return a + x.tris.length; }, 0);
  var altTotal = p.altBase + (p.altArteReal != null ? p.altArteReal : (p.temArte ? p.altArte : 0));
  var volCm3 = ferVolumeCm3();
  var gramas = volCm3 * 1.24;          // PLA
  var linhas = [
    ['Tamanho', p.larguraMM.toFixed(1) + ' × ' + p.alturaMM.toFixed(1) + ' mm'],
    ['Altura total', altTotal.toFixed(1) + ' mm'],
    ['Material (PLA)', gramas < 1 ? 'menos de 1 g' : gramas.toFixed(1) + ' g'],
    ['Triângulos', nTri.toLocaleString('pt-BR')]
  ];
  var html = '<div class="fer-medidas">' + linhas.map(function (l) {
    return '<div><span>' + l[0] + '</span><b>' + l[1] + '</b></div>';
  }).join('') + '</div>';

  // lista de pecas: clica na bolinha e troca a cor
  if (ms.pecas && ms.pecas.length) {
    html += '<div class="fer-rot" style="margin-top:14px">Cores da peça</div>';
    html += '<div class="fer-pecas">' + ms.pecas.map(function (pc, i) {
      var rot = pc.nome === 'base' ? 'Base'
              : (pc.nome === 'desenho' ? 'Desenho'
              : (FER.detalhe === 'relevo' ? 'Nível ' : 'Cor ') + pc.nome.replace('cor', ''));
      var cor = ferCorDe(pc.nome, pc.cor);
      return '<label><input type="color" data-fercor="' + esc(pc.nome) +
             '" value="' + ferRGBParaHex(cor) + '"><span>' + esc(rot) + '</span></label>';
    }).join('') + '</div>';
  }

  if (p.nfc) {
    html += '<div class="fer-nfc-info">' +
      '<b>Tag NFC de ' + p.nfc.diametroMM + ' mm</b> — bolso de ' +
      p.nfc.prof.toFixed(1) + ' mm ' +
      (p.nfc.modo === 'fechado'
        ? 'fechado por dentro. Pause a impressão em <b>Z = ' + p.nfc.zPausa.toFixed(1) +
          ' mm</b>, encaixe a tag e mande continuar.'
        : 'aberto por baixo. Imprima normal e cole a tag no final.') +
      '</div>';
  }

  if (FER.mioloTirado) {
    html += '<div class="fer-nota">Tirei as partes da cor do fundo que estavam '
      + '<b>dentro</b> do desenho (miolo de letra, por exemplo). '
      + 'Se elas fazem parte da arte — tipo letra branca em fundo branco — '
      + '<button type="button" class="fer-link" id="fer_trazer_miolo">traga de volta</button>.</div>';
  }
  html += ferDiagHTML();

  var avisos = (p.avisos || []).slice();
  if (FER.avisoLeve) avisos.unshift(FER.avisoLeve);
  if (avisos.length) {
    html += '<div class="fer-avisos">' + avisos.map(function (a) {
      return '<div>' + esc(a) + '</div>';
    }).join('') + '</div>';
  }
  box.innerHTML = html;

  var btAn = document.getElementById('fer_analisar');
  if (btAn) btAn.onclick = function () {
    btAn.disabled = true; btAn.textContent = 'Analisando...';
    setTimeout(function () { ferAnalisar(); FER.reparoPassos = null; ferPintarInfo(); }, 20);
  };
  var btRep = document.getElementById('fer_reparar');
  if (btRep) btRep.onclick = function () {
    btRep.disabled = true; btRep.textContent = 'Reparando...';
    setTimeout(function () { ferReparar(); }, 20);
  };
  var btMiolo = document.getElementById('fer_trazer_miolo');
  if (btMiolo) btMiolo.onclick = function () {
    var cb = document.getElementById('fer_fundo_dentro');
    if (cb) { cb.checked = true; ferRecalcular(0); }
  };
  box.querySelectorAll('input[data-fercor]').forEach(function (inp) {
    inp.oninput = function () {
      var rgb = ferHexParaRGB(inp.value);
      if (!rgb) return;
      FER.cores = FER.cores || {};
      FER.cores[inp.dataset.fercor] = rgb;
      if (FER.visor === '2d') ferPintar2D(); else ferPintar3D();
    };
  });
}

function ferVolumeCm3() {
  var ms = FER.malhas;
  if (!ms || !ms.solidos) return 0;
  var total = 0;
  ms.solidos.forEach(function (s) {
    var v = 0;
    for (var i = 0; i < s.tris.length; i++) {
      var t = s.tris[i];
      v += (t[0][0] * (t[1][1] * t[2][2] - t[2][1] * t[1][2])
          - t[1][0] * (t[0][1] * t[2][2] - t[2][1] * t[0][2])
          + t[2][0] * (t[0][1] * t[1][2] - t[1][1] * t[0][2])) / 6;
    }
    total += Math.abs(v);
  });
  return total / 1000;
}


/* ---------- zip sem compressão: junta os STL num arquivo só ---------- */
var FER_CRC = null;
function ferCrc32(buf) {
  if (!FER_CRC) {
    FER_CRC = new Uint32Array(256);
    for (var n = 0; n < 256; n++) {
      var c = n;
      for (var q = 0; q < 8; q++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      FER_CRC[n] = c >>> 0;
    }
  }
  var crc = 0xFFFFFFFF;
  for (var i = 0; i < buf.length; i++) crc = FER_CRC[(crc ^ buf[i]) & 0xFF] ^ (crc >>> 8);
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

function ferZipAsync(arquivos) {
  return Promise.all(arquivos.map(function (a) {
    return ferComprimir(a.dados).then(function (c) {
      return (c && c.length < a.dados.length)
        ? { nome: a.nome, dados: a.dados, comp: c, metodo: 8 }
        : { nome: a.nome, dados: a.dados, comp: a.dados, metodo: 0 };
    });
  })).then(function (lista) { return ferZip(lista); });
}

function ferZip(arquivos) {
  // arquivos: [{nome, dados:Uint8Array}]
  var partes = [], central = [], desloc = 0;
  var enc = new TextEncoder();

  function u16(v) { return [v & 255, (v >> 8) & 255]; }
  function u32(v) { return [v & 255, (v >> 8) & 255, (v >> 16) & 255, (v >>> 24) & 255]; }

  arquivos.forEach(function (a) {
    var nome = enc.encode(a.nome);
    var crc = ferCrc32(a.dados);
    var corpo = a.comp || a.dados;
    var metodo = a.metodo || 0;
    var cab = [].concat(
      u32(0x04034b50), u16(20), u16(0), u16(metodo), u16(0), u16(0),
      u32(crc), u32(corpo.length), u32(a.dados.length),
      u16(nome.length), u16(0)
    );
    var cabBuf = new Uint8Array(cab.length + nome.length);
    cabBuf.set(cab, 0); cabBuf.set(nome, cab.length);
    partes.push(cabBuf, corpo);

    var cen = [].concat(
      u32(0x02014b50), u16(20), u16(20), u16(0), u16(metodo), u16(0), u16(0),
      u32(crc), u32(corpo.length), u32(a.dados.length),
      u16(nome.length), u16(0), u16(0), u16(0), u16(0), u32(0), u32(desloc)
    );
    var cenBuf = new Uint8Array(cen.length + nome.length);
    cenBuf.set(cen, 0); cenBuf.set(nome, cen.length);
    central.push(cenBuf);
    desloc += cabBuf.length + corpo.length;
  });

  var tamCentral = central.reduce(function (t, c) { return t + c.length; }, 0);
  var fim = new Uint8Array([].concat(
    u32(0x06054b50), u16(0), u16(0),
    u16(arquivos.length), u16(arquivos.length),
    u32(tamCentral), u32(desloc), u16(0)
  ));

  var total = partes.reduce(function (t, x) { return t + x.length; }, 0) + tamCentral + fim.length;
  var out = new Uint8Array(total), o = 0;
  partes.forEach(function (x) { out.set(x, o); o += x.length; });
  central.forEach(function (x) { out.set(x, o); o += x.length; });
  out.set(fim, o);
  return out;
}


/* ---------- conferencia da malha ---------- */
function ferAnalisar() {
  var pecas = ferMalhasIndexadas();
  if (!pecas.length) return null;
  var linhas = [], total = {
    abertas: 0, naoManifold: 0, invertidas: 0, degeneradas: 0,
    duplicadas: 0, soltos: 0, autoInt: 0, fechadas: 0
  };
  var minEsp = Infinity, criticas = 0;
  pecas.forEach(function (p) {
    var m = (FER.reparadas && FER.reparadas[p.nome]) ? FER.reparadas[p.nome] : p.malha;
    var v = MALHA.validar(m, { limiteTri: 60000, maxRelatar: 20 });
    var e = null;
    try { e = MALHA.espessuraMinima(m, 220); } catch (err) { e = null; }
    if (e && e.minimaMM < minEsp) minEsp = e.minimaMM;
    if (e) criticas += e.criticas;
    total.abertas += v.abertas;
    total.naoManifold += v.naoManifold;
    total.invertidas += v.invertidas;
    total.degeneradas += v.degeneradas;
    total.duplicadas += v.duplicadas;
    total.soltos += v.soltos;
    if (v.autoInterseccoes > 0) total.autoInt += v.autoInterseccoes;
    if (v.fechada) total.fechadas++;
    linhas.push({ nome: p.rotulo, v: v, esp: e });
  });
  var cx = null;
  pecas.forEach(function (p) {
    var m = (FER.reparadas && FER.reparadas[p.nome]) ? FER.reparadas[p.nome] : p.malha;
    var c = MALHA.caixa(m);
    if (!c) return;
    if (!cx) cx = { x0: c.x0, y0: c.y0, z0: c.z0, x1: c.x1, y1: c.y1, z1: c.z1 };
    else {
      cx.x0 = Math.min(cx.x0, c.x0); cx.y0 = Math.min(cx.y0, c.y0); cx.z0 = Math.min(cx.z0, c.z0);
      cx.x1 = Math.max(cx.x1, c.x1); cx.y1 = Math.max(cx.y1, c.y1); cx.z1 = Math.max(cx.z1, c.z1);
    }
  });
  FER.diag = {
    linhas: linhas, total: total, pecas: pecas.length,
    espessura: isFinite(minEsp) ? minEsp : null, criticas: criticas,
    caixa: cx ? { dx: cx.x1 - cx.x0, dy: cx.y1 - cx.y0, dz: cx.z1 - cx.z0 } : null,
    tudoOk: total.fechadas === pecas.length && total.autoInt === 0
  };
  return FER.diag;
}

function ferReparar() {
  var pecas = ferMalhasIndexadas();
  if (!pecas.length) return;
  FER.reparadas = FER.reparadas || {};
  var passos = [];
  pecas.forEach(function (p) {
    var base = FER.reparadas[p.nome] || p.malha;
    var r = MALHA.reparar(base);
    FER.reparadas[p.nome] = r.malha;
    if (r.passos.length) passos.push(p.rotulo + ': ' + r.passos.join(', '));
  });
  FER.reparoPassos = passos;
  ferAnalisar();
  ferPintarInfo();
}

function ferDiagHTML() {
  var d = FER.diag;
  if (!d) {
    return '<div class="fer-diag"><button type="button" class="btn ghost" id="fer_analisar">'
      + 'Analisar malha</button>'
      + '<span class="u"> confere topologia, espessura e se o arquivo está pronto pro fatiador</span></div>';
  }
  var t = d.total;
  function linha(rot, val, bom) {
    return '<div class="' + (bom ? 'bom' : 'ruim') + '"><span>' + esc(rot) + '</span><b>' +
           esc(String(val)) + '</b></div>';
  }
  var h = '<div class="fer-diag">';
  h += '<div class="fer-rot">Integridade da malha</div>';
  h += '<div class="fer-diaglista">';
  h += linha('Malha fechada', d.total.fechadas + ' de ' + d.pecas, d.total.fechadas === d.pecas);
  h += linha('Arestas abertas', t.abertas, t.abertas === 0);
  h += linha('Non-manifold', t.naoManifold, t.naoManifold === 0);
  h += linha('Faces invertidas', t.invertidas, t.invertidas === 0);
  h += linha('Faces degeneradas', t.degeneradas, t.degeneradas === 0);
  h += linha('Faces repetidas', t.duplicadas, t.duplicadas === 0);
  h += linha('Auto-interseções', t.autoInt, t.autoInt === 0);
  h += linha('Objetos soltos', t.soltos, true);
  h += '</div>';
  h += '<div class="fer-rot" style="margin-top:12px">Impressão</div>';
  h += '<div class="fer-diaglista">';
  h += linha('Espessura mínima',
             d.espessura != null ? d.espessura.toFixed(2) + ' mm' : '—',
             d.espessura == null || d.espessura >= 0.8);
  h += linha('Regiões críticas', d.criticas, d.criticas === 0);
  if (d.caixa) {
    h += linha('Dimensão total',
      d.caixa.dx.toFixed(1) + ' × ' + d.caixa.dy.toFixed(1) + ' × ' + d.caixa.dz.toFixed(1) + ' mm', true);
  }
  h += linha('Peças', d.pecas, true);
  h += '</div>';

  if (FER.reparoPassos && FER.reparoPassos.length) {
    h += '<div class="fer-nota" style="margin-top:10px"><b>Reparo:</b> '
       + esc(FER.reparoPassos.join(' · ')) + '</div>';
  } else if (FER.reparoPassos) {
    h += '<div class="fer-nota" style="margin-top:10px">Reparo rodou e não achou nada pra corrigir.</div>';
  }

  h += '<div class="fer-diagbot">';
  h += '<button type="button" class="btn ghost" id="fer_analisar">Analisar de novo</button>';
  if (!d.tudoOk) {
    h += '<button type="button" class="btn primary" id="fer_reparar">Reparar malha</button>';
  }
  h += '</div>';
  h += '</div>';
  return h;
}

/* ---------- downloads ---------- */
function ferBaixar(conteudo, nome, tipo) {
  var blob = (conteudo instanceof ArrayBuffer)
    ? new Blob([conteudo], { type: tipo })
    : new Blob([conteudo], { type: tipo + ';charset=utf-8' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url; a.download = nome;
  document.body.appendChild(a); a.click();
  setTimeout(function () { document.body.removeChild(a); URL.revokeObjectURL(url); }, 400);
}

function ferNomeBase() {
  var n = (FER.nomeArquivo || 'peca').replace(/[^\wÀ-ÿ -]/g, '').trim() || 'peca';
  return n.replace(/\s+/g, '-').toLowerCase().slice(0, 32);
}

function ferBaixarSVG() {
  if (!FER.peca) return;
  ferBaixar(MODELOS.svg(FER.peca), ferNomeBase() + '.svg', 'image/svg+xml');
}

function ferNomePeca(nome, i) {
  if (nome === 'base') return (i + 1) + '-base';
  if (nome === 'desenho') return (i + 1) + '-desenho';
  return (i + 1) + '-cor' + nome.replace('cor', '');
}

function ferBaixarSTL() {
  if (!FER.peca || !FER.malhas) return;
  var nomeE = ferNomeBase();
  var separarE = ferLigado('fer_separar');
  var pecasE = ferPecasParaEstudio();
  // pelo motor novo: cada peça sai como sólido único (sem faces internas)
  carregarEstudio().then(function (E) { return E.exportarSTLGerador(pecasE, nomeE, separarE && pecasE.length > 1); })
    .catch(function (e) { console.warn('STL pelo caminho antigo:', e); ferBaixarSTLAntigo(); });
}
function ferBaixarSTLAntigo() {
  if (!FER.peca || !FER.malhas) return;
  var nome = ferNomeBase();
  var idx = ferMalhasIndexadas();
  var pecas = idx.map(function (p) {
    var m = (FER.reparadas && FER.reparadas[p.nome]) ? FER.reparadas[p.nome] : p.malha;
    return { nome: p.nome, cor: p.cor, tris: MALHA.paraTris(m) };
  });
  if (!pecas.length) return;

  var separar = ferLigado('fer_separar') && pecas.length > 1;
  if (!separar) {
    var tudo = [];
    pecas.forEach(function (p) { tudo = tudo.concat(p.tris); });
    ferBaixar(GEO.stlBinario(tudo, nome), nome + '.stl', 'model/stl');
    return;
  }

  var arquivos = pecas.map(function (p, i) {
    var buf = GEO.stlBinario(p.tris, nome + '-' + p.nome);
    return { nome: nome + '-' + ferNomePeca(p.nome, i) + '.stl', dados: new Uint8Array(buf) };
  });
  ferZipAsync(arquivos).then(function (zip) {
    ferBaixar(zip.buffer.slice(zip.byteOffset, zip.byteOffset + zip.byteLength),
              nome + '-stl.zip', 'application/zip');
  });
}


/* ---------- 3MF: um arquivo só, com as peças no lugar e com cor ---------- */
/* Malha indexada de cada peca, em mm. Cacheada por recalculo.             */
function ferMalhasIndexadas() {
  if (FER.indexCache && FER.indexCacheMarca === FER.marca) return FER.indexCache;
  var pecas = (FER.malhas && FER.malhas.pecas) || [];
  var out = pecas.map(function (p) {
    return {
      nome: p.nome,
      rotulo: ferRotuloPeca(p),
      corBase: p.cor,                 // cor detectada; a escolhida resolve na hora
      get cor() { return ferCorDe(this.nome, this.corBase); },
      malha: MALHA.indexar(p.tris)
    };
  });
  FER.indexCache = out;
  FER.indexCacheMarca = FER.marca;
  return out;
}

function ferRotuloPeca(p) {
  if (p.nome === 'base') return 'Base';
  if (p.nome === 'desenho') return 'Desenho';
  return (FER.detalhe === 'relevo' ? 'Nivel ' : 'Cor ') + p.nome.replace('cor', '');
}

/* ---------- Estúdio 3D (estudio3d.js, carregado só quando precisa) ---------- */
var _estudioCarregando = null;
function carregarEstudio() {
  if (window.Estudio3D) return Promise.resolve(window.Estudio3D);
  if (!_estudioCarregando) {
    _estudioCarregando = new Promise(function (resolve, reject) {
      var s = document.createElement('script');
      s.src = 'estudio3d.js';
      s.onload = function () { window.Estudio3D ? resolve(window.Estudio3D) : reject(new Error('estudio3d.js não iniciou')); };
      s.onerror = function () { reject(new Error('O arquivo estudio3d.js não está na pasta do sistema.')); };
      document.head.appendChild(s);
    });
    _estudioCarregando.catch(function () { _estudioCarregando = null; });
  }
  return _estudioCarregando;
}

// peças do gerador no formato do Estúdio: {nome, cor '#hex', malha {pos, idx}}
function ferPecasParaEstudio() {
  return ferMalhasIndexadas().map(function (p) {
    var m = (FER.reparadas && FER.reparadas[p.nome]) ? FER.reparadas[p.nome] : p.malha;
    return { nome: p.rotulo, cor: ferRGBParaHex(p.cor).toUpperCase(), malha: { pos: m.pos, idx: m.idx } };
  });
}

// 3MF pelo motor novo: cor no formato que o Bambu Studio lê (m:colorgroup)
// e cada peça como sólido único (o bolso da tag não deixa mais faces internas)
function ferBaixar3MF() {
  if (!FER.peca || !FER.malhas) return;
  var pecas = ferPecasParaEstudio();
  if (!pecas.length) return;
  var nome = ferNomeBase();
  var bt = document.getElementById('fer_3mf');
  if (bt) bt.disabled = true;
  carregarEstudio()
    .then(function (E) { return E.exportar3MFGerador(pecas, nome); })
    .then(function () { toast('3MF gerado — no Bambu Studio confirme as cores e dê OK', 'ok'); })
    .catch(function (e) { console.error(e); toast('Não consegui gerar o 3MF: ' + (e.message || e), 'warn'); })
    .then(function () { if (bt) bt.disabled = false; });
}

function ferAbrirNoEstudio() {
  if (!FER.peca || !FER.malhas) return;
  var pecas = ferPecasParaEstudio();
  var nome = FER.nomeArquivo || 'Chaveiro';
  ferModoFerramentas('estudio').then(function (E) {
    return E.abrirDoGerador(pecas, nome);
  }).catch(function (e) { console.error(e); toast('Não consegui abrir no Estúdio: ' + (e.message || e), 'warn'); });
}

function ferModoFerramentas(modo) {
  var ger = document.getElementById('ferr_gerador');
  var est = document.getElementById('ferr_estudio');
  var txt = document.getElementById('ferr_modo_texto');
  ferMarcarSeg('ferr_modo_seg', modo);
  if (modo !== 'estudio') {
    if (ger) ger.style.display = '';
    if (est) est.style.display = 'none';
    if (txt) txt.textContent = 'Transforma imagem, texto ou forma em peça pronta pra imprimir: chaveiro, medalha, placa ou só o contorno. Baixa em 3MF (com as cores), SVG e STL. Nada fica salvo — é só gerar e baixar.';
    return Promise.resolve(null);
  }
  if (ger) ger.style.display = 'none';
  if (est) est.style.display = '';
  if (txt) txt.textContent = 'Abra modelos STL, OBJ ou 3MF (inclusive gerados por IA), confira e repare a malha, separe detalhes em peças independentes, corte com encaixe, ponha texto na frente e no verso e exporte pro Bambu Studio com as cores certas. Nada fica salvo no sistema.';
  if (est && !est.childNodes.length) est.innerHTML = '<div class="card"><p class="u">Carregando o Estúdio 3D…</p></div>';
  return carregarEstudio().then(function (E) {
    if (est && est.querySelector('.card') && !est.querySelector('.e3d')) est.innerHTML = '';
    E.montar(est);
    return E;
  }).catch(function (e) {
    if (est) est.innerHTML = '<div class="card"><div class="fer-erro" style="display:block">' + esc(e.message || String(e)) + ' Coloque o estudio3d.js junto com o app.js.</div></div>';
    throw e;
  });
}

/* Compacta de verdade quando o navegador tem CompressionStream.             */
function ferComprimir(dados) {
  if (typeof CompressionStream === 'undefined') return Promise.resolve(null);
  try {
    var cs = new CompressionStream('deflate-raw');
    var w = cs.writable.getWriter();
    w.write(dados); w.close();
    return new Response(cs.readable).arrayBuffer()
      .then(function (b) { return new Uint8Array(b); })
      .catch(function () { return null; });
  } catch (e) { return Promise.resolve(null); }
}

/* ---------- montagem da tela ---------- */
function ferTrocarModo(modo) {
  FER.modo = modo;
  ['imagem', 'texto', 'forma'].forEach(function (m) {
    var el = document.getElementById('fer_ent_' + m);
    if (el) el.style.display = (m === modo) ? '' : 'none';
  });
  var ajus = document.getElementById('fer_ajustes_img');
  if (ajus) ajus.style.display = (modo === 'imagem') ? '' : 'none';
  if (modo !== 'imagem') { ferMarcarSeg('fer_detalhe_seg', 'chapado'); ferAtualizarDetalhe(); }
  if (modo === 'texto') ferDesenharTexto();
  else if (modo === 'forma') {
    var sel = document.querySelector('#fer_formas .fer-forma.active');
    ferDesenharForma(sel ? sel.dataset.f : 'circulo');
  } else {
    FER.origem = FER.fontes.imagem || null;
    if (FER.origem) { ferRecalcular(0); }
    else { FER.peca = null; FER.malhas = null; ferAviso(''); ferPintarTudo(); }
  }
}

var FER_DICAS = {
  chapado: 'Uma altura só. Bom pra logo e desenho de traço.',
  cor: 'Separa pelas cores da própria imagem. Todas na mesma altura, uma cor cada.',
  relevo: 'Lê os tons da imagem e vira degraus de altura. É assim que sai medalha e brasão com o desenho em relevo.'
};

function ferTrocarVisor(qual) {
  FER.visor = qual || '3d';
  var c3 = document.getElementById('fer_cv3d');
  var c2 = document.getElementById('fer_cv2d');
  var bt = document.getElementById('fer_vistas_3d');
  var dica = document.querySelector('.fer-dica-girar');
  if (c3) c3.style.display = (FER.visor === '3d') ? '' : 'none';
  if (c2) c2.style.display = (FER.visor === '2d') ? '' : 'none';
  if (bt) bt.style.visibility = (FER.visor === '3d') ? '' : 'hidden';
  if (dica) dica.style.display = (FER.visor === '3d') ? '' : 'none';
  ferPintarTudo();
}

function ferAtualizarDetalhe() {
  var d = ferSeg('fer_detalhe_seg') || 'chapado';
  var lin = document.getElementById('fer_lin_niveis');
  if (lin) lin.style.display = (d === 'chapado') ? 'none' : '';
  var inv = document.getElementById('fer_lin_relevo_inv');
  if (inv) inv.style.display = (d === 'relevo') ? '' : 'none';
  var rot = document.getElementById('fer_rot_niveis');
  if (rot) rot.textContent = (d === 'relevo') ? 'Quantos níveis de altura' : 'Quantas cores';
  var dica = document.getElementById('fer_detalhe_dica');
  if (dica) dica.textContent = FER_DICAS[d] || '';
  // por cor o limite util e 4; em relevo vai ate 6
  var seg = document.getElementById('fer_niveis_seg');
  if (seg) {
    seg.querySelectorAll('button').forEach(function (b) {
      var n = parseInt(b.dataset.v, 10);
      var liberado = (d === 'relevo') || n <= 4;
      b.disabled = !liberado;
      b.style.display = liberado ? '' : 'none';
      if (!liberado && b.classList.contains('active')) {
        ferMarcarSeg('fer_niveis_seg', '4');
      }
    });
  }
}

function ferAtualizarCamposModelo() {
  var modelo = ferSeg('fer_modelo_seg') || 'chaveiro';
  var temBase = modelo !== 'contorno';
  var mostrar = function (id, cond) {
    var el = document.getElementById(id);
    if (el) el.style.display = cond ? '' : 'none';
  };
  mostrar('fer_lin_borda', temBase);
  mostrar('fer_lin_argola', temBase);
  mostrar('fer_lin_arte', temBase && !ferLigado('fer_vazada'));
  mostrar('fer_lin_vazada', temBase);
  mostrar('fer_lin_canto', modelo === 'placa');
  mostrar('fer_lin_argola_ops', temBase && ferLigado('fer_argola'));
  mostrar('fer_lin_nfc', temBase);
  mostrar('fer_lin_nfc_ops', temBase && ferLigado('fer_nfc'));
  var rot = document.getElementById('fer_rot_altbase');
  if (rot) rot.textContent = temBase ? 'Altura da base' : 'Espessura';
}

function renderFerramentas() {
  if (FER.montado) {
    ferAtualizarCamposModelo(); ferPintarTudo();
    if (window.Estudio3D && window.Estudio3D.estudio) window.Estudio3D.estudio.visor.redimensionar();
    return;
  }
  FER.montado = true;

  // fontes disponíveis
  var selF = document.getElementById('fer_fonte');
  if (selF && !selF.options.length) {
    selF.innerHTML = FER_FONTES.map(function (f) {
      return '<option value="' + esc(f[1]) + '">' + esc(f[0]) + '</option>';
    }).join('');
  }
  // formas
  var boxF = document.getElementById('fer_formas');
  if (boxF && !boxF.children.length) {
    boxF.innerHTML = FER_FORMAS.map(function (f, i) {
      return '<button type="button" class="fer-forma' + (i === 0 ? ' active' : '') +
             '" data-f="' + f[0] + '" title="' + esc(f[1]) + '">' +
             '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="' + f[2] + '"/></svg>' +
             '<span>' + esc(f[1]) + '</span></button>';
    }).join('');
    boxF.onclick = function (ev) {
      var b = ev.target.closest('.fer-forma');
      if (!b) return;
      boxF.querySelectorAll('.fer-forma').forEach(function (x) { x.classList.remove('active'); });
      b.classList.add('active');
      ferDesenharForma(b.dataset.f);
    };
  }

  ferBindSeg('fer_entrada_seg', ferTrocarModo);
  ferBindSeg('fer_modelo_seg', function () { ferAtualizarCamposModelo(); ferRecalcular(0); });
  ferBindSeg('fer_argola_seg', function () { ferRecalcular(0); });
  ferBindSeg('fer_recorte_seg', function (v) {
    if (v === 'auto') {
      var sl = document.getElementById('fer_limiar');
      if (sl && FER.limiarAuto != null) sl.value = FER.limiarAuto;
    }
    ferRecalcular(0);
  });
  ferBindSeg('fer_detalhe_seg', function () { ferAtualizarDetalhe(); ferRecalcular(0); });
  ferBindSeg('fer_niveis_seg', function () { ferRecalcular(0); });
  ferBindSeg('fer_nfc_seg', function () { ferRecalcular(0); });

  // arquivo
  var inp = document.getElementById('fer_arquivo');
  if (inp) inp.onchange = function () { ferCarregarArquivo(this.files && this.files[0]); this.value = ''; };
  var drop = document.getElementById('fer_drop');
  if (drop) {
    drop.onclick = function () { if (inp) inp.click(); };
    ['dragenter', 'dragover'].forEach(function (e) {
      drop.addEventListener(e, function (ev) {
        ev.preventDefault(); drop.classList.add('sobre');
      });
    });
    ['dragleave', 'drop'].forEach(function (e) {
      drop.addEventListener(e, function (ev) {
        ev.preventDefault(); drop.classList.remove('sobre');
      });
    });
    drop.addEventListener('drop', function (ev) {
      var f = ev.dataTransfer && ev.dataTransfer.files && ev.dataTransfer.files[0];
      if (f) ferCarregarArquivo(f);
    });
  }

  // colar imagem
  if (!FER.colarLigado) {
    FER.colarLigado = true;
    document.addEventListener('paste', function (ev) {
      var view = document.getElementById('view-ferr');
      if (!view || !view.classList.contains('active')) return;
      if (FER.modo !== 'imagem') return;
      var it = (ev.clipboardData && ev.clipboardData.items) || [];
      for (var i = 0; i < it.length; i++) {
        if (it[i].type && it[i].type.indexOf('image') === 0) {
          ferCarregarArquivo(it[i].getAsFile());
          ev.preventDefault();
          return;
        }
      }
    });
  }

  // campos que recalculam
  ['fer_limiar', 'fer_suavizar', 'fer_sujeira', 'fer_tamanho', 'fer_altbase',
   'fer_altarte', 'fer_borda', 'fer_furo', 'fer_parede', 'fer_canto', 'fer_bico',
   'fer_nfc_diam', 'fer_nfc_prof']
  .forEach(function (id) {
    var el = document.getElementById(id);
    if (!el) return;
    el.oninput = function () {
      var eco = document.getElementById(id + '_eco');
      if (eco) eco.textContent = el.value;
      ferRecalcular();
    };
  });
  ['fer_inverter', 'fer_argola', 'fer_vazada', 'fer_nfc',
   'fer_relevo_inv', 'fer_fundo_dentro'].forEach(function (id) {
    var el = document.getElementById(id);
    if (el) el.onchange = function () { ferAtualizarCamposModelo(); ferRecalcular(0); };
  });
  var txt = document.getElementById('fer_texto');
  if (txt) txt.oninput = function () { clearTimeout(FER.tTexto); FER.tTexto = setTimeout(ferDesenharTexto, 140); };
  var fnt = document.getElementById('fer_fonte');
  if (fnt) fnt.onchange = ferDesenharTexto;

  var bs = document.getElementById('fer_svg'); if (bs) bs.onclick = ferBaixarSVG;
  var bEst = document.getElementById('fer_estudio'); if (bEst) bEst.onclick = ferAbrirNoEstudio;
  ferBindSeg('ferr_modo_seg', function (v) { ferModoFerramentas(v).catch(function () {}); });
  var bt = document.getElementById('fer_stl'); if (bt) bt.onclick = ferBaixarSTL;
  var b3 = document.getElementById('fer_3mf'); if (b3) b3.onclick = ferBaixar3MF;

  // girar o 3D com o mouse / dedo
  var cv3 = document.getElementById('fer_cv3d');
  if (cv3) {
    var pegar = function (ev) {
      var t = ev.touches ? ev.touches[0] : ev;
      return { x: t.clientX, y: t.clientY };
    };
    var comecar = function (ev) {
      FER.girando = pegar(ev);
      FER.girando.rx = FER.vista.rx; FER.girando.rz = FER.vista.rz;
    };
    var mover = function (ev) {
      if (!FER.girando) return;
      var p = pegar(ev);
      FER.vista.rz = FER.girando.rz + (p.x - FER.girando.x) * 0.012;
      FER.vista.rx = Math.max(0, Math.min(1.5708,
        FER.girando.rx + (p.y - FER.girando.y) * 0.012));
      ferPintar3D();
      if (ev.cancelable) ev.preventDefault();
    };
    var parar = function () { FER.girando = null; };
    cv3.addEventListener('mousedown', comecar);
    window.addEventListener('mousemove', mover);
    window.addEventListener('mouseup', parar);
    cv3.addEventListener('touchstart', comecar, { passive: true });
    cv3.addEventListener('touchmove', mover, { passive: false });
    cv3.addEventListener('touchend', parar);
    cv3.addEventListener('wheel', function (ev) {
      FER.vista.zoom = Math.max(0.35, Math.min(4, FER.vista.zoom * (ev.deltaY > 0 ? 0.9 : 1.1)));
      ferPintar3D();
      ev.preventDefault();
    }, { passive: false });
  }

  ferBindSeg('fer_vista_seg', function (v) { ferTrocarVisor(v); });
  var vt = document.getElementById('fer_vista_topo');
  if (vt) vt.onclick = function () { FER.vista.rx = 0; FER.vista.rz = 0; ferPintar3D(); };
  var vl = document.getElementById('fer_vista_lado');
  if (vl) vl.onclick = function () { FER.vista.rx = 0.95; FER.vista.rz = -0.42; ferPintar3D(); };

  ferTrocarVisor('3d');
  ferTrocarModo('imagem');
  ferAtualizarDetalhe();
  ferAtualizarCamposModelo();
  ferPintarTudo();
}

